writeNewRepair("omniflow-backend-patch/connector_api.py", "portal_kb_semantic.kick(tenant[\"client_id\"], \"tick\")", false,
    "\"\"\"\nOmniFlow Control Plane \u2014 CONNECTOR endpoints (shared channel queue).\n\nYe endpoints customer ke apne device (home laptop) par chalne wale connector\nke liye hain \u2014 server par WhatsApp session KABHI nahi chalta. Instagram\ncommands use the same queue and a server-side Meta Graph dispatch adapter.\nAuth: X-Omniflow-Key header = OMNIFLOW_SERVICE_KEY ya\nOMNIFLOW_ADMIN_API_KEY (wahi proven pattern jo admin endpoints use karte hain).\n\nConnector ka tenant resolve hota hai (pehla match jeeta):\n  1. Request body/query me explicit `client_id`\n  2. Backend env OMNIFLOW_CONNECTOR_USER_EMAIL -> platform_users lookup\n\nEndpoints:\n  POST /api/v1/connector/whatsapp/status          {state, phone?, account_name?, client_id?}\n  GET  /api/v1/connector/whatsapp/commands        ?limit=20  (pending, oldest first)\n  POST /api/v1/connector/whatsapp/commands/ack    {command_id, ok, note?, client_id?}\n  GET  /api/v1/connector/bot                      (tenant ka agent config)\n  POST /api/v1/connector/whatsapp/messages        {messages:[{from, body, name?, direction?}]}\n                                                  -> conversation upsert + message store\n\"\"\"\n\nimport logging\nimport os\nimport secrets\nimport threading\nimport time\nfrom datetime import datetime, timezone\nfrom typing import Any, Dict, Optional\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nimport portal_cod\nimport portal_contacts\nimport portal_sequences\n\n\nlogger = logging.getLogger(\"omniflow.connector-api\")\n\nbp = Blueprint(\"connector_api\", __name__, url_prefix=\"/api/v1/connector\")\n\nALLOWED_STATES = (\"disconnected\", \"connecting\", \"connected\")\n_TENANT_TTL_SECONDS = 300.0\n_tenant_lock = threading.Lock()\n_tenant_cache: Dict[str, Any] = {\"email\": None, \"value\": None, \"at\": 0.0}\n\n\ndef _authorized() -> bool:\n    key = request.headers.get(\"X-Omniflow-Key\", \"\")\n    if not key:\n        return False\n    accepted = [\n        os.environ.get(\"OMNIFLOW_SERVICE_KEY\"),\n        os.environ.get(\"OMNIFLOW_ADMIN_API_KEY\"),\n    ]\n    return any(k for k in accepted if k and secrets.compare_digest(key, k))\n\n\n@bp.before_request\ndef _guard():\n    if request.method == \"OPTIONS\":\n        return None\n    if not _authorized():\n        return jsonify({\"error\": {\"code\": \"forbidden\",\n                                  \"message\": \"Service key missing or invalid.\"}}), 403\n\n\ndef _resolve_tenant(explicit_client_id: Any) -> Optional[Dict[str, Any]]:\n    \"\"\"client_id (explicit > env email lookup). None = not configurable.\"\"\"\n    if isinstance(explicit_client_id, str) and explicit_client_id.strip().isdigit():\n        explicit_client_id = int(explicit_client_id.strip())\n    if isinstance(explicit_client_id, int) and not isinstance(explicit_client_id, bool) \\\n            and explicit_client_id > 0:\n        return {\"client_id\": explicit_client_id, \"user_id\": None, \"source\": \"request\"}\n\n    email = os.environ.get(\"OMNIFLOW_CONNECTOR_USER_EMAIL\", \"\").strip().lower()\n    if not email:\n        return None\n\n    now = time.time()\n    with _tenant_lock:\n        cached = (\n            _tenant_cache[\"email\"] == email\n            and _tenant_cache[\"value\"] is not None\n            and (now - float(_tenant_cache[\"at\"])) < _TENANT_TTL_SECONDS\n        )\n        if cached:\n            return dict(_tenant_cache[\"value\"])\n\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"SELECT id, client_id FROM \" + portal_db._q(portal_db.USERS_TABLE) +\n                \" WHERE \" + portal_db._q(portal_db.USER_EMAIL_COL) + \" = %s LIMIT 1\",\n                (email,),\n            )\n            found = portal_db.rows(cur)\n    finally:\n        conn.close()\n\n    if not found:\n        return None\n    tenant = {\"client_id\": found[0][\"client_id\"], \"user_id\": found[0][\"id\"], \"source\": \"env\"}\n    with _tenant_lock:\n        _tenant_cache.update({\"email\": email, \"value\": tenant, \"at\": now})\n    return dict(tenant)\n\n\ndef _tenant_or_error(explicit_client_id: Any):\n    try:\n        tenant = _resolve_tenant(explicit_client_id)\n    except Exception as error:\n        return None, (jsonify(portal_db.portal_unavailable(error, \"tenant resolve\")[0]), 503)\n    if tenant is None:\n        return None, (jsonify({\"error\": {\n            \"code\": \"connector_not_configured\",\n            \"message\": (\n                \"Connector tenant resolve nahi hua: body/query me client_id bhejein \"\n                \"ya backend par OMNIFLOW_CONNECTOR_USER_EMAIL set karein.\"\n            ),\n        }}), 503)\n    return tenant, None\n\n\ndef _json_body() -> Dict[str, Any]:\n    payload = request.get_json(silent=True)\n    return payload if isinstance(payload, dict) else {}\n\n\ndef _query_int(name: str, default: int, low: int, high: int) -> int:\n    raw = request.args.get(name, \"\")\n    try:\n        value = int(raw)\n    except (TypeError, ValueError):\n        return default\n    return max(low, min(high, value))\n\n\n@bp.post(\"/whatsapp/status\")\ndef report_status():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    state = payload.get(\"state\")\n    if state not in ALLOWED_STATES:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"state disconnected|connecting|connected hon.\"}}), 400\n    phone = payload.get(\"phone\")\n    phone = phone.strip() if isinstance(phone, str) else None\n    account_name = payload.get(\"account_name\")\n    account_name = account_name.strip() if isinstance(account_name, str) else None\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(portal_db.STATUS_TABLE) +\n                    \" (client_id, state, phone, account_name, last_seen_at,\"\n                    \" reported_by, updated_at) \"\n                    \"VALUES (%s, %s, %s, %s, NOW(), %s, NOW()) \"\n                    \"ON CONFLICT (client_id) DO UPDATE SET \"\n                    \" state = EXCLUDED.state,\"\n                    \" phone = EXCLUDED.phone,\"\n                    \" account_name = EXCLUDED.account_name,\"\n                    \" last_seen_at = EXCLUDED.last_seen_at,\"\n                    \" reported_by = EXCLUDED.reported_by,\"\n                    \" updated_at = NOW()\",\n                    (tenant[\"client_id\"], state, phone, account_name, tenant[\"user_id\"]),\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"wa status write\")[0]), 503\n\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.get(\"/whatsapp/commands\")\ndef list_commands():\n    args = request.args\n    tenant, error = _tenant_or_error(args.get(\"client_id\"))\n    if error:\n        return error\n    limit = _query_int(\"limit\", 20, 1, 50)\n    channel = (args.get(\"channel\") or \"\").strip()\n    if channel and channel not in ALLOWED_CHANNELS:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"channel whatsapp|telegram|instagram hon.\"}}), 400\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                try:\n                    import portal_growth\n\n                    portal_growth.materialize_due_broadcasts(cur, tenant[\"client_id\"], conn)\n                    import portal_digest\n\n                    portal_digest.materialize_due_digest(\n                        cur, tenant[\"client_id\"], conn\n                    )\n\n                    import portal_checkout\n\n                    portal_checkout.materialize_cart_reminders(\n                        cur, tenant[\"client_id\"], conn\n                    )\n\n                    try:\n                        import portal_bi\n                        portal_bi.materialize_weekly_problems(\n                            cur, tenant[\"client_id\"], conn\n                        )\n                    except Exception:\n                        pass\n\n                except Exception:\n                    pass\n                try:\n                    import portal_webhooks\n\n                    portal_webhooks.deliver_pending_webhooks(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_sequences\n\n                    portal_sequences.deliver_due_sequence_steps(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_workflows\n\n                    portal_workflows.run_due_workflows(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_kb_semantic\n\n                    # D1: throttled background top-up of the knowledge\n                    # semantic index (no-op when off or up to date).\n                    portal_kb_semantic.kick(tenant[\"client_id\"], \"tick\")\n                except Exception:\n                    pass\n                try:\n                    import portal_events\n\n                    portal_events.requeue_due_commands(\n                        cur, tenant[\"client_id\"]\n                    )\n                except Exception:\n                    pass\n                cmd_sql = (\n                    \"SELECT id, action, payload, created_at FROM \"\n                    + portal_db._q(portal_db.CMD_TABLE) +\n                    \" WHERE client_id = %s AND status = 'pending'\"\n                    \" AND (next_attempt_at IS NULL OR next_attempt_at <= NOW())\"\n                )\n                cmd_params: list = [tenant[\"client_id\"]]\n                if channel:\n                    cmd_sql += \" AND channel = %s\"\n                    cmd_params.append(channel)\n                cmd_sql += \" ORDER BY id ASC LIMIT %s\"\n                cmd_params.append(limit)\n                cur.execute(cmd_sql, tuple(cmd_params))\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"commands read\")[0]), 503\n\n    commands = []\n    for row in found:\n        created = row.get(\"created_at\")\n        if isinstance(created, datetime) and created.tzinfo is None:\n            created = created.replace(tzinfo=timezone.utc)\n        commands.append({\n            \"id\": row.get(\"id\"),\n            \"action\": row.get(\"action\"),\n            \"payload\": row.get(\"payload\") or {},\n            \"created_at\": created.isoformat() if isinstance(created, datetime) else None,\n        })\n    return jsonify({\"commands\": commands}), 200\n\n\n@bp.post(\"/whatsapp/commands/ack\")\ndef ack_command():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    command_id = payload.get(\"command_id\")\n    if isinstance(command_id, bool) or not isinstance(command_id, int) or command_id <= 0:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"command_id (positive int) zaroori hai.\"}}), 400\n    ok_flag = payload.get(\"ok\") is True\n    note = payload.get(\"note\")\n    note = note if isinstance(note, str) else None\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(portal_db.CMD_TABLE) +\n                    \" SET status = %s, result_note = %s, updated_at = NOW() \"\n                    \"WHERE id = %s AND client_id = %s RETURNING id\",\n                    (\"done\" if ok_flag else \"failed\", note, command_id, tenant[\"client_id\"]),\n                )\n                try:\n                    import portal_events\n\n                    portal_events.on_command_ack(\n                        cur,\n                        tenant[\"client_id\"],\n                        command_id,\n                        ok_flag,\n                        note,\n                        payload.get(\"provider_message_id\"),\n                    )\n                except Exception:\n                    pass\n                updated = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"command ack\")[0]), 503\n\n    if not updated:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Command nahi mili.\"}}), 404\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.get(\"/bot\")\ndef connector_bot_config():\n    tenant, error = _tenant_or_error(request.args.get(\"client_id\"))\n    if error:\n        return error\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT agent_name, tone, greeting, fallback,\"\n                    \" working_hours_enabled, working_hours_start, working_hours_end,\"\n                    \" human_handoff_enabled, updated_at\"\n                    \" FROM \" + portal_db._q(portal_db.BOT_TABLE) +\n                    \" WHERE client_id = %s\",\n                    (tenant[\"client_id\"],),\n                )\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"connector bot read\")[0]), 503\n\n    if not found:\n        return jsonify({\n            \"agent_name\": \"OmniFlow Assistant\",\n            \"tone\": \"friendly\",\n            \"greeting\": \"\",\n            \"fallback\": \"\",\n            \"working_hours_enabled\": False,\n            \"working_hours_start\": \"09:00\",\n            \"working_hours_end\": \"18:00\",\n            \"human_handoff_enabled\": False,\n            \"updated_at\": None,\n        }), 200\n\n    row = found[0]\n    updated = row.get(\"updated_at\")\n    if isinstance(updated, datetime) and updated.tzinfo is None:\n        updated = updated.replace(tzinfo=timezone.utc)\n    return jsonify({\n        \"agent_name\": row.get(\"agent_name\") or \"OmniFlow Assistant\",\n        \"tone\": row.get(\"tone\") if row.get(\"tone\") in (\"friendly\", \"professional\", \"concise\") else \"friendly\",\n        \"greeting\": row.get(\"greeting\") or \"\",\n        \"fallback\": row.get(\"fallback\") or \"\",\n        \"working_hours_enabled\": row.get(\"working_hours_enabled\") is True,\n        \"working_hours_start\": row.get(\"working_hours_start\") or \"09:00\",\n        \"working_hours_end\": row.get(\"working_hours_end\") or \"18:00\",\n        \"human_handoff_enabled\": row.get(\"human_handoff_enabled\") is True,\n        \"updated_at\": updated.isoformat() if isinstance(updated, datetime) else None,\n    }), 200\n\n\nMAX_INGEST_MESSAGES = 100\nALLOWED_DIRECTIONS = (\"in\", \"out\")\nALLOWED_CHANNELS = (\"whatsapp\", \"telegram\", \"instagram\")\n\n\n_AWAY_TABLE_READY = False\nAWAY_COOLDOWN_HOURS = 4\n_AWAY_DEFAULTS = {\n    \"enabled\": False,\n    \"timezone\": \"Asia/Karachi\",\n    \"days\": [\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n    ],\n    \"away_message\": \"\",\n}\n\n\ndef _ensure_away_table() -> None:\n    global _AWAY_TABLE_READY\n    if _AWAY_TABLE_READY:\n        return\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(\"portal_away_replies\") +\n                \" (id BIGSERIAL PRIMARY KEY, client_id BIGINT NOT NULL,\"\n                \" conversation_id BIGINT, contact_id TEXT NOT NULL,\"\n                \" body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending',\"\n                \" result_note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\"\n                \" sent_at TIMESTAMPTZ)\"\n            )\n            cur.execute(\n                \"CREATE INDEX IF NOT EXISTS portal_away_pending_idx ON \" +\n                portal_db._q(\"portal_away_replies\") +\n                \" (client_id, status, id)\"\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    _AWAY_TABLE_READY = True\n\n\ndef _load_business_hours(cur, client_id):\n    try:\n        cur.execute(\n            \"SELECT settings -> 'business_hours' AS business_hours FROM \" +\n            portal_db._q(\"client_settings\") +\n            \" WHERE client_id = %s\",\n            (client_id,),\n        )\n        rows = portal_db.rows(cur)\n    except Exception:\n        return _AWAY_DEFAULTS\n    stored = rows[0].get(\"business_hours\") if rows and rows[0] else None\n    return stored if isinstance(stored, dict) else _AWAY_DEFAULTS\n\n\ndef _away_closed_now(config) -> bool:\n    try:\n        from zoneinfo import ZoneInfo\n\n        days = config.get(\"days\")\n        if not isinstance(days, list) or len(days) != 7:\n            return False\n        now = datetime.now(ZoneInfo(str(config.get(\"timezone\") or \"UTC\")))\n        day = days[(now.weekday() + 1) % 7]\n        if not isinstance(day, dict) or day.get(\"enabled\") is not True:\n            return True\n        current = now.strftime(\"%H:%M\")\n        start = day.get(\"start\")\n        end = day.get(\"end\")\n        if not isinstance(start, str) or not isinstance(end, str):\n            return True\n        return not (start <= current <= end)\n    except Exception:\n        return False\n\n\ndef _maybe_enqueue_away_reply(client_id, conversation_id, contact_id, direction, conn) -> Optional[bool]:\n    \"\"\"Queue one automatic away reply, inside the ingest transaction.\n\n    Fires only for inbound messages while business hours are enabled and\n    currently closed, at most once per conversation per cooldown window.\n    Never raises into the caller: wrap in try/except there.\n    \"\"\"\n    if direction != \"in\":\n        return\n    with conn.cursor() as cur:\n        config = _load_business_hours(cur, client_id)\n        message = config.get(\"away_message\")\n        if (\n            config.get(\"enabled\") is not True\n            or not isinstance(message, str)\n            or not message.strip()\n        ):\n            return\n        if not _away_closed_now(config):\n            return\n        cur.execute(\n            \"SELECT 1 FROM \" + portal_db._q(\"portal_away_replies\") +\n            \" WHERE client_id = %s AND conversation_id = %s\"\n            \" AND created_at > NOW() - INTERVAL '\" +\n            str(AWAY_COOLDOWN_HOURS) + \" hours'\"\n            \" LIMIT 1\",\n            (client_id, conversation_id),\n        )\n        if portal_db.rows(cur):\n            return\n        try:\n            contact_lang = portal_contacts.stored_language(\n                cur, client_id, contact_id)\n        except Exception:\n            contact_lang = None\n        if contact_lang == \"ur\":\n            variant = config.get(\"away_message_ur\")\n        elif contact_lang == \"roman\":\n            variant = config.get(\"away_message_roman\")\n        else:\n            variant = None\n        if isinstance(variant, str) and variant.strip():\n            message = variant\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(\"portal_away_replies\") +\n            \" (client_id, conversation_id, contact_id, body)\"\n            \" VALUES (%s, %s, %s, %s)\",\n            (client_id, conversation_id, contact_id, message.strip()),\n        )\n        return True\n\n\n@bp.get(\"/away-replies\")\ndef list_due_away_replies():\n    args = request.args\n    tenant, error = _tenant_or_error(args.get(\"client_id\"))\n    if error:\n        return error\n    limit = _query_int(\"limit\", 5, 1, 20)\n\n    try:\n        _ensure_away_table()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT id, contact_id, body, created_at FROM \" +\n                    portal_db._q(\"portal_away_replies\") +\n                    \" WHERE client_id = %s AND status = 'pending'\"\n                    \" AND (next_attempt_at IS NULL OR next_attempt_at <= NOW())\"\n                    \" ORDER BY id ASC LIMIT %s\",\n                    (tenant[\"client_id\"], limit),\n                )\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"away replies read\")[0]), 503\n\n    replies = []\n    for row in found:\n        created = row.get(\"created_at\")\n        if isinstance(created, datetime) and created.tzinfo is None:\n            created = created.replace(tzinfo=timezone.utc)\n        replies.append({\n            \"id\": row.get(\"id\"),\n            \"external_user_id\": row.get(\"contact_id\"),\n            \"body\": row.get(\"body\"),\n            \"created_at\": created.isoformat() if isinstance(created, datetime) else None,\n        })\n    return jsonify({\"away_replies\": replies}), 200\n\n\n@bp.post(\"/away-replies/ack\")\ndef ack_away_reply():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    away_id = payload.get(\"away_id\")\n    if isinstance(away_id, bool) or not isinstance(away_id, int) or away_id <= 0:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"away_id (positive int) zaroori hai.\"}}), 400\n    ok_flag = payload.get(\"ok\") is True\n    note = payload.get(\"note\")\n    note = note if isinstance(note, str) else None\n\n    try:\n        _ensure_away_table()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(\"portal_away_replies\") +\n                    \" SET status = %s, result_note = %s, sent_at = NOW()\"\n                    \" WHERE id = %s AND client_id = %s AND status = 'pending' RETURNING id\",\n                    (\"sent\" if ok_flag else \"failed\", note, away_id, tenant[\"client_id\"]),\n                )\n                updated = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"away ack\")[0]), 503\n\n    if not updated:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Away reply nahi mili.\"}}), 404\n    return jsonify({\"ok\": True}), 200\n\n\nclass MessageValidationError(ValueError):\n    \"\"\"A connector payload failed the shared message contract.\"\"\"\n\n\nclass IngestRateLimited(Exception):\n    \"\"\"The tenant exceeded the shared inbound ingest limit.\"\"\"\n\n\nclass IngestFailure(Exception):\n    \"\"\"Wrap a persistence/automation failure for route-level JSON errors.\"\"\"\n\n    def __init__(self, original: Exception, operation: str):\n        super().__init__(str(original))\n        self.original = original\n        self.operation = operation\n\n\ndef normalize_messages(messages: Any, default_channel: str = \"whatsapp\",\n                        require_nonempty: bool = True):\n    \"\"\"Normalize provider-neutral messages for every channel adapter.\n\n    The returned records are deliberately the same records consumed by the\n    existing conversation, event, automation, compliance and audit engine.\n    Provider adapters may retain ``id``, ``media`` and ``postback`` metadata;\n    the core still uses the normalized ``from/body/name/direction/channel``\n    contract for conversation work.\n    \"\"\"\n    if not isinstance(messages, list) or (require_nonempty and not messages):\n        raise MessageValidationError(\n            \"messages (non-empty list) zaroori hai.\"\n            if require_nonempty else \"messages list zaroori hai.\"\n        )\n    if len(messages) > MAX_INGEST_MESSAGES:\n        raise MessageValidationError(\n            \"Aik request me max \" + str(MAX_INGEST_MESSAGES)\n            + \" messages bhejein.\"\n        )\n\n    normalized = []\n    for item in messages:\n        if not isinstance(item, dict):\n            raise MessageValidationError(\"Har message aik object ho.\")\n        sender = item.get(\"from\")\n        if not isinstance(sender, str) or not sender.strip():\n            raise MessageValidationError(\"Har message me 'from' zaroori hai.\")\n        body = item.get(\"body\")\n        if body is None:\n            body = \"\"\n        elif not isinstance(body, str):\n            body = str(body)\n        try:\n            import portal_interactive\n\n            reply_body = portal_interactive.interactive_body_override(\n                item.get(\"interactive\"), body\n            )\n            if reply_body is not None:\n                body = reply_body\n        except Exception:\n            pass\n        direction = item.get(\"direction\", \"in\")\n        if direction not in ALLOWED_DIRECTIONS:\n            raise MessageValidationError(\"direction in|out hon.\")\n        channel = item.get(\"channel\", default_channel)\n        if channel not in ALLOWED_CHANNELS:\n            raise MessageValidationError(\n                \"channel \" + \"|\".join(ALLOWED_CHANNELS) + \" hon.\"\n            )\n        name = item.get(\"name\")\n        name = name.strip() if isinstance(name, str) else None\n        record = {\n            \"from\": sender.strip(),\n            \"body\": body,\n            \"name\": name,\n            \"direction\": direction,\n            \"channel\": channel,\n        }\n        provider_id = item.get(\"id\")\n        if isinstance(provider_id, (str, int)) and str(provider_id).strip():\n            record[\"id\"] = str(provider_id).strip()\n        # Keep adapter metadata in the event/audit payload without making it\n        # part of the core conversation contract.\n        for key in (\"media\", \"postback\", \"timestamp\", \"provider\"):\n            if key in item and item[key] is not None:\n                record[key] = item[key]\n        normalized.append(record)\n    return normalized\n\n\ndef ingest_messages_for_tenant(tenant: Dict[str, Any], normalized) -> int:\n    \"\"\"Run the existing message engine for any normalized channel.\n\n    Instagram calls this function rather than creating a second conversation\n    or automation pipeline. One-reply, approvals, compliance, sequences,\n    workflows, intelligence and event idempotency all remain in this path.\n    \"\"\"\n    inserted = 0\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                try:\n                    import portal_ratelimit\n\n                    if not portal_ratelimit.allow(\n                        cur,\n                        \"ingest:\" + str(tenant[\"client_id\"]),\n                        portal_ratelimit.ingest_limit(),\n                        60,\n                    ):\n                        conn.commit()\n                        raise IngestRateLimited()\n                except IngestRateLimited:\n                    raise\n                except Exception:\n                    pass\n                for item in normalized:\n                    try:\n                        import portal_events\n\n                        if not portal_events.record_inbound(\n                            cur, tenant[\"client_id\"], item\n                        ):\n                            continue\n                    except Exception:\n                        pass\n                    if item[\"channel\"] == \"instagram\":\n                        try:\n                            import portal_identity\n\n                            identity_handle = item[\"from\"]\n                            if identity_handle.startswith(\"ig:\"):\n                                identity_handle = identity_handle[3:]\n                            portal_identity.resolve(\n                                cur,\n                                tenant[\"client_id\"],\n                                \"instagram\",\n                                identity_handle,\n                                item[\"name\"] or \"\",\n                                create=True,\n                                source=\"instagram_webhook\",\n                            )\n                        except Exception:\n                            pass\n                    cur.execute(\n                        \"INSERT INTO \" + portal_db._q(portal_db.CONV_TABLE) +\n                        \" (client_id, channel, contact_id, contact_name,\"\n                        \" status, last_message_preview, last_message_at,\"\n                        \" created_at, updated_at) \"\n                        \"VALUES (%s, %s, %s, %s, 'open', %s, NOW(), NOW(), NOW()) \"\n                        \"ON CONFLICT (client_id, channel, contact_id) DO UPDATE SET \"\n                        \" contact_name = COALESCE(EXCLUDED.contact_name,\"\n                        \" \" + portal_db._q(portal_db.CONV_TABLE) + \".contact_name), \"\n                        \" last_message_preview = EXCLUDED.last_message_preview, \"\n                        \" last_message_at = EXCLUDED.last_message_at, \"\n                        \" updated_at = NOW() \"\n                        \"RETURNING id\",\n                        (tenant[\"client_id\"], item[\"channel\"], item[\"from\"],\n                         item[\"name\"], item[\"body\"]),\n                    )\n                    conv = portal_db.rows(cur)\n                    conversation_id = conv[0][\"id\"] if conv else None\n                    cur.execute(\n                        \"INSERT INTO \" + portal_db._q(portal_db.MSGS_TABLE) +\n                        \" (conversation_id, client_id, direction, body,\"\n                        \" sender_name, status, created_at) \"\n                        \"VALUES (%s, %s, %s, %s, %s, %s, NOW())\",\n                        (conversation_id, tenant[\"client_id\"], item[\"direction\"],\n                         item[\"body\"], item[\"name\"],\n                         \"received\" if item[\"direction\"] == \"in\" else \"sent\"),\n                    )\n                    # One-reply law (B2): the first automation that sends a\n                    # customer-visible reply claims the message; the other\n                    # reply hooks stay quiet. Side-effect hooks (language\n                    # detection, compliance, listen, routing, sequences)\n                    # always run.\n                    claimed_by = None\n                    if claimed_by is None:\n                        try:\n                            import portal_approvals\n\n                            if portal_approvals.maybe_decide(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"approvals\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            if _maybe_enqueue_away_reply(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"away\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            if portal_cod.maybe_cod_flow(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"cod\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            import portal_brain\n\n                            if portal_brain.maybe_answer(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                conn,\n                            ):\n                                claimed_by = \"brain\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            import portal_kb\n                            import portal_intents\n\n                            import portal_llm\n\n                            with portal_llm.usage_scope(\n                                    \"intent\", tenant[\"client_id\"]):\n                                intent = portal_intents.classify(item[\"body\"])\n                            if portal_kb.maybe_auto_reply(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                intent,\n                                conn,\n                            ):\n                                claimed_by = \"kb\"\n                        except Exception:\n                            pass\n                    if claimed_by:\n                        try:\n                            import portal_events\n\n                            portal_events.note_claim(\n                                cur, tenant[\"client_id\"], item, claimed_by\n                            )\n                        except Exception:\n                            pass\n                    try:\n                        portal_contacts.maybe_detect_language(\n                            tenant[\"client_id\"],\n                            item[\"from\"],\n                            item[\"body\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    if item[\"direction\"] == \"in\":\n                        try:\n                            import portal_compliance\n\n                            portal_compliance.maybe_opt_out(\n                                tenant[\"client_id\"],\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_listen\n\n                            portal_listen.maybe_listen(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_routing\n\n                            portal_routing.maybe_route(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_intelligence\n\n                            portal_intelligence.maybe_analyze(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_approvals\n\n                            portal_approvals.maybe_request(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                    try:\n                        portal_sequences.maybe_enroll_new_contact(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        portal_sequences.maybe_enroll_keyword(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            item[\"body\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        portal_sequences.maybe_auto_pause_replies(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        import portal_workflows\n\n                        portal_workflows.maybe_trigger_message(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            item[\"body\"],\n                            item[\"direction\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        import portal_events\n\n                        portal_events.mark_inbound_done(\n                            cur, tenant[\"client_id\"], item\n                        )\n                    except Exception:\n                        pass\n                    inserted += 1\n            conn.commit()\n        finally:\n            conn.close()\n    except IngestRateLimited:\n        raise\n    except Exception as error:\n        raise IngestFailure(error, \"messages ingest\") from error\n    return inserted\n\n\n@bp.post(\"/whatsapp/messages\")\ndef ingest_whatsapp_messages():\n    \"\"\"Store connector-delivered messages through the shared channel engine.\"\"\"\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n    try:\n        normalized = normalize_messages(\n            payload.get(\"messages\"), default_channel=\"whatsapp\"\n        )\n    except MessageValidationError as error:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": str(error)}}), 400\n\n    try:\n        inserted = ingest_messages_for_tenant(tenant, normalized)\n    except IngestRateLimited:\n        return jsonify({\"error\": {\n            \"code\": \"rate_limited\",\n            \"message\": \"Too many messages; slow down.\",\n        }}), 429\n    except IngestFailure as failure:\n        return jsonify(portal_db.portal_unavailable(\n            failure.original, failure.operation)[0]), 503\n\n    logger.info(\"whatsapp messages ingested client_id=%s count=%s\",\n                tenant[\"client_id\"], inserted)\n    return jsonify({\"ok\": True, \"inserted\": inserted}), 200\n\n");
writeNewRepair("OmniFlow-Control-Plane/connector_api.py", "portal_kb_semantic.kick(tenant[\"client_id\"], \"tick\")", true,
    "\"\"\"\nOmniFlow Control Plane \u2014 CONNECTOR endpoints (shared channel queue).\n\nYe endpoints customer ke apne device (home laptop) par chalne wale connector\nke liye hain \u2014 server par WhatsApp session KABHI nahi chalta. Instagram\ncommands use the same queue and a server-side Meta Graph dispatch adapter.\nAuth: X-Omniflow-Key header = OMNIFLOW_SERVICE_KEY ya\nOMNIFLOW_ADMIN_API_KEY (wahi proven pattern jo admin endpoints use karte hain).\n\nConnector ka tenant resolve hota hai (pehla match jeeta):\n  1. Request body/query me explicit `client_id`\n  2. Backend env OMNIFLOW_CONNECTOR_USER_EMAIL -> platform_users lookup\n\nEndpoints:\n  POST /api/v1/connector/whatsapp/status          {state, phone?, account_name?, client_id?}\n  GET  /api/v1/connector/whatsapp/commands        ?limit=20  (pending, oldest first)\n  POST /api/v1/connector/whatsapp/commands/ack    {command_id, ok, note?, client_id?}\n  GET  /api/v1/connector/bot                      (tenant ka agent config)\n  POST /api/v1/connector/whatsapp/messages        {messages:[{from, body, name?, direction?}]}\n                                                  -> conversation upsert + message store\n\"\"\"\n\nimport logging\nimport os\nimport secrets\nimport threading\nimport time\nfrom datetime import datetime, timezone\nfrom typing import Any, Dict, Optional\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nimport portal_cod\nimport portal_contacts\nimport portal_sequences\n\n\nlogger = logging.getLogger(\"omniflow.connector-api\")\n\nbp = Blueprint(\"connector_api\", __name__, url_prefix=\"/api/v1/connector\")\n\nALLOWED_STATES = (\"disconnected\", \"connecting\", \"connected\")\n_TENANT_TTL_SECONDS = 300.0\n_tenant_lock = threading.Lock()\n_tenant_cache: Dict[str, Any] = {\"email\": None, \"value\": None, \"at\": 0.0}\n\n\ndef _authorized() -> bool:\n    key = request.headers.get(\"X-Omniflow-Key\", \"\")\n    if not key:\n        return False\n    accepted = [\n        os.environ.get(\"OMNIFLOW_SERVICE_KEY\"),\n        os.environ.get(\"OMNIFLOW_ADMIN_API_KEY\"),\n    ]\n    return any(k for k in accepted if k and secrets.compare_digest(key, k))\n\n\n@bp.before_request\ndef _guard():\n    if request.method == \"OPTIONS\":\n        return None\n    if not _authorized():\n        return jsonify({\"error\": {\"code\": \"forbidden\",\n                                  \"message\": \"Service key missing or invalid.\"}}), 403\n\n\ndef _resolve_tenant(explicit_client_id: Any) -> Optional[Dict[str, Any]]:\n    \"\"\"client_id (explicit > env email lookup). None = not configurable.\"\"\"\n    if isinstance(explicit_client_id, str) and explicit_client_id.strip().isdigit():\n        explicit_client_id = int(explicit_client_id.strip())\n    if isinstance(explicit_client_id, int) and not isinstance(explicit_client_id, bool) \\\n            and explicit_client_id > 0:\n        return {\"client_id\": explicit_client_id, \"user_id\": None, \"source\": \"request\"}\n\n    email = os.environ.get(\"OMNIFLOW_CONNECTOR_USER_EMAIL\", \"\").strip().lower()\n    if not email:\n        return None\n\n    now = time.time()\n    with _tenant_lock:\n        cached = (\n            _tenant_cache[\"email\"] == email\n            and _tenant_cache[\"value\"] is not None\n            and (now - float(_tenant_cache[\"at\"])) < _TENANT_TTL_SECONDS\n        )\n        if cached:\n            return dict(_tenant_cache[\"value\"])\n\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"SELECT id, client_id FROM \" + portal_db._q(portal_db.USERS_TABLE) +\n                \" WHERE \" + portal_db._q(portal_db.USER_EMAIL_COL) + \" = %s LIMIT 1\",\n                (email,),\n            )\n            found = portal_db.rows(cur)\n    finally:\n        conn.close()\n\n    if not found:\n        return None\n    tenant = {\"client_id\": found[0][\"client_id\"], \"user_id\": found[0][\"id\"], \"source\": \"env\"}\n    with _tenant_lock:\n        _tenant_cache.update({\"email\": email, \"value\": tenant, \"at\": now})\n    return dict(tenant)\n\n\ndef _tenant_or_error(explicit_client_id: Any):\n    try:\n        tenant = _resolve_tenant(explicit_client_id)\n    except Exception as error:\n        return None, (jsonify(portal_db.portal_unavailable(error, \"tenant resolve\")[0]), 503)\n    if tenant is None:\n        return None, (jsonify({\"error\": {\n            \"code\": \"connector_not_configured\",\n            \"message\": (\n                \"Connector tenant resolve nahi hua: body/query me client_id bhejein \"\n                \"ya backend par OMNIFLOW_CONNECTOR_USER_EMAIL set karein.\"\n            ),\n        }}), 503)\n    return tenant, None\n\n\ndef _json_body() -> Dict[str, Any]:\n    payload = request.get_json(silent=True)\n    return payload if isinstance(payload, dict) else {}\n\n\ndef _query_int(name: str, default: int, low: int, high: int) -> int:\n    raw = request.args.get(name, \"\")\n    try:\n        value = int(raw)\n    except (TypeError, ValueError):\n        return default\n    return max(low, min(high, value))\n\n\n@bp.post(\"/whatsapp/status\")\ndef report_status():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    state = payload.get(\"state\")\n    if state not in ALLOWED_STATES:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"state disconnected|connecting|connected hon.\"}}), 400\n    phone = payload.get(\"phone\")\n    phone = phone.strip() if isinstance(phone, str) else None\n    account_name = payload.get(\"account_name\")\n    account_name = account_name.strip() if isinstance(account_name, str) else None\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(portal_db.STATUS_TABLE) +\n                    \" (client_id, state, phone, account_name, last_seen_at,\"\n                    \" reported_by, updated_at) \"\n                    \"VALUES (%s, %s, %s, %s, NOW(), %s, NOW()) \"\n                    \"ON CONFLICT (client_id) DO UPDATE SET \"\n                    \" state = EXCLUDED.state,\"\n                    \" phone = EXCLUDED.phone,\"\n                    \" account_name = EXCLUDED.account_name,\"\n                    \" last_seen_at = EXCLUDED.last_seen_at,\"\n                    \" reported_by = EXCLUDED.reported_by,\"\n                    \" updated_at = NOW()\",\n                    (tenant[\"client_id\"], state, phone, account_name, tenant[\"user_id\"]),\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"wa status write\")[0]), 503\n\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.get(\"/whatsapp/commands\")\ndef list_commands():\n    args = request.args\n    tenant, error = _tenant_or_error(args.get(\"client_id\"))\n    if error:\n        return error\n    limit = _query_int(\"limit\", 20, 1, 50)\n    channel = (args.get(\"channel\") or \"\").strip()\n    if channel and channel not in ALLOWED_CHANNELS:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"channel whatsapp|telegram|instagram hon.\"}}), 400\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                try:\n                    import portal_growth\n\n                    portal_growth.materialize_due_broadcasts(cur, tenant[\"client_id\"], conn)\n                    import portal_digest\n\n                    portal_digest.materialize_due_digest(\n                        cur, tenant[\"client_id\"], conn\n                    )\n\n                    import portal_checkout\n\n                    portal_checkout.materialize_cart_reminders(\n                        cur, tenant[\"client_id\"], conn\n                    )\n\n                    try:\n                        import portal_bi\n                        portal_bi.materialize_weekly_problems(\n                            cur, tenant[\"client_id\"], conn\n                        )\n                    except Exception:\n                        pass\n\n                except Exception:\n                    pass\n                try:\n                    import portal_webhooks\n\n                    portal_webhooks.deliver_pending_webhooks(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_sequences\n\n                    portal_sequences.deliver_due_sequence_steps(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_workflows\n\n                    portal_workflows.run_due_workflows(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_kb_semantic\n\n                    # D1: throttled background top-up of the knowledge\n                    # semantic index (no-op when off or up to date).\n                    portal_kb_semantic.kick(tenant[\"client_id\"], \"tick\")\n                except Exception:\n                    pass\n                try:\n                    import portal_events\n\n                    portal_events.requeue_due_commands(\n                        cur, tenant[\"client_id\"]\n                    )\n                except Exception:\n                    pass\n                cmd_sql = (\n                    \"SELECT id, action, payload, created_at FROM \"\n                    + portal_db._q(portal_db.CMD_TABLE) +\n                    \" WHERE client_id = %s AND status = 'pending'\"\n                    \" AND (next_attempt_at IS NULL OR next_attempt_at <= NOW())\"\n                )\n                cmd_params: list = [tenant[\"client_id\"]]\n                if channel:\n                    cmd_sql += \" AND channel = %s\"\n                    cmd_params.append(channel)\n                cmd_sql += \" ORDER BY id ASC LIMIT %s\"\n                cmd_params.append(limit)\n                cur.execute(cmd_sql, tuple(cmd_params))\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"commands read\")[0]), 503\n\n    commands = []\n    for row in found:\n        created = row.get(\"created_at\")\n        if isinstance(created, datetime) and created.tzinfo is None:\n            created = created.replace(tzinfo=timezone.utc)\n        commands.append({\n            \"id\": row.get(\"id\"),\n            \"action\": row.get(\"action\"),\n            \"payload\": row.get(\"payload\") or {},\n            \"created_at\": created.isoformat() if isinstance(created, datetime) else None,\n        })\n    return jsonify({\"commands\": commands}), 200\n\n\n@bp.post(\"/whatsapp/commands/ack\")\ndef ack_command():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    command_id = payload.get(\"command_id\")\n    if isinstance(command_id, bool) or not isinstance(command_id, int) or command_id <= 0:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"command_id (positive int) zaroori hai.\"}}), 400\n    ok_flag = payload.get(\"ok\") is True\n    note = payload.get(\"note\")\n    note = note if isinstance(note, str) else None\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(portal_db.CMD_TABLE) +\n                    \" SET status = %s, result_note = %s, updated_at = NOW() \"\n                    \"WHERE id = %s AND client_id = %s RETURNING id\",\n                    (\"done\" if ok_flag else \"failed\", note, command_id, tenant[\"client_id\"]),\n                )\n                try:\n                    import portal_events\n\n                    portal_events.on_command_ack(\n                        cur,\n                        tenant[\"client_id\"],\n                        command_id,\n                        ok_flag,\n                        note,\n                        payload.get(\"provider_message_id\"),\n                    )\n                except Exception:\n                    pass\n                updated = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"command ack\")[0]), 503\n\n    if not updated:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Command nahi mili.\"}}), 404\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.get(\"/bot\")\ndef connector_bot_config():\n    tenant, error = _tenant_or_error(request.args.get(\"client_id\"))\n    if error:\n        return error\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT agent_name, tone, greeting, fallback,\"\n                    \" working_hours_enabled, working_hours_start, working_hours_end,\"\n                    \" human_handoff_enabled, updated_at\"\n                    \" FROM \" + portal_db._q(portal_db.BOT_TABLE) +\n                    \" WHERE client_id = %s\",\n                    (tenant[\"client_id\"],),\n                )\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"connector bot read\")[0]), 503\n\n    if not found:\n        return jsonify({\n            \"agent_name\": \"OmniFlow Assistant\",\n            \"tone\": \"friendly\",\n            \"greeting\": \"\",\n            \"fallback\": \"\",\n            \"working_hours_enabled\": False,\n            \"working_hours_start\": \"09:00\",\n            \"working_hours_end\": \"18:00\",\n            \"human_handoff_enabled\": False,\n            \"updated_at\": None,\n        }), 200\n\n    row = found[0]\n    updated = row.get(\"updated_at\")\n    if isinstance(updated, datetime) and updated.tzinfo is None:\n        updated = updated.replace(tzinfo=timezone.utc)\n    return jsonify({\n        \"agent_name\": row.get(\"agent_name\") or \"OmniFlow Assistant\",\n        \"tone\": row.get(\"tone\") if row.get(\"tone\") in (\"friendly\", \"professional\", \"concise\") else \"friendly\",\n        \"greeting\": row.get(\"greeting\") or \"\",\n        \"fallback\": row.get(\"fallback\") or \"\",\n        \"working_hours_enabled\": row.get(\"working_hours_enabled\") is True,\n        \"working_hours_start\": row.get(\"working_hours_start\") or \"09:00\",\n        \"working_hours_end\": row.get(\"working_hours_end\") or \"18:00\",\n        \"human_handoff_enabled\": row.get(\"human_handoff_enabled\") is True,\n        \"updated_at\": updated.isoformat() if isinstance(updated, datetime) else None,\n    }), 200\n\n\nMAX_INGEST_MESSAGES = 100\nALLOWED_DIRECTIONS = (\"in\", \"out\")\nALLOWED_CHANNELS = (\"whatsapp\", \"telegram\", \"instagram\")\n\n\n_AWAY_TABLE_READY = False\nAWAY_COOLDOWN_HOURS = 4\n_AWAY_DEFAULTS = {\n    \"enabled\": False,\n    \"timezone\": \"Asia/Karachi\",\n    \"days\": [\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n    ],\n    \"away_message\": \"\",\n}\n\n\ndef _ensure_away_table() -> None:\n    global _AWAY_TABLE_READY\n    if _AWAY_TABLE_READY:\n        return\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(\"portal_away_replies\") +\n                \" (id BIGSERIAL PRIMARY KEY, client_id BIGINT NOT NULL,\"\n                \" conversation_id BIGINT, contact_id TEXT NOT NULL,\"\n                \" body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending',\"\n                \" result_note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\"\n                \" sent_at TIMESTAMPTZ)\"\n            )\n            cur.execute(\n                \"CREATE INDEX IF NOT EXISTS portal_away_pending_idx ON \" +\n                portal_db._q(\"portal_away_replies\") +\n                \" (client_id, status, id)\"\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    _AWAY_TABLE_READY = True\n\n\ndef _load_business_hours(cur, client_id):\n    try:\n        cur.execute(\n            \"SELECT settings -> 'business_hours' AS business_hours FROM \" +\n            portal_db._q(\"client_settings\") +\n            \" WHERE client_id = %s\",\n            (client_id,),\n        )\n        rows = portal_db.rows(cur)\n    except Exception:\n        return _AWAY_DEFAULTS\n    stored = rows[0].get(\"business_hours\") if rows and rows[0] else None\n    return stored if isinstance(stored, dict) else _AWAY_DEFAULTS\n\n\ndef _away_closed_now(config) -> bool:\n    try:\n        from zoneinfo import ZoneInfo\n\n        days = config.get(\"days\")\n        if not isinstance(days, list) or len(days) != 7:\n            return False\n        now = datetime.now(ZoneInfo(str(config.get(\"timezone\") or \"UTC\")))\n        day = days[(now.weekday() + 1) % 7]\n        if not isinstance(day, dict) or day.get(\"enabled\") is not True:\n            return True\n        current = now.strftime(\"%H:%M\")\n        start = day.get(\"start\")\n        end = day.get(\"end\")\n        if not isinstance(start, str) or not isinstance(end, str):\n            return True\n        return not (start <= current <= end)\n    except Exception:\n        return False\n\n\ndef _maybe_enqueue_away_reply(client_id, conversation_id, contact_id, direction, conn) -> Optional[bool]:\n    \"\"\"Queue one automatic away reply, inside the ingest transaction.\n\n    Fires only for inbound messages while business hours are enabled and\n    currently closed, at most once per conversation per cooldown window.\n    Never raises into the caller: wrap in try/except there.\n    \"\"\"\n    if direction != \"in\":\n        return\n    with conn.cursor() as cur:\n        config = _load_business_hours(cur, client_id)\n        message = config.get(\"away_message\")\n        if (\n            config.get(\"enabled\") is not True\n            or not isinstance(message, str)\n            or not message.strip()\n        ):\n            return\n        if not _away_closed_now(config):\n            return\n        cur.execute(\n            \"SELECT 1 FROM \" + portal_db._q(\"portal_away_replies\") +\n            \" WHERE client_id = %s AND conversation_id = %s\"\n            \" AND created_at > NOW() - INTERVAL '\" +\n            str(AWAY_COOLDOWN_HOURS) + \" hours'\"\n            \" LIMIT 1\",\n            (client_id, conversation_id),\n        )\n        if portal_db.rows(cur):\n            return\n        try:\n            contact_lang = portal_contacts.stored_language(\n                cur, client_id, contact_id)\n        except Exception:\n            contact_lang = None\n        if contact_lang == \"ur\":\n            variant = config.get(\"away_message_ur\")\n        elif contact_lang == \"roman\":\n            variant = config.get(\"away_message_roman\")\n        else:\n            variant = None\n        if isinstance(variant, str) and variant.strip():\n            message = variant\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(\"portal_away_replies\") +\n            \" (client_id, conversation_id, contact_id, body)\"\n            \" VALUES (%s, %s, %s, %s)\",\n            (client_id, conversation_id, contact_id, message.strip()),\n        )\n        return True\n\n\n@bp.get(\"/away-replies\")\ndef list_due_away_replies():\n    args = request.args\n    tenant, error = _tenant_or_error(args.get(\"client_id\"))\n    if error:\n        return error\n    limit = _query_int(\"limit\", 5, 1, 20)\n\n    try:\n        _ensure_away_table()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT id, contact_id, body, created_at FROM \" +\n                    portal_db._q(\"portal_away_replies\") +\n                    \" WHERE client_id = %s AND status = 'pending'\"\n                    \" AND (next_attempt_at IS NULL OR next_attempt_at <= NOW())\"\n                    \" ORDER BY id ASC LIMIT %s\",\n                    (tenant[\"client_id\"], limit),\n                )\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"away replies read\")[0]), 503\n\n    replies = []\n    for row in found:\n        created = row.get(\"created_at\")\n        if isinstance(created, datetime) and created.tzinfo is None:\n            created = created.replace(tzinfo=timezone.utc)\n        replies.append({\n            \"id\": row.get(\"id\"),\n            \"external_user_id\": row.get(\"contact_id\"),\n            \"body\": row.get(\"body\"),\n            \"created_at\": created.isoformat() if isinstance(created, datetime) else None,\n        })\n    return jsonify({\"away_replies\": replies}), 200\n\n\n@bp.post(\"/away-replies/ack\")\ndef ack_away_reply():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    away_id = payload.get(\"away_id\")\n    if isinstance(away_id, bool) or not isinstance(away_id, int) or away_id <= 0:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"away_id (positive int) zaroori hai.\"}}), 400\n    ok_flag = payload.get(\"ok\") is True\n    note = payload.get(\"note\")\n    note = note if isinstance(note, str) else None\n\n    try:\n        _ensure_away_table()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(\"portal_away_replies\") +\n                    \" SET status = %s, result_note = %s, sent_at = NOW()\"\n                    \" WHERE id = %s AND client_id = %s AND status = 'pending' RETURNING id\",\n                    (\"sent\" if ok_flag else \"failed\", note, away_id, tenant[\"client_id\"]),\n                )\n                updated = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"away ack\")[0]), 503\n\n    if not updated:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Away reply nahi mili.\"}}), 404\n    return jsonify({\"ok\": True}), 200\n\n\nclass MessageValidationError(ValueError):\n    \"\"\"A connector payload failed the shared message contract.\"\"\"\n\n\nclass IngestRateLimited(Exception):\n    \"\"\"The tenant exceeded the shared inbound ingest limit.\"\"\"\n\n\nclass IngestFailure(Exception):\n    \"\"\"Wrap a persistence/automation failure for route-level JSON errors.\"\"\"\n\n    def __init__(self, original: Exception, operation: str):\n        super().__init__(str(original))\n        self.original = original\n        self.operation = operation\n\n\ndef normalize_messages(messages: Any, default_channel: str = \"whatsapp\",\n                        require_nonempty: bool = True):\n    \"\"\"Normalize provider-neutral messages for every channel adapter.\n\n    The returned records are deliberately the same records consumed by the\n    existing conversation, event, automation, compliance and audit engine.\n    Provider adapters may retain ``id``, ``media`` and ``postback`` metadata;\n    the core still uses the normalized ``from/body/name/direction/channel``\n    contract for conversation work.\n    \"\"\"\n    if not isinstance(messages, list) or (require_nonempty and not messages):\n        raise MessageValidationError(\n            \"messages (non-empty list) zaroori hai.\"\n            if require_nonempty else \"messages list zaroori hai.\"\n        )\n    if len(messages) > MAX_INGEST_MESSAGES:\n        raise MessageValidationError(\n            \"Aik request me max \" + str(MAX_INGEST_MESSAGES)\n            + \" messages bhejein.\"\n        )\n\n    normalized = []\n    for item in messages:\n        if not isinstance(item, dict):\n            raise MessageValidationError(\"Har message aik object ho.\")\n        sender = item.get(\"from\")\n        if not isinstance(sender, str) or not sender.strip():\n            raise MessageValidationError(\"Har message me 'from' zaroori hai.\")\n        body = item.get(\"body\")\n        if body is None:\n            body = \"\"\n        elif not isinstance(body, str):\n            body = str(body)\n        try:\n            import portal_interactive\n\n            reply_body = portal_interactive.interactive_body_override(\n                item.get(\"interactive\"), body\n            )\n            if reply_body is not None:\n                body = reply_body\n        except Exception:\n            pass\n        direction = item.get(\"direction\", \"in\")\n        if direction not in ALLOWED_DIRECTIONS:\n            raise MessageValidationError(\"direction in|out hon.\")\n        channel = item.get(\"channel\", default_channel)\n        if channel not in ALLOWED_CHANNELS:\n            raise MessageValidationError(\n                \"channel \" + \"|\".join(ALLOWED_CHANNELS) + \" hon.\"\n            )\n        name = item.get(\"name\")\n        name = name.strip() if isinstance(name, str) else None\n        record = {\n            \"from\": sender.strip(),\n            \"body\": body,\n            \"name\": name,\n            \"direction\": direction,\n            \"channel\": channel,\n        }\n        provider_id = item.get(\"id\")\n        if isinstance(provider_id, (str, int)) and str(provider_id).strip():\n            record[\"id\"] = str(provider_id).strip()\n        # Keep adapter metadata in the event/audit payload without making it\n        # part of the core conversation contract.\n        for key in (\"media\", \"postback\", \"timestamp\", \"provider\"):\n            if key in item and item[key] is not None:\n                record[key] = item[key]\n        normalized.append(record)\n    return normalized\n\n\ndef ingest_messages_for_tenant(tenant: Dict[str, Any], normalized) -> int:\n    \"\"\"Run the existing message engine for any normalized channel.\n\n    Instagram calls this function rather than creating a second conversation\n    or automation pipeline. One-reply, approvals, compliance, sequences,\n    workflows, intelligence and event idempotency all remain in this path.\n    \"\"\"\n    inserted = 0\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                try:\n                    import portal_ratelimit\n\n                    if not portal_ratelimit.allow(\n                        cur,\n                        \"ingest:\" + str(tenant[\"client_id\"]),\n                        portal_ratelimit.ingest_limit(),\n                        60,\n                    ):\n                        conn.commit()\n                        raise IngestRateLimited()\n                except IngestRateLimited:\n                    raise\n                except Exception:\n                    pass\n                for item in normalized:\n                    try:\n                        import portal_events\n\n                        if not portal_events.record_inbound(\n                            cur, tenant[\"client_id\"], item\n                        ):\n                            continue\n                    except Exception:\n                        pass\n                    if item[\"channel\"] == \"instagram\":\n                        try:\n                            import portal_identity\n\n                            identity_handle = item[\"from\"]\n                            if identity_handle.startswith(\"ig:\"):\n                                identity_handle = identity_handle[3:]\n                            portal_identity.resolve(\n                                cur,\n                                tenant[\"client_id\"],\n                                \"instagram\",\n                                identity_handle,\n                                item[\"name\"] or \"\",\n                                create=True,\n                                source=\"instagram_webhook\",\n                            )\n                        except Exception:\n                            pass\n                    cur.execute(\n                        \"INSERT INTO \" + portal_db._q(portal_db.CONV_TABLE) +\n                        \" (client_id, channel, contact_id, contact_name,\"\n                        \" status, last_message_preview, last_message_at,\"\n                        \" created_at, updated_at) \"\n                        \"VALUES (%s, %s, %s, %s, 'open', %s, NOW(), NOW(), NOW()) \"\n                        \"ON CONFLICT (client_id, channel, contact_id) DO UPDATE SET \"\n                        \" contact_name = COALESCE(EXCLUDED.contact_name,\"\n                        \" \" + portal_db._q(portal_db.CONV_TABLE) + \".contact_name), \"\n                        \" last_message_preview = EXCLUDED.last_message_preview, \"\n                        \" last_message_at = EXCLUDED.last_message_at, \"\n                        \" updated_at = NOW() \"\n                        \"RETURNING id\",\n                        (tenant[\"client_id\"], item[\"channel\"], item[\"from\"],\n                         item[\"name\"], item[\"body\"]),\n                    )\n                    conv = portal_db.rows(cur)\n                    conversation_id = conv[0][\"id\"] if conv else None\n                    cur.execute(\n                        \"INSERT INTO \" + portal_db._q(portal_db.MSGS_TABLE) +\n                        \" (conversation_id, client_id, direction, body,\"\n                        \" sender_name, status, created_at) \"\n                        \"VALUES (%s, %s, %s, %s, %s, %s, NOW())\",\n                        (conversation_id, tenant[\"client_id\"], item[\"direction\"],\n                         item[\"body\"], item[\"name\"],\n                         \"received\" if item[\"direction\"] == \"in\" else \"sent\"),\n                    )\n                    # One-reply law (B2): the first automation that sends a\n                    # customer-visible reply claims the message; the other\n                    # reply hooks stay quiet. Side-effect hooks (language\n                    # detection, compliance, listen, routing, sequences)\n                    # always run.\n                    claimed_by = None\n                    if claimed_by is None:\n                        try:\n                            import portal_approvals\n\n                            if portal_approvals.maybe_decide(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"approvals\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            if _maybe_enqueue_away_reply(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"away\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            if portal_cod.maybe_cod_flow(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"cod\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            import portal_brain\n\n                            if portal_brain.maybe_answer(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                conn,\n                            ):\n                                claimed_by = \"brain\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            import portal_kb\n                            import portal_intents\n\n                            import portal_llm\n\n                            with portal_llm.usage_scope(\n                                    \"intent\", tenant[\"client_id\"]):\n                                intent = portal_intents.classify(item[\"body\"])\n                            if portal_kb.maybe_auto_reply(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                intent,\n                                conn,\n                            ):\n                                claimed_by = \"kb\"\n                        except Exception:\n                            pass\n                    if claimed_by:\n                        try:\n                            import portal_events\n\n                            portal_events.note_claim(\n                                cur, tenant[\"client_id\"], item, claimed_by\n                            )\n                        except Exception:\n                            pass\n                    try:\n                        portal_contacts.maybe_detect_language(\n                            tenant[\"client_id\"],\n                            item[\"from\"],\n                            item[\"body\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    if item[\"direction\"] == \"in\":\n                        try:\n                            import portal_compliance\n\n                            portal_compliance.maybe_opt_out(\n                                tenant[\"client_id\"],\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_listen\n\n                            portal_listen.maybe_listen(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_routing\n\n                            portal_routing.maybe_route(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_intelligence\n\n                            portal_intelligence.maybe_analyze(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_approvals\n\n                            portal_approvals.maybe_request(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                    try:\n                        portal_sequences.maybe_enroll_new_contact(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        portal_sequences.maybe_enroll_keyword(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            item[\"body\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        portal_sequences.maybe_auto_pause_replies(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        import portal_workflows\n\n                        portal_workflows.maybe_trigger_message(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            item[\"body\"],\n                            item[\"direction\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        import portal_events\n\n                        portal_events.mark_inbound_done(\n                            cur, tenant[\"client_id\"], item\n                        )\n                    except Exception:\n                        pass\n                    inserted += 1\n            conn.commit()\n        finally:\n            conn.close()\n    except IngestRateLimited:\n        raise\n    except Exception as error:\n        raise IngestFailure(error, \"messages ingest\") from error\n    return inserted\n\n\n@bp.post(\"/whatsapp/messages\")\ndef ingest_whatsapp_messages():\n    \"\"\"Store connector-delivered messages through the shared channel engine.\"\"\"\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n    try:\n        normalized = normalize_messages(\n            payload.get(\"messages\"), default_channel=\"whatsapp\"\n        )\n    except MessageValidationError as error:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": str(error)}}), 400\n\n    try:\n        inserted = ingest_messages_for_tenant(tenant, normalized)\n    except IngestRateLimited:\n        return jsonify({\"error\": {\n            \"code\": \"rate_limited\",\n            \"message\": \"Too many messages; slow down.\",\n        }}), 429\n    except IngestFailure as failure:\n        return jsonify(portal_db.portal_unavailable(\n            failure.original, failure.operation)[0]), 503\n\n    logger.info(\"whatsapp messages ingested client_id=%s count=%s\",\n                tenant[\"client_id\"], inserted)\n    return jsonify({\"ok\": True, \"inserted\": inserted}), 200\n\n");
writeNewRepair("omniflow-backend-patch/platform_settings.py", "# key/base reuse the AI engine above. Env fallbacks: OF_KB_EMBED_MODE,", false,
    "\"\"\"Platform-level settings store (admin-panel managed provider config).\n\nOne tiny table - platform_settings(key TEXT PRIMARY KEY, value TEXT,\nupdated_at) - holds everything the owner types into the admin panel's\nIntegrations page: SMTP/Brevo email credentials, the LLM engine config,\nthe AI feature switches and the future-channel keys (voice, video,\npayments, phone verification, the WhatsApp E2E test number).\n\nDesign laws:\n- STANDARD LIBRARY ONLY for the readers (portal_llm imports this inside\n  the ingest hot path; flask lives in admin_providers, not here).\n- Fail-soft: any read error -> None, and the caller falls back to its\n  environment variable (env-config adapters stay the safety net).\n- Secrets are stored as-is in the database and masked by the admin API;\n  the readers here are server-side only.\n- A 30-second TTL cache keeps the ingest loop from hammering the\n  database; every PUT invalidates it on the instance that wrote.\n\"\"\"\n\nimport time\n\ntry:  # pragma: no cover - always available in the Control Plane image\n    import portal_db\nexcept Exception:  # pragma: no cover - tests may inject a stub\n    portal_db = None\n\nTABLE = \"platform_settings\"\nCACHE_TTL_SECONDS = 30.0\n\n_DDL_READY = False\n_cache = {}\n_cache_at = 0.0\n\ndef _ddl() -> str:\n    \"\"\"Built lazily so importing this module never touches portal_db.\"\"\"\n    return (\n        \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(TABLE) + \" (\"\n        \" key TEXT PRIMARY KEY,\"\n        \" value TEXT NOT NULL DEFAULT '',\"\n        \" updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\"\n        \")\"\n    )\n\n# group -> the exact keys the admin API accepts for that group.\nGROUP_KEYS = {\n    \"email\": [\"provider\", \"smtp_host\", \"smtp_port\", \"smtp_user\",\n              \"smtp_password\", \"smtp_from\", \"brevo_api_key\", \"reports_to\"],\n    \"llm\": [\"base_url\", \"api_key\", \"model\", \"prices_json\"],\n    \"flags\": [\"true_sentiment\", \"kb_autodraft\", \"phone_verification\"],\n    \"voice\": [\"provider\", \"account_sid\", \"auth_token\", \"from_number\"],\n    \"video\": [\"provider\", \"api_key\", \"zoom_account_id\",\n              \"zoom_client_id\", \"zoom_client_secret\"],\n    \"payments\": [\"provider\", \"publishable_key\", \"secret_key\",\n                 \"webhook_secret\"],\n    \"whatsapp_e2e\": [\"live_number\"],\n    \"stt\": [\"api_key\", \"base_url\", \"model\"],\n    # Platform AI controls (admin AI Control Center): a global pause, the\n    # highest autonomy any workspace may run at, and a per-workspace daily\n    # LLM call cap (0 = unlimited). Env fallbacks: OF_AI_KILL_SWITCH,\n    # OF_AI_AUTONOMY_CAP, OF_AI_DAILY_CALL_CAP.\n    \"ai\": [\"kill_switch\", \"autonomy_cap\", \"daily_call_cap\", \"guard_mode\"],\n    # Knowledge semantic index (D1): OpenAI-compatible /embeddings. Blank\n    # key/base reuse the AI engine above. Env fallbacks: OF_KB_EMBED_MODE,\n    # OF_EMBED_API_KEY, OF_EMBED_BASE_URL, OF_EMBED_MODEL,\n    # OF_EMBED_DIMENSIONS, OF_KB_EMBED_MIN_SIM (percent).\n    \"embeddings\": [\"mode\", \"api_key\", \"base_url\", \"model\", \"dimensions\",\n                   \"min_similarity\"],\n}\n\nAUTONOMY_LEVELS = (\"off\", \"suggest\", \"auto\")\nGUARD_MODES = (\"off\", \"standard\", \"strict\")\n\nSECRET_HINTS = (\"password\", \"api_key\", \"token\", \"secret\")\n\n\ndef _key(group: str, name: str) -> str:\n    return group + \".\" + name\n\n\ndef _ensure(cur) -> None:\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_ddl())\n    _DDL_READY = True\n\n\ndef invalidate_cache() -> None:\n    \"\"\"Drop the TTL cache (called after every successful PUT).\"\"\"\n    global _cache_at\n    _cache.clear()\n    _cache_at = 0.0\n\n\ndef get_setting(key: str, default=None):\n    \"\"\"One setting as TEXT; default on any error (fail-soft).\"\"\"\n    global _cache, _cache_at\n    if portal_db is None:\n        return default\n    now = time.monotonic()\n    if _cache and (now - _cache_at) < CACHE_TTL_SECONDS:\n        if key in _cache:\n            return _cache[key]\n        return default\n    try:\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                _ensure(cur)\n                cur.execute(\n                    \"SELECT key, value FROM \" + portal_db._q(TABLE)\n                )\n                rows = portal_db.rows(cur)\n        finally:\n            conn.close()\n        _cache = {str(r[\"key\"]): str(r[\"value\"] or \"\") for r in rows}\n        _cache_at = time.monotonic()\n    except Exception:\n        _cache.clear()\n        _cache_at = 0.0\n        return default\n    return _cache.get(key, default)\n\n\ndef get_group(group: str) -> dict:\n    \"\"\"Every stored key of one group as {name: value} (no defaults).\"\"\"\n    prefix = group + \".\"\n    out = {}\n    if portal_db is None:\n        return out\n    try:\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                _ensure(cur)\n                cur.execute(\n                    \"SELECT key, value FROM \" + portal_db._q(TABLE)\n                    + \" WHERE key LIKE %s\",\n                    (prefix + \"%\",),\n                )\n                rows = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception:\n        return out\n    for row in rows:\n        out[str(row[\"key\"])[len(prefix):]] = str(row[\"value\"] or \"\")\n    return out\n\n\ndef put_group(cur, group: str, values: dict) -> None:\n    \"\"\"Upsert one group inside the CALLER's transaction (admin PUT).\n\n    The caller owns auth, whitelist filtering, the audit row and the\n    commit; this only writes the key/value pairs.\n    \"\"\"\n    prefix = group + \".\"\n    for name, value in values.items():\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(TABLE) +\n            \" (key, value, updated_at) VALUES (%s, %s, NOW())\"\n            \" ON CONFLICT (key) DO UPDATE SET\"\n            \" value = EXCLUDED.value, updated_at = NOW()\",\n            (prefix + name, str(value)),\n        )\n\n\ndef _env(name: str, default: str = \"\") -> str:\n    import os\n    return os.environ.get(name, default).strip()\n\n\ndef llm_config() -> dict:\n    \"\"\"Effective LLM config: admin panel first, env fallback.\n\n    enabled keeps the env kill switch: OF_LLM_ENABLED explicitly off\n    wins over a stored key.\n    \"\"\"\n    stored = {}\n    try:\n        stored = get_group(\"llm\")\n    except Exception:\n        stored = {}\n    env_enabled = _env(\"OF_LLM_ENABLED\", \"1\").lower() not in (\n        \"0\", \"false\", \"no\", \"off\")\n    api_key = str(stored.get(\"api_key\") or _env(\"OF_LLM_API_KEY\", \"\"))\n    return {\n        \"base_url\": (str(stored.get(\"base_url\") or \"\")\n                     or _env(\"OF_LLM_BASE_URL\",\n                             \"https://api.openai.com/v1\")).rstrip(\"/\"),\n        \"api_key\": api_key,\n        \"model\": str(stored.get(\"model\") or \"\")\n                 or _env(\"OF_LLM_MODEL\", \"gpt-4o-mini\"),\n        \"enabled\": bool(api_key) and env_enabled,\n    }\n\n\ndef ai_controls() -> dict:\n    \"\"\"Effective platform AI controls: admin panel first, env fallback.\n\n    {kill_switch: bool, autonomy_cap: off|suggest|auto,\n     daily_call_cap: int (0 = unlimited),\n     guard_mode: off|standard|strict (prompt-injection guard),\n     source: panel|env|default}\n    Fail-soft: any storage problem yields the permissive defaults. Reads\n    go through get_setting (30 s TTL cache) because the LLM gate consults\n    this on EVERY call - never an extra round trip per call.\n    \"\"\"\n    stored = {}\n    try:\n        for name in GROUP_KEYS[\"ai\"]:\n            stored[name] = str(get_setting(\"ai.\" + name, \"\") or \"\")\n    except Exception:\n        stored = {}\n    source = \"default\"\n    kill_raw = str(stored.get(\"kill_switch\") or \"\")\n    if kill_raw:\n        source = \"panel\"\n    else:\n        kill_raw = _env(\"OF_AI_KILL_SWITCH\", \"\")\n        if kill_raw:\n            source = \"env\"\n    cap_raw = str(stored.get(\"autonomy_cap\") or \"\").strip().lower()\n    if cap_raw and source == \"default\":\n        source = \"panel\"\n    if not cap_raw:\n        cap_raw = _env(\"OF_AI_AUTONOMY_CAP\", \"\").lower()\n        if cap_raw and source == \"default\":\n            source = \"env\"\n    if cap_raw not in AUTONOMY_LEVELS:\n        cap_raw = \"auto\"\n    daily_raw = str(stored.get(\"daily_call_cap\") or \"\").strip()\n    if daily_raw and source == \"default\":\n        source = \"panel\"\n    if not daily_raw:\n        daily_raw = _env(\"OF_AI_DAILY_CALL_CAP\", \"\")\n        if daily_raw and source == \"default\":\n            source = \"env\"\n    try:\n        daily_cap = max(0, int(daily_raw or 0))\n    except (TypeError, ValueError):\n        daily_cap = 0\n    guard_raw = str(stored.get(\"guard_mode\") or \"\").strip().lower()\n    if guard_raw and source == \"default\":\n        source = \"panel\"\n    if not guard_raw:\n        guard_raw = _env(\"OF_AI_GUARD_MODE\", \"\").lower()\n        if guard_raw and source == \"default\":\n            source = \"env\"\n    if guard_raw not in GUARD_MODES:\n        guard_raw = \"standard\"\n    return {\n        \"kill_switch\": kill_raw.strip().lower() in (\"on\", \"1\", \"true\", \"yes\"),\n        \"autonomy_cap\": cap_raw,\n        \"daily_call_cap\": daily_cap,\n        \"guard_mode\": guard_raw,\n        \"source\": source,\n    }\n\n\ndef video_config() -> dict:\n    \"\"\"Effective video-provider config: admin panel first, env fallback.\"\"\"\n    stored = {}\n    try:\n        stored = get_group(\"video\")\n    except Exception:\n        stored = {}\n    def pick(name, env, default=\"\"):\n        return str(stored.get(name) or \"\").strip() or _env(env, default)\n    provider = (str(stored.get(\"provider\") or \"\").strip().lower()\n                or _env(\"OF_VIDEO_PROVIDER\", \"whereby\"))\n    return {\n        \"provider\": provider,\n        \"api_key\": str(stored.get(\"api_key\") or \"\")\n                   or os_secret_env(\"OF_VIDEO_API_KEY\"),\n        \"zoom_account_id\": pick(\"zoom_account_id\", \"OF_ZOOM_ACCOUNT_ID\"),\n        \"zoom_client_id\": pick(\"zoom_client_id\", \"OF_ZOOM_CLIENT_ID\"),\n        \"zoom_client_secret\": str(stored.get(\"zoom_client_secret\") or \"\")\n                              or os_secret_env(\"OF_ZOOM_CLIENT_SECRET\"),\n    }\n\n\ndef smtp_config() -> dict:\n    \"\"\"Effective email config: admin panel first, env fallback.\"\"\"\n    stored = {}\n    try:\n        stored = get_group(\"email\")\n    except Exception:\n        stored = {}\n    def pick(name, env, default=\"\"):\n        return str(stored.get(name) or \"\").strip() or _env(env, default)\n    provider = (str(stored.get(\"provider\") or \"\").strip().lower()\n                or (\"brevo\" if _env(\"BREVO_API_KEY\") else \"smtp\"))\n    return {\n        \"provider\": provider,\n        \"smtp_host\": pick(\"smtp_host\", \"SMTP_HOST\"),\n        \"smtp_port\": pick(\"smtp_port\", \"SMTP_PORT\", \"587\"),\n        \"smtp_user\": pick(\"smtp_user\", \"SMTP_USER\"),\n        \"smtp_password\": str(stored.get(\"smtp_password\") or \"\")\n                         or os_secret_env(\"SMTP_PASSWORD\"),\n        \"smtp_from\": pick(\"smtp_from\", \"SMTP_FROM\",\n                          \"OmniFlow <no-reply@omniflow.app>\"),\n        \"brevo_api_key\": str(stored.get(\"brevo_api_key\") or \"\")\n                         or os_secret_env(\"BREVO_API_KEY\"),\n        \"reports_to\": pick(\"reports_to\", \"OMNIFLOW_REPORTS_TO\"),\n    }\n\n\ndef os_secret_env(name: str) -> str:\n    \"\"\"Secret env fallback (os.environ read kept out of the hot path).\"\"\"\n    import os\n    return os.environ.get(name, \"\")\n\n\ndef flag(name: str) -> bool:\n    \"\"\"AI/feature switch state; every switch defaults OFF.\"\"\"\n    try:\n        raw = str(get_setting(\"flags.\" + name, \"\") or \"\").strip().lower()\n    except Exception:\n        return False\n    return raw in (\"on\", \"1\", \"true\", \"yes\")\n\n\ndef stt_config() -> dict:\n    \"\"\"Effective speech-to-text config: admin panel first, env fallback.\n\n    portal_media owns the base/model defaults (OpenAI-compatible whisper\n    endpoint); this only resolves what the owner saved (or the env).\n    \"\"\"\n    stored = {}\n    try:\n        stored = get_group(\"stt\")\n    except Exception:\n        stored = {}\n    return {\n        \"api_key\": str(stored.get(\"api_key\")\n                       or _env(\"OMNIFLOW_STT_API_KEY\", \"\")),\n        \"base_url\": str(stored.get(\"base_url\")\n                        or _env(\"OMNIFLOW_STT_BASE\", \"\")),\n        \"model\": str(stored.get(\"model\")\n                     or _env(\"OMNIFLOW_STT_MODEL\", \"\")),\n    }\n\n\nEMBED_MODES = (\"on\", \"off\")\nGEMINI_HOST_HINT = \"generativelanguage.googleapis.com\"\n\n\ndef _embed_default_model(base_url: str) -> str:\n    if GEMINI_HOST_HINT in str(base_url or \"\"):\n        return _env(\"OF_EMBED_MODEL_GEMINI\", \"gemini-embedding-001\")\n    return _env(\"OF_EMBED_MODEL_DEFAULT\", \"text-embedding-3-small\")\n\n\ndef _embed_default_min_sim(model: str) -> int:\n    # Similarity scales differ per model family: Gemini vectors sit higher\n    # for unrelated text than OpenAI's. Owner/env can always override.\n    if \"gemini\" in str(model or \"\").lower():\n        return int(_env(\"OF_KB_EMBED_MIN_SIM_GEMINI\", \"60\") or 60)\n    return int(_env(\"OF_KB_EMBED_MIN_SIM_DEFAULT\", \"30\") or 30)\n\n\ndef _int_or(value, default: int, low: int, high: int) -> int:\n    try:\n        number = int(str(value).strip())\n    except Exception:\n        return default\n    return max(low, min(high, number))\n\n\ndef embed_config() -> dict:\n    \"\"\"Effective knowledge-embedding config: admin panel first, env next,\n    then the AI engine's own base/key. Uses get_setting (30 s TTL cache)\n    because retrieval consults it on the reply path. Fail-soft.\n\n    {mode: on|off, active: bool, reason: active|off|no_key|llm_disabled,\n     api_key, base_url, model, dimensions (0 = provider default),\n     min_similarity (0..1), key_source: embeddings|env|llm|none}\n    \"\"\"\n    def setting(name: str) -> str:\n        try:\n            return str(get_setting(\"embeddings.\" + name, \"\") or \"\").strip()\n        except Exception:\n            return \"\"\n\n    def llm_setting(name: str) -> str:\n        try:\n            return str(get_setting(\"llm.\" + name, \"\") or \"\").strip()\n        except Exception:\n            return \"\"\n\n    mode = (setting(\"mode\") or _env(\"OF_KB_EMBED_MODE\", \"on\")).lower()\n    if mode not in EMBED_MODES:\n        mode = \"on\"\n    key_source = \"none\"\n    api_key = setting(\"api_key\")\n    if api_key:\n        key_source = \"embeddings\"\n    elif _env(\"OF_EMBED_API_KEY\", \"\"):\n        api_key, key_source = _env(\"OF_EMBED_API_KEY\", \"\"), \"env\"\n    else:\n        api_key = llm_setting(\"api_key\") or _env(\"OF_LLM_API_KEY\", \"\")\n        key_source = \"llm\" if api_key else \"none\"\n    base_url = (setting(\"base_url\") or _env(\"OF_EMBED_BASE_URL\", \"\")\n                or llm_setting(\"base_url\")\n                or _env(\"OF_LLM_BASE_URL\", \"https://api.openai.com/v1\"))\n    base_url = base_url.rstrip(\"/\")\n    model = (setting(\"model\") or _env(\"OF_EMBED_MODEL\", \"\")\n             or _embed_default_model(base_url))\n    dimensions = _int_or(setting(\"dimensions\")\n                         or _env(\"OF_EMBED_DIMENSIONS\", \"256\"), 256, 0, 4096)\n    min_sim = _int_or(setting(\"min_similarity\")\n                      or _env(\"OF_KB_EMBED_MIN_SIM\", \"\"),\n                      _embed_default_min_sim(model), 0, 100)\n    llm_enabled = _env(\"OF_LLM_ENABLED\", \"1\").lower() not in (\n        \"0\", \"false\", \"no\", \"off\")\n    if mode == \"off\":\n        reason = \"off\"\n    elif not api_key:\n        reason = \"no_key\"\n    elif key_source == \"llm\" and not llm_enabled:\n        reason = \"llm_disabled\"\n    else:\n        reason = \"active\"\n    return {\n        \"mode\": mode,\n        \"active\": reason == \"active\",\n        \"reason\": reason,\n        \"api_key\": api_key,\n        \"base_url\": base_url,\n        \"model\": model,\n        \"dimensions\": dimensions,\n        \"min_similarity\": min_sim / 100.0,\n        \"key_source\": key_source,\n    }\n\n");
writeNewRepair("OmniFlow-Control-Plane/platform_settings.py", "# key/base reuse the AI engine above. Env fallbacks: OF_KB_EMBED_MODE,", true,
    "\"\"\"Platform-level settings store (admin-panel managed provider config).\n\nOne tiny table - platform_settings(key TEXT PRIMARY KEY, value TEXT,\nupdated_at) - holds everything the owner types into the admin panel's\nIntegrations page: SMTP/Brevo email credentials, the LLM engine config,\nthe AI feature switches and the future-channel keys (voice, video,\npayments, phone verification, the WhatsApp E2E test number).\n\nDesign laws:\n- STANDARD LIBRARY ONLY for the readers (portal_llm imports this inside\n  the ingest hot path; flask lives in admin_providers, not here).\n- Fail-soft: any read error -> None, and the caller falls back to its\n  environment variable (env-config adapters stay the safety net).\n- Secrets are stored as-is in the database and masked by the admin API;\n  the readers here are server-side only.\n- A 30-second TTL cache keeps the ingest loop from hammering the\n  database; every PUT invalidates it on the instance that wrote.\n\"\"\"\n\nimport time\n\ntry:  # pragma: no cover - always available in the Control Plane image\n    import portal_db\nexcept Exception:  # pragma: no cover - tests may inject a stub\n    portal_db = None\n\nTABLE = \"platform_settings\"\nCACHE_TTL_SECONDS = 30.0\n\n_DDL_READY = False\n_cache = {}\n_cache_at = 0.0\n\ndef _ddl() -> str:\n    \"\"\"Built lazily so importing this module never touches portal_db.\"\"\"\n    return (\n        \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(TABLE) + \" (\"\n        \" key TEXT PRIMARY KEY,\"\n        \" value TEXT NOT NULL DEFAULT '',\"\n        \" updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\"\n        \")\"\n    )\n\n# group -> the exact keys the admin API accepts for that group.\nGROUP_KEYS = {\n    \"email\": [\"provider\", \"smtp_host\", \"smtp_port\", \"smtp_user\",\n              \"smtp_password\", \"smtp_from\", \"brevo_api_key\", \"reports_to\"],\n    \"llm\": [\"base_url\", \"api_key\", \"model\", \"prices_json\"],\n    \"flags\": [\"true_sentiment\", \"kb_autodraft\", \"phone_verification\"],\n    \"voice\": [\"provider\", \"account_sid\", \"auth_token\", \"from_number\"],\n    \"video\": [\"provider\", \"api_key\", \"zoom_account_id\",\n              \"zoom_client_id\", \"zoom_client_secret\"],\n    \"payments\": [\"provider\", \"publishable_key\", \"secret_key\",\n                 \"webhook_secret\"],\n    \"whatsapp_e2e\": [\"live_number\"],\n    \"stt\": [\"api_key\", \"base_url\", \"model\"],\n    # Platform AI controls (admin AI Control Center): a global pause, the\n    # highest autonomy any workspace may run at, and a per-workspace daily\n    # LLM call cap (0 = unlimited). Env fallbacks: OF_AI_KILL_SWITCH,\n    # OF_AI_AUTONOMY_CAP, OF_AI_DAILY_CALL_CAP.\n    \"ai\": [\"kill_switch\", \"autonomy_cap\", \"daily_call_cap\", \"guard_mode\"],\n    # Knowledge semantic index (D1): OpenAI-compatible /embeddings. Blank\n    # key/base reuse the AI engine above. Env fallbacks: OF_KB_EMBED_MODE,\n    # OF_EMBED_API_KEY, OF_EMBED_BASE_URL, OF_EMBED_MODEL,\n    # OF_EMBED_DIMENSIONS, OF_KB_EMBED_MIN_SIM (percent).\n    \"embeddings\": [\"mode\", \"api_key\", \"base_url\", \"model\", \"dimensions\",\n                   \"min_similarity\"],\n}\n\nAUTONOMY_LEVELS = (\"off\", \"suggest\", \"auto\")\nGUARD_MODES = (\"off\", \"standard\", \"strict\")\n\nSECRET_HINTS = (\"password\", \"api_key\", \"token\", \"secret\")\n\n\ndef _key(group: str, name: str) -> str:\n    return group + \".\" + name\n\n\ndef _ensure(cur) -> None:\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_ddl())\n    _DDL_READY = True\n\n\ndef invalidate_cache() -> None:\n    \"\"\"Drop the TTL cache (called after every successful PUT).\"\"\"\n    global _cache_at\n    _cache.clear()\n    _cache_at = 0.0\n\n\ndef get_setting(key: str, default=None):\n    \"\"\"One setting as TEXT; default on any error (fail-soft).\"\"\"\n    global _cache, _cache_at\n    if portal_db is None:\n        return default\n    now = time.monotonic()\n    if _cache and (now - _cache_at) < CACHE_TTL_SECONDS:\n        if key in _cache:\n            return _cache[key]\n        return default\n    try:\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                _ensure(cur)\n                cur.execute(\n                    \"SELECT key, value FROM \" + portal_db._q(TABLE)\n                )\n                rows = portal_db.rows(cur)\n        finally:\n            conn.close()\n        _cache = {str(r[\"key\"]): str(r[\"value\"] or \"\") for r in rows}\n        _cache_at = time.monotonic()\n    except Exception:\n        _cache.clear()\n        _cache_at = 0.0\n        return default\n    return _cache.get(key, default)\n\n\ndef get_group(group: str) -> dict:\n    \"\"\"Every stored key of one group as {name: value} (no defaults).\"\"\"\n    prefix = group + \".\"\n    out = {}\n    if portal_db is None:\n        return out\n    try:\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                _ensure(cur)\n                cur.execute(\n                    \"SELECT key, value FROM \" + portal_db._q(TABLE)\n                    + \" WHERE key LIKE %s\",\n                    (prefix + \"%\",),\n                )\n                rows = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception:\n        return out\n    for row in rows:\n        out[str(row[\"key\"])[len(prefix):]] = str(row[\"value\"] or \"\")\n    return out\n\n\ndef put_group(cur, group: str, values: dict) -> None:\n    \"\"\"Upsert one group inside the CALLER's transaction (admin PUT).\n\n    The caller owns auth, whitelist filtering, the audit row and the\n    commit; this only writes the key/value pairs.\n    \"\"\"\n    prefix = group + \".\"\n    for name, value in values.items():\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(TABLE) +\n            \" (key, value, updated_at) VALUES (%s, %s, NOW())\"\n            \" ON CONFLICT (key) DO UPDATE SET\"\n            \" value = EXCLUDED.value, updated_at = NOW()\",\n            (prefix + name, str(value)),\n        )\n\n\ndef _env(name: str, default: str = \"\") -> str:\n    import os\n    return os.environ.get(name, default).strip()\n\n\ndef llm_config() -> dict:\n    \"\"\"Effective LLM config: admin panel first, env fallback.\n\n    enabled keeps the env kill switch: OF_LLM_ENABLED explicitly off\n    wins over a stored key.\n    \"\"\"\n    stored = {}\n    try:\n        stored = get_group(\"llm\")\n    except Exception:\n        stored = {}\n    env_enabled = _env(\"OF_LLM_ENABLED\", \"1\").lower() not in (\n        \"0\", \"false\", \"no\", \"off\")\n    api_key = str(stored.get(\"api_key\") or _env(\"OF_LLM_API_KEY\", \"\"))\n    return {\n        \"base_url\": (str(stored.get(\"base_url\") or \"\")\n                     or _env(\"OF_LLM_BASE_URL\",\n                             \"https://api.openai.com/v1\")).rstrip(\"/\"),\n        \"api_key\": api_key,\n        \"model\": str(stored.get(\"model\") or \"\")\n                 or _env(\"OF_LLM_MODEL\", \"gpt-4o-mini\"),\n        \"enabled\": bool(api_key) and env_enabled,\n    }\n\n\ndef ai_controls() -> dict:\n    \"\"\"Effective platform AI controls: admin panel first, env fallback.\n\n    {kill_switch: bool, autonomy_cap: off|suggest|auto,\n     daily_call_cap: int (0 = unlimited),\n     guard_mode: off|standard|strict (prompt-injection guard),\n     source: panel|env|default}\n    Fail-soft: any storage problem yields the permissive defaults. Reads\n    go through get_setting (30 s TTL cache) because the LLM gate consults\n    this on EVERY call - never an extra round trip per call.\n    \"\"\"\n    stored = {}\n    try:\n        for name in GROUP_KEYS[\"ai\"]:\n            stored[name] = str(get_setting(\"ai.\" + name, \"\") or \"\")\n    except Exception:\n        stored = {}\n    source = \"default\"\n    kill_raw = str(stored.get(\"kill_switch\") or \"\")\n    if kill_raw:\n        source = \"panel\"\n    else:\n        kill_raw = _env(\"OF_AI_KILL_SWITCH\", \"\")\n        if kill_raw:\n            source = \"env\"\n    cap_raw = str(stored.get(\"autonomy_cap\") or \"\").strip().lower()\n    if cap_raw and source == \"default\":\n        source = \"panel\"\n    if not cap_raw:\n        cap_raw = _env(\"OF_AI_AUTONOMY_CAP\", \"\").lower()\n        if cap_raw and source == \"default\":\n            source = \"env\"\n    if cap_raw not in AUTONOMY_LEVELS:\n        cap_raw = \"auto\"\n    daily_raw = str(stored.get(\"daily_call_cap\") or \"\").strip()\n    if daily_raw and source == \"default\":\n        source = \"panel\"\n    if not daily_raw:\n        daily_raw = _env(\"OF_AI_DAILY_CALL_CAP\", \"\")\n        if daily_raw and source == \"default\":\n            source = \"env\"\n    try:\n        daily_cap = max(0, int(daily_raw or 0))\n    except (TypeError, ValueError):\n        daily_cap = 0\n    guard_raw = str(stored.get(\"guard_mode\") or \"\").strip().lower()\n    if guard_raw and source == \"default\":\n        source = \"panel\"\n    if not guard_raw:\n        guard_raw = _env(\"OF_AI_GUARD_MODE\", \"\").lower()\n        if guard_raw and source == \"default\":\n            source = \"env\"\n    if guard_raw not in GUARD_MODES:\n        guard_raw = \"standard\"\n    return {\n        \"kill_switch\": kill_raw.strip().lower() in (\"on\", \"1\", \"true\", \"yes\"),\n        \"autonomy_cap\": cap_raw,\n        \"daily_call_cap\": daily_cap,\n        \"guard_mode\": guard_raw,\n        \"source\": source,\n    }\n\n\ndef video_config() -> dict:\n    \"\"\"Effective video-provider config: admin panel first, env fallback.\"\"\"\n    stored = {}\n    try:\n        stored = get_group(\"video\")\n    except Exception:\n        stored = {}\n    def pick(name, env, default=\"\"):\n        return str(stored.get(name) or \"\").strip() or _env(env, default)\n    provider = (str(stored.get(\"provider\") or \"\").strip().lower()\n                or _env(\"OF_VIDEO_PROVIDER\", \"whereby\"))\n    return {\n        \"provider\": provider,\n        \"api_key\": str(stored.get(\"api_key\") or \"\")\n                   or os_secret_env(\"OF_VIDEO_API_KEY\"),\n        \"zoom_account_id\": pick(\"zoom_account_id\", \"OF_ZOOM_ACCOUNT_ID\"),\n        \"zoom_client_id\": pick(\"zoom_client_id\", \"OF_ZOOM_CLIENT_ID\"),\n        \"zoom_client_secret\": str(stored.get(\"zoom_client_secret\") or \"\")\n                              or os_secret_env(\"OF_ZOOM_CLIENT_SECRET\"),\n    }\n\n\ndef smtp_config() -> dict:\n    \"\"\"Effective email config: admin panel first, env fallback.\"\"\"\n    stored = {}\n    try:\n        stored = get_group(\"email\")\n    except Exception:\n        stored = {}\n    def pick(name, env, default=\"\"):\n        return str(stored.get(name) or \"\").strip() or _env(env, default)\n    provider = (str(stored.get(\"provider\") or \"\").strip().lower()\n                or (\"brevo\" if _env(\"BREVO_API_KEY\") else \"smtp\"))\n    return {\n        \"provider\": provider,\n        \"smtp_host\": pick(\"smtp_host\", \"SMTP_HOST\"),\n        \"smtp_port\": pick(\"smtp_port\", \"SMTP_PORT\", \"587\"),\n        \"smtp_user\": pick(\"smtp_user\", \"SMTP_USER\"),\n        \"smtp_password\": str(stored.get(\"smtp_password\") or \"\")\n                         or os_secret_env(\"SMTP_PASSWORD\"),\n        \"smtp_from\": pick(\"smtp_from\", \"SMTP_FROM\",\n                          \"OmniFlow <no-reply@omniflow.app>\"),\n        \"brevo_api_key\": str(stored.get(\"brevo_api_key\") or \"\")\n                         or os_secret_env(\"BREVO_API_KEY\"),\n        \"reports_to\": pick(\"reports_to\", \"OMNIFLOW_REPORTS_TO\"),\n    }\n\n\ndef os_secret_env(name: str) -> str:\n    \"\"\"Secret env fallback (os.environ read kept out of the hot path).\"\"\"\n    import os\n    return os.environ.get(name, \"\")\n\n\ndef flag(name: str) -> bool:\n    \"\"\"AI/feature switch state; every switch defaults OFF.\"\"\"\n    try:\n        raw = str(get_setting(\"flags.\" + name, \"\") or \"\").strip().lower()\n    except Exception:\n        return False\n    return raw in (\"on\", \"1\", \"true\", \"yes\")\n\n\ndef stt_config() -> dict:\n    \"\"\"Effective speech-to-text config: admin panel first, env fallback.\n\n    portal_media owns the base/model defaults (OpenAI-compatible whisper\n    endpoint); this only resolves what the owner saved (or the env).\n    \"\"\"\n    stored = {}\n    try:\n        stored = get_group(\"stt\")\n    except Exception:\n        stored = {}\n    return {\n        \"api_key\": str(stored.get(\"api_key\")\n                       or _env(\"OMNIFLOW_STT_API_KEY\", \"\")),\n        \"base_url\": str(stored.get(\"base_url\")\n                        or _env(\"OMNIFLOW_STT_BASE\", \"\")),\n        \"model\": str(stored.get(\"model\")\n                     or _env(\"OMNIFLOW_STT_MODEL\", \"\")),\n    }\n\n\nEMBED_MODES = (\"on\", \"off\")\nGEMINI_HOST_HINT = \"generativelanguage.googleapis.com\"\n\n\ndef _embed_default_model(base_url: str) -> str:\n    if GEMINI_HOST_HINT in str(base_url or \"\"):\n        return _env(\"OF_EMBED_MODEL_GEMINI\", \"gemini-embedding-001\")\n    return _env(\"OF_EMBED_MODEL_DEFAULT\", \"text-embedding-3-small\")\n\n\ndef _embed_default_min_sim(model: str) -> int:\n    # Similarity scales differ per model family: Gemini vectors sit higher\n    # for unrelated text than OpenAI's. Owner/env can always override.\n    if \"gemini\" in str(model or \"\").lower():\n        return int(_env(\"OF_KB_EMBED_MIN_SIM_GEMINI\", \"60\") or 60)\n    return int(_env(\"OF_KB_EMBED_MIN_SIM_DEFAULT\", \"30\") or 30)\n\n\ndef _int_or(value, default: int, low: int, high: int) -> int:\n    try:\n        number = int(str(value).strip())\n    except Exception:\n        return default\n    return max(low, min(high, number))\n\n\ndef embed_config() -> dict:\n    \"\"\"Effective knowledge-embedding config: admin panel first, env next,\n    then the AI engine's own base/key. Uses get_setting (30 s TTL cache)\n    because retrieval consults it on the reply path. Fail-soft.\n\n    {mode: on|off, active: bool, reason: active|off|no_key|llm_disabled,\n     api_key, base_url, model, dimensions (0 = provider default),\n     min_similarity (0..1), key_source: embeddings|env|llm|none}\n    \"\"\"\n    def setting(name: str) -> str:\n        try:\n            return str(get_setting(\"embeddings.\" + name, \"\") or \"\").strip()\n        except Exception:\n            return \"\"\n\n    def llm_setting(name: str) -> str:\n        try:\n            return str(get_setting(\"llm.\" + name, \"\") or \"\").strip()\n        except Exception:\n            return \"\"\n\n    mode = (setting(\"mode\") or _env(\"OF_KB_EMBED_MODE\", \"on\")).lower()\n    if mode not in EMBED_MODES:\n        mode = \"on\"\n    key_source = \"none\"\n    api_key = setting(\"api_key\")\n    if api_key:\n        key_source = \"embeddings\"\n    elif _env(\"OF_EMBED_API_KEY\", \"\"):\n        api_key, key_source = _env(\"OF_EMBED_API_KEY\", \"\"), \"env\"\n    else:\n        api_key = llm_setting(\"api_key\") or _env(\"OF_LLM_API_KEY\", \"\")\n        key_source = \"llm\" if api_key else \"none\"\n    base_url = (setting(\"base_url\") or _env(\"OF_EMBED_BASE_URL\", \"\")\n                or llm_setting(\"base_url\")\n                or _env(\"OF_LLM_BASE_URL\", \"https://api.openai.com/v1\"))\n    base_url = base_url.rstrip(\"/\")\n    model = (setting(\"model\") or _env(\"OF_EMBED_MODEL\", \"\")\n             or _embed_default_model(base_url))\n    dimensions = _int_or(setting(\"dimensions\")\n                         or _env(\"OF_EMBED_DIMENSIONS\", \"256\"), 256, 0, 4096)\n    min_sim = _int_or(setting(\"min_similarity\")\n                      or _env(\"OF_KB_EMBED_MIN_SIM\", \"\"),\n                      _embed_default_min_sim(model), 0, 100)\n    llm_enabled = _env(\"OF_LLM_ENABLED\", \"1\").lower() not in (\n        \"0\", \"false\", \"no\", \"off\")\n    if mode == \"off\":\n        reason = \"off\"\n    elif not api_key:\n        reason = \"no_key\"\n    elif key_source == \"llm\" and not llm_enabled:\n        reason = \"llm_disabled\"\n    else:\n        reason = \"active\"\n    return {\n        \"mode\": mode,\n        \"active\": reason == \"active\",\n        \"reason\": reason,\n        \"api_key\": api_key,\n        \"base_url\": base_url,\n        \"model\": model,\n        \"dimensions\": dimensions,\n        \"min_similarity\": min_sim / 100.0,\n        \"key_source\": key_source,\n    }\n\n");
writeNewRepair("omniflow-backend-patch/portal_ai_usage.py", "(\"kb_embed\", \"Knowledge semantic index\"),", false,
    "\"\"\"AI usage + cost ledger (MASTER-UPGRADE platform service).\n\nEvery real LLM call the platform makes goes through ``portal_llm.chat_json``;\nthat function now reports each call here (feature, model, prompt/completion\ntokens straight from the provider's ``usage`` block, latency, ok/failed).\nCallers tag their calls with ``portal_llm.usage_scope(feature, client_id,\ncur)``; a call without a scope is still counted (feature \"other\",\nworkspace 0 = platform).\n\nCost is an ESTIMATE from a price table the platform admin saves\n(Admin -> Integrations -> AI engine -> \"Model prices (JSON)\" =\n``{\"gpt-4o-mini\": {\"input\": 0.15, \"output\": 0.60}}`` in USD per million\ntokens; ``\"default\"`` covers unlisted models; env ``OF_AI_PRICES_JSON`` is\nthe fallback). No prices saved = tokens only, cost shown as \"not\nconfigured\" - never a made-up number.\n\nLaws: recording is fail-soft (a ledger problem never fails the customer\nmessage); with a caller cursor the row rides that transaction behind a\nSAVEPOINT, otherwise one short connection; ``OF_AI_USAGE=0`` switches the\nledger off. Read API is tenant-scoped and open to API keys (read-only).\n\"\"\"\n\nimport json\nimport logging\nimport os\nfrom typing import Any, Dict, List, Optional\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import PortalAuthUnavailable, authenticate_portal_request\n\nlogger = logging.getLogger(\"omniflow.portal-ai-usage\")\n\nbp = Blueprint(\"portal_ai_usage\", __name__, url_prefix=\"/api/v1/portal\")\n\nTABLE = \"portal_ai_usage\"\nENABLED = os.environ.get(\n    \"OF_AI_USAGE\", \"1\").strip().lower() not in (\"0\", \"false\", \"no\", \"off\")\nMAX_DAYS = int(os.environ.get(\"OF_AI_USAGE_MAX_DAYS\", \"90\") or 90)\nDEFAULT_DAYS = 7\n\n#: feature key -> owner-facing label (the usage card renders from this).\nFEATURES = (\n    (\"brain\", \"AI Brain answers & drafts\"),\n    (\"workflow\", \"Workflow decisions\"),\n    (\"intent\", \"Intent classification\"),\n    (\"sentiment\", \"Sentiment\"),\n    (\"negotiation\", \"Negotiation replies\"),\n    (\"copy\", \"Broadcast copy\"),\n    (\"bi_narrative\", \"Business insights narrative\"),\n    (\"kb_embed\", \"Knowledge semantic index\"),\n    (\"ai_quality_label\", \"Labelled-set live checks\"),\n    (\"other\", \"Other\"),\n)\nFEATURE_LABELS = dict(FEATURES)\n\n_DDL_READY = False\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_ai_usage (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL DEFAULT 0,\n  feature TEXT NOT NULL DEFAULT 'other',\n  model TEXT NOT NULL DEFAULT '',\n  prompt_tokens INTEGER NOT NULL DEFAULT 0,\n  completion_tokens INTEGER NOT NULL DEFAULT 0,\n  latency_ms INTEGER NOT NULL DEFAULT 0,\n  ok BOOLEAN NOT NULL DEFAULT TRUE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_ai_usage_client_time\n  ON portal_ai_usage (client_id, created_at DESC);\nALTER TABLE portal_ai_usage\n  ADD COLUMN IF NOT EXISTS agent_id BIGINT;\nCREATE INDEX IF NOT EXISTS idx_portal_ai_usage_agent\n  ON portal_ai_usage (client_id, agent_id, created_at DESC);\n\"\"\"\n\n\ndef _ensure_ddl(cur) -> None:\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_DDL)\n    _DDL_READY = True\n\n\n# ---------------------------------------------------------------------------\n# write path\n# ---------------------------------------------------------------------------\n\ndef _insert(cur, client_id: int, feature: str, model: str, prompt_tokens: int,\n            completion_tokens: int, latency_ms: int, ok: bool,\n            agent_id: int = 0) -> None:\n    aid = int(agent_id or 0) or None\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(TABLE) +\n        \" (client_id, feature, model, prompt_tokens, completion_tokens,\"\n        \" latency_ms, ok, agent_id) VALUES (%s, %s, %s, %s, %s, %s, %s, %s)\",\n        (int(client_id or 0), str(feature or \"other\")[:40],\n         str(model or \"\")[:80], max(0, int(prompt_tokens or 0)),\n         max(0, int(completion_tokens or 0)), max(0, int(latency_ms or 0)),\n         bool(ok), aid),\n    )\n\n\ndef record(client_id: int, feature: str, model: str, prompt_tokens: int,\n           completion_tokens: int, latency_ms: int, ok: bool,\n           cur=None, agent_id: int = 0) -> bool:\n    \"\"\"Append one call to the ledger. Never raises; False when skipped.\"\"\"\n    if not ENABLED:\n        return False\n    feature = feature if feature in FEATURE_LABELS else \"other\"\n    if cur is not None:\n        try:\n            cur.execute(\"SAVEPOINT of_ai_usage\")\n            _ensure_ddl(cur)\n            _insert(cur, client_id, feature, model, prompt_tokens,\n                    completion_tokens, latency_ms, ok, agent_id=agent_id)\n            cur.execute(\"RELEASE SAVEPOINT of_ai_usage\")\n            return True\n        except Exception as error:\n            logger.warning(\"ai usage record (tx) failed: %s\", error)\n            try:\n                cur.execute(\"ROLLBACK TO SAVEPOINT of_ai_usage\")\n            except Exception:\n                pass\n            return False\n    try:\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as own:\n                _ensure_ddl(own)\n                _insert(own, client_id, feature, model, prompt_tokens,\n                        completion_tokens, latency_ms, ok, agent_id=agent_id)\n            conn.commit()\n        finally:\n            conn.close()\n        return True\n    except Exception as error:\n        logger.warning(\"ai usage record failed: %s\", error)\n        return False\n\n\n# ---------------------------------------------------------------------------\n# platform gate (admin AI Control Center): kill switch + daily call cap\n# ---------------------------------------------------------------------------\n\nGATE_KILL_SWITCH = \"kill_switch\"\nGATE_DAILY_CAP = \"daily_cap\"\n#: reasons -> owner-facing sentence (notification detail)\nGATE_MESSAGES = {\n    GATE_KILL_SWITCH: \"AI answering is paused platform-wide by the OmniFlow\"\n                      \" team. Replies and drafts resume automatically when\"\n                      \" the pause is lifted.\",\n    GATE_DAILY_CAP: \"This workspace reached its daily AI call limit. AI\"\n                    \" answers and drafts pause until the limit resets;\"\n                    \" human replies are unaffected.\",\n}\n\n\ndef _count_calls_since(cur, client_id: int, hours: int) -> int:\n    cur.execute(\n        \"SELECT COUNT(*) AS calls FROM \" + portal_db._q(TABLE) +\n        \" WHERE client_id = %s\"\n        \" AND created_at > NOW() - make_interval(hours => %s)\",\n        (int(client_id or 0), int(hours)),\n    )\n    rows = portal_db.rows(cur)\n    return int((rows[0] if rows else {}).get(\"calls\") or 0)\n\n\ndef calls_since(client_id: int, hours: int = 24, cur=None) -> Optional[int]:\n    \"\"\"LLM calls this workspace made in the last ``hours`` (None when the\n    ledger cannot be read). With a caller cursor the query rides that\n    transaction behind a SAVEPOINT; otherwise one short connection.\"\"\"\n    if cur is not None:\n        try:\n            cur.execute(\"SAVEPOINT of_ai_gate\")\n            value = _count_calls_since(cur, client_id, hours)\n            cur.execute(\"RELEASE SAVEPOINT of_ai_gate\")\n            return value\n        except Exception as error:\n            logger.warning(\"ai gate count (tx) failed: %s\", error)\n            try:\n                cur.execute(\"ROLLBACK TO SAVEPOINT of_ai_gate\")\n            except Exception:\n                pass\n            return None\n    try:\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as own:\n                value = _count_calls_since(own, client_id, hours)\n            conn.commit()\n        finally:\n            conn.close()\n        return value\n    except Exception as error:\n        logger.warning(\"ai gate count failed: %s\", error)\n        return None\n\n\ndef gate(feature: str, client_id: int, cur=None) -> Optional[str]:\n    \"\"\"Platform gate every LLM call passes before the provider is called.\n\n    Returns None when the call may proceed, else the blocking reason\n    (``kill_switch`` | ``daily_cap``). Fail-open: a storage problem never\n    blocks a call. When a workspace hits its daily cap the owner gets ONE\n    in-app notification per day (dedupe key ``aicap:<client>:<day>``).\n    \"\"\"\n    try:\n        import platform_settings\n\n        controls = platform_settings.ai_controls()\n    except Exception:\n        return None\n    if controls.get(\"kill_switch\"):\n        return GATE_KILL_SWITCH\n    cap = int(controls.get(\"daily_call_cap\") or 0)\n    client_id = int(client_id or 0)\n    if cap <= 0 or client_id <= 0:\n        return None\n    used = calls_since(client_id, 24, cur=cur)\n    if used is None or used < cap:\n        return None\n    try:\n        import datetime as _dt\n\n        import portal_notify\n\n        day = _dt.datetime.utcnow().strftime(\"%Y%m%d\")\n        portal_notify.notify(\n            client_id, \"system\", \"Daily AI call limit reached\",\n            GATE_MESSAGES[GATE_DAILY_CAP] + \" (\" + str(used) + \"/\" + str(cap)\n            + \" calls in the last 24 hours.)\", severity=\"high\",\n            dedupe_key=\"aicap:\" + str(client_id) + \":\" + day)\n    except Exception:\n        pass\n    return GATE_DAILY_CAP\n\n\n# ---------------------------------------------------------------------------\n# prices + cost\n# ---------------------------------------------------------------------------\n\ndef prices() -> Dict[str, Dict[str, float]]:\n    \"\"\"{model: {\"input\": usd_per_1M, \"output\": usd_per_1M}} from the admin\n    panel (llm.prices_json) or OF_AI_PRICES_JSON; {} when not configured.\"\"\"\n    raw = \"\"\n    try:\n        import platform_settings\n\n        raw = str(platform_settings.get_setting(\"llm.prices_json\", \"\") or \"\")\n    except Exception:\n        raw = \"\"\n    if not raw.strip():\n        raw = os.environ.get(\"OF_AI_PRICES_JSON\", \"\")\n    return parse_prices(raw)\n\n\ndef parse_prices(raw: Any) -> Dict[str, Dict[str, float]]:\n    try:\n        data = json.loads(raw) if isinstance(raw, str) else raw\n    except Exception:\n        return {}\n    if not isinstance(data, dict):\n        return {}\n    out: Dict[str, Dict[str, float]] = {}\n    for model, value in data.items():\n        if not isinstance(value, dict):\n            continue\n        try:\n            entry = {\"input\": float(value.get(\"input\") or 0),\n                     \"output\": float(value.get(\"output\") or 0)}\n        except Exception:\n            continue\n        if entry[\"input\"] < 0 or entry[\"output\"] < 0:\n            continue\n        out[str(model).strip().lower()] = entry\n    return out\n\n\ndef estimate_cost(model: str, prompt_tokens: int, completion_tokens: int,\n                  table: Dict[str, Dict[str, float]]) -> Optional[float]:\n    \"\"\"USD for one call, or None when the model is not priced.\"\"\"\n    if not table:\n        return None\n    price = table.get(str(model or \"\").strip().lower()) or table.get(\"default\")\n    if not price:\n        return None\n    return round((max(0, int(prompt_tokens or 0)) * price[\"input\"]\n                  + max(0, int(completion_tokens or 0)) * price[\"output\"])\n                 / 1000000.0, 6)\n\n\n# ---------------------------------------------------------------------------\n# read path\n# ---------------------------------------------------------------------------\n\ndef _days(value: Any) -> int:\n    try:\n        days = int(value or DEFAULT_DAYS)\n    except Exception:\n        days = DEFAULT_DAYS\n    return max(1, min(MAX_DAYS, days))\n\n\ndef usage_report(cur, client_id: int, days: int = DEFAULT_DAYS) -> Dict[str, Any]:\n    \"\"\"Totals + per-feature / per-model / per-day rollups for the window.\"\"\"\n    days = _days(days)\n    cur.execute(\n        \"SELECT feature, model, ok, agent_id, COUNT(*) AS calls,\"\n        \" COALESCE(SUM(prompt_tokens), 0) AS prompt_tokens,\"\n        \" COALESCE(SUM(completion_tokens), 0) AS completion_tokens,\"\n        \" COALESCE(AVG(latency_ms), 0) AS avg_latency_ms\"\n        \" FROM \" + portal_db._q(TABLE) +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY feature, model, ok, agent_id\",\n        (client_id, days),\n    )\n    groups = portal_db.rows(cur)\n    cur.execute(\n        \"SELECT DATE(created_at) AS day, COUNT(*) AS calls,\"\n        \" COALESCE(SUM(prompt_tokens + completion_tokens), 0) AS tokens\"\n        \" FROM \" + portal_db._q(TABLE) +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY DATE(created_at) ORDER BY day\",\n        (client_id, days),\n    )\n    daily = portal_db.rows(cur)\n    table = prices()\n    totals = {\"calls\": 0, \"failed\": 0, \"prompt_tokens\": 0,\n              \"completion_tokens\": 0, \"latency_weighted\": 0.0,\n              \"cost_usd\": 0.0, \"unpriced_calls\": 0}\n    by_feature: Dict[str, Dict[str, Any]] = {}\n    by_model: Dict[str, Dict[str, Any]] = {}\n    by_agent: Dict[int, Dict[str, Any]] = {}\n    for row in groups:\n        calls = int(row.get(\"calls\") or 0)\n        p_tok = int(row.get(\"prompt_tokens\") or 0)\n        c_tok = int(row.get(\"completion_tokens\") or 0)\n        ok = bool(row.get(\"ok\"))\n        model = str(row.get(\"model\") or \"\")\n        feature = str(row.get(\"feature\") or \"other\")\n        try:\n            agent_id = int(row.get(\"agent_id\") or 0)\n        except Exception:\n            agent_id = 0\n        cost = estimate_cost(model, p_tok, c_tok, table)\n        totals[\"calls\"] += calls\n        totals[\"failed\"] += 0 if ok else calls\n        totals[\"prompt_tokens\"] += p_tok\n        totals[\"completion_tokens\"] += c_tok\n        totals[\"latency_weighted\"] += float(row.get(\"avg_latency_ms\") or 0) * calls\n        if cost is None:\n            totals[\"unpriced_calls\"] += calls\n        else:\n            totals[\"cost_usd\"] += cost\n        for bucket, key in ((by_feature, feature), (by_model, model or \"(unknown)\")):\n            entry = bucket.setdefault(key, {\"calls\": 0, \"failed\": 0, \"tokens\": 0,\n                                            \"cost_usd\": 0.0, \"priced\": True})\n            entry[\"calls\"] += calls\n            entry[\"failed\"] += 0 if ok else calls\n            entry[\"tokens\"] += p_tok + c_tok\n            if cost is None:\n                entry[\"priced\"] = False\n            else:\n                entry[\"cost_usd\"] += cost\n        # agent_id 0 / NULL = unattributed (default brain, no persona)\n        akey = agent_id if agent_id > 0 else 0\n        aentry = by_agent.setdefault(akey, {\"calls\": 0, \"failed\": 0, \"tokens\": 0,\n                                            \"cost_usd\": 0.0, \"priced\": True})\n        aentry[\"calls\"] += calls\n        aentry[\"failed\"] += 0 if ok else calls\n        aentry[\"tokens\"] += p_tok + c_tok\n        if cost is None:\n            aentry[\"priced\"] = False\n        else:\n            aentry[\"cost_usd\"] += cost\n    priced = bool(table) and totals[\"unpriced_calls\"] == 0\n    calls = totals[\"calls\"]\n    agent_names: Dict[int, str] = {}\n    try:\n        ids = [aid for aid in by_agent.keys() if aid > 0]\n        if ids:\n            cur.execute(\n                \"SELECT id, name FROM \" + portal_db._q(\"portal_agents\") +\n                \" WHERE client_id = %s AND id = ANY(%s)\",\n                (client_id, ids),\n            )\n            for row in portal_db.rows(cur):\n                agent_names[int(row.get(\"id\") or 0)] = str(row.get(\"name\") or \"\")\n    except Exception as error:\n        logger.warning(\"ai usage agent names failed: %s\", error)\n    by_agent_list = []\n    for aid, v in sorted(by_agent.items(), key=lambda i: -i[1][\"calls\"]):\n        by_agent_list.append({\n            \"agent_id\": aid if aid > 0 else None,\n            \"name\": (agent_names.get(aid) if aid > 0 else None) or (\n                \"Unattributed\" if aid == 0 else (\"Agent #\" + str(aid))),\n            \"calls\": v[\"calls\"],\n            \"failed\": v[\"failed\"],\n            \"tokens\": v[\"tokens\"],\n            \"cost_usd\": round(v[\"cost_usd\"], 4) if v[\"priced\"] and table else None,\n            \"share\": round(v[\"calls\"] / calls, 3) if calls else 0.0,\n        })\n    return {\n        \"days\": days,\n        \"totals\": {\n            \"calls\": calls,\n            \"failed\": totals[\"failed\"],\n            \"prompt_tokens\": totals[\"prompt_tokens\"],\n            \"completion_tokens\": totals[\"completion_tokens\"],\n            \"tokens\": totals[\"prompt_tokens\"] + totals[\"completion_tokens\"],\n            \"avg_latency_ms\": (int(totals[\"latency_weighted\"] / calls)\n                               if calls else 0),\n            \"cost_usd\": round(totals[\"cost_usd\"], 4) if priced else None,\n            \"priced\": priced,\n            \"unpriced_calls\": totals[\"unpriced_calls\"],\n        },\n        \"by_feature\": [\n            {\"feature\": key, \"label\": FEATURE_LABELS.get(key, key),\n             \"calls\": v[\"calls\"], \"failed\": v[\"failed\"], \"tokens\": v[\"tokens\"],\n             \"cost_usd\": round(v[\"cost_usd\"], 4) if v[\"priced\"] and table else None}\n            for key, v in sorted(by_feature.items(), key=lambda i: -i[1][\"calls\"])\n        ],\n        \"by_model\": [\n            {\"model\": key, \"calls\": v[\"calls\"], \"failed\": v[\"failed\"],\n             \"tokens\": v[\"tokens\"],\n             \"cost_usd\": round(v[\"cost_usd\"], 4) if v[\"priced\"] and table else None}\n            for key, v in sorted(by_model.items(), key=lambda i: -i[1][\"calls\"])\n        ],\n        \"by_day\": [\n            {\"day\": (row.get(\"day\").isoformat() if hasattr(row.get(\"day\"), \"isoformat\")\n                     else str(row.get(\"day\"))),\n             \"calls\": int(row.get(\"calls\") or 0),\n             \"tokens\": int(row.get(\"tokens\") or 0)}\n            for row in daily\n        ],\n        \"prices_configured\": bool(table),\n        \"features\": [{\"key\": k, \"label\": l} for k, l in FEATURES],\n        \"by_agent\": by_agent_list,\n    }\n\n\n# ---------------------------------------------------------------------------\n# HTTP\n# ---------------------------------------------------------------------------\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    return principal, None\n\n\n@bp.get(\"/ai/usage\")\ndef get_usage():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    days = _days(request.args.get(\"days\"))\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            report = usage_report(cur, client_id, days)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify(report), 200\n");
writeNewRepair("OmniFlow-Control-Plane/portal_ai_usage.py", "(\"kb_embed\", \"Knowledge semantic index\"),", true,
    "\"\"\"AI usage + cost ledger (MASTER-UPGRADE platform service).\n\nEvery real LLM call the platform makes goes through ``portal_llm.chat_json``;\nthat function now reports each call here (feature, model, prompt/completion\ntokens straight from the provider's ``usage`` block, latency, ok/failed).\nCallers tag their calls with ``portal_llm.usage_scope(feature, client_id,\ncur)``; a call without a scope is still counted (feature \"other\",\nworkspace 0 = platform).\n\nCost is an ESTIMATE from a price table the platform admin saves\n(Admin -> Integrations -> AI engine -> \"Model prices (JSON)\" =\n``{\"gpt-4o-mini\": {\"input\": 0.15, \"output\": 0.60}}`` in USD per million\ntokens; ``\"default\"`` covers unlisted models; env ``OF_AI_PRICES_JSON`` is\nthe fallback). No prices saved = tokens only, cost shown as \"not\nconfigured\" - never a made-up number.\n\nLaws: recording is fail-soft (a ledger problem never fails the customer\nmessage); with a caller cursor the row rides that transaction behind a\nSAVEPOINT, otherwise one short connection; ``OF_AI_USAGE=0`` switches the\nledger off. Read API is tenant-scoped and open to API keys (read-only).\n\"\"\"\n\nimport json\nimport logging\nimport os\nfrom typing import Any, Dict, List, Optional\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import PortalAuthUnavailable, authenticate_portal_request\n\nlogger = logging.getLogger(\"omniflow.portal-ai-usage\")\n\nbp = Blueprint(\"portal_ai_usage\", __name__, url_prefix=\"/api/v1/portal\")\n\nTABLE = \"portal_ai_usage\"\nENABLED = os.environ.get(\n    \"OF_AI_USAGE\", \"1\").strip().lower() not in (\"0\", \"false\", \"no\", \"off\")\nMAX_DAYS = int(os.environ.get(\"OF_AI_USAGE_MAX_DAYS\", \"90\") or 90)\nDEFAULT_DAYS = 7\n\n#: feature key -> owner-facing label (the usage card renders from this).\nFEATURES = (\n    (\"brain\", \"AI Brain answers & drafts\"),\n    (\"workflow\", \"Workflow decisions\"),\n    (\"intent\", \"Intent classification\"),\n    (\"sentiment\", \"Sentiment\"),\n    (\"negotiation\", \"Negotiation replies\"),\n    (\"copy\", \"Broadcast copy\"),\n    (\"bi_narrative\", \"Business insights narrative\"),\n    (\"kb_embed\", \"Knowledge semantic index\"),\n    (\"ai_quality_label\", \"Labelled-set live checks\"),\n    (\"other\", \"Other\"),\n)\nFEATURE_LABELS = dict(FEATURES)\n\n_DDL_READY = False\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_ai_usage (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL DEFAULT 0,\n  feature TEXT NOT NULL DEFAULT 'other',\n  model TEXT NOT NULL DEFAULT '',\n  prompt_tokens INTEGER NOT NULL DEFAULT 0,\n  completion_tokens INTEGER NOT NULL DEFAULT 0,\n  latency_ms INTEGER NOT NULL DEFAULT 0,\n  ok BOOLEAN NOT NULL DEFAULT TRUE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_ai_usage_client_time\n  ON portal_ai_usage (client_id, created_at DESC);\nALTER TABLE portal_ai_usage\n  ADD COLUMN IF NOT EXISTS agent_id BIGINT;\nCREATE INDEX IF NOT EXISTS idx_portal_ai_usage_agent\n  ON portal_ai_usage (client_id, agent_id, created_at DESC);\n\"\"\"\n\n\ndef _ensure_ddl(cur) -> None:\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_DDL)\n    _DDL_READY = True\n\n\n# ---------------------------------------------------------------------------\n# write path\n# ---------------------------------------------------------------------------\n\ndef _insert(cur, client_id: int, feature: str, model: str, prompt_tokens: int,\n            completion_tokens: int, latency_ms: int, ok: bool,\n            agent_id: int = 0) -> None:\n    aid = int(agent_id or 0) or None\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(TABLE) +\n        \" (client_id, feature, model, prompt_tokens, completion_tokens,\"\n        \" latency_ms, ok, agent_id) VALUES (%s, %s, %s, %s, %s, %s, %s, %s)\",\n        (int(client_id or 0), str(feature or \"other\")[:40],\n         str(model or \"\")[:80], max(0, int(prompt_tokens or 0)),\n         max(0, int(completion_tokens or 0)), max(0, int(latency_ms or 0)),\n         bool(ok), aid),\n    )\n\n\ndef record(client_id: int, feature: str, model: str, prompt_tokens: int,\n           completion_tokens: int, latency_ms: int, ok: bool,\n           cur=None, agent_id: int = 0) -> bool:\n    \"\"\"Append one call to the ledger. Never raises; False when skipped.\"\"\"\n    if not ENABLED:\n        return False\n    feature = feature if feature in FEATURE_LABELS else \"other\"\n    if cur is not None:\n        try:\n            cur.execute(\"SAVEPOINT of_ai_usage\")\n            _ensure_ddl(cur)\n            _insert(cur, client_id, feature, model, prompt_tokens,\n                    completion_tokens, latency_ms, ok, agent_id=agent_id)\n            cur.execute(\"RELEASE SAVEPOINT of_ai_usage\")\n            return True\n        except Exception as error:\n            logger.warning(\"ai usage record (tx) failed: %s\", error)\n            try:\n                cur.execute(\"ROLLBACK TO SAVEPOINT of_ai_usage\")\n            except Exception:\n                pass\n            return False\n    try:\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as own:\n                _ensure_ddl(own)\n                _insert(own, client_id, feature, model, prompt_tokens,\n                        completion_tokens, latency_ms, ok, agent_id=agent_id)\n            conn.commit()\n        finally:\n            conn.close()\n        return True\n    except Exception as error:\n        logger.warning(\"ai usage record failed: %s\", error)\n        return False\n\n\n# ---------------------------------------------------------------------------\n# platform gate (admin AI Control Center): kill switch + daily call cap\n# ---------------------------------------------------------------------------\n\nGATE_KILL_SWITCH = \"kill_switch\"\nGATE_DAILY_CAP = \"daily_cap\"\n#: reasons -> owner-facing sentence (notification detail)\nGATE_MESSAGES = {\n    GATE_KILL_SWITCH: \"AI answering is paused platform-wide by the OmniFlow\"\n                      \" team. Replies and drafts resume automatically when\"\n                      \" the pause is lifted.\",\n    GATE_DAILY_CAP: \"This workspace reached its daily AI call limit. AI\"\n                    \" answers and drafts pause until the limit resets;\"\n                    \" human replies are unaffected.\",\n}\n\n\ndef _count_calls_since(cur, client_id: int, hours: int) -> int:\n    cur.execute(\n        \"SELECT COUNT(*) AS calls FROM \" + portal_db._q(TABLE) +\n        \" WHERE client_id = %s\"\n        \" AND created_at > NOW() - make_interval(hours => %s)\",\n        (int(client_id or 0), int(hours)),\n    )\n    rows = portal_db.rows(cur)\n    return int((rows[0] if rows else {}).get(\"calls\") or 0)\n\n\ndef calls_since(client_id: int, hours: int = 24, cur=None) -> Optional[int]:\n    \"\"\"LLM calls this workspace made in the last ``hours`` (None when the\n    ledger cannot be read). With a caller cursor the query rides that\n    transaction behind a SAVEPOINT; otherwise one short connection.\"\"\"\n    if cur is not None:\n        try:\n            cur.execute(\"SAVEPOINT of_ai_gate\")\n            value = _count_calls_since(cur, client_id, hours)\n            cur.execute(\"RELEASE SAVEPOINT of_ai_gate\")\n            return value\n        except Exception as error:\n            logger.warning(\"ai gate count (tx) failed: %s\", error)\n            try:\n                cur.execute(\"ROLLBACK TO SAVEPOINT of_ai_gate\")\n            except Exception:\n                pass\n            return None\n    try:\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as own:\n                value = _count_calls_since(own, client_id, hours)\n            conn.commit()\n        finally:\n            conn.close()\n        return value\n    except Exception as error:\n        logger.warning(\"ai gate count failed: %s\", error)\n        return None\n\n\ndef gate(feature: str, client_id: int, cur=None) -> Optional[str]:\n    \"\"\"Platform gate every LLM call passes before the provider is called.\n\n    Returns None when the call may proceed, else the blocking reason\n    (``kill_switch`` | ``daily_cap``). Fail-open: a storage problem never\n    blocks a call. When a workspace hits its daily cap the owner gets ONE\n    in-app notification per day (dedupe key ``aicap:<client>:<day>``).\n    \"\"\"\n    try:\n        import platform_settings\n\n        controls = platform_settings.ai_controls()\n    except Exception:\n        return None\n    if controls.get(\"kill_switch\"):\n        return GATE_KILL_SWITCH\n    cap = int(controls.get(\"daily_call_cap\") or 0)\n    client_id = int(client_id or 0)\n    if cap <= 0 or client_id <= 0:\n        return None\n    used = calls_since(client_id, 24, cur=cur)\n    if used is None or used < cap:\n        return None\n    try:\n        import datetime as _dt\n\n        import portal_notify\n\n        day = _dt.datetime.utcnow().strftime(\"%Y%m%d\")\n        portal_notify.notify(\n            client_id, \"system\", \"Daily AI call limit reached\",\n            GATE_MESSAGES[GATE_DAILY_CAP] + \" (\" + str(used) + \"/\" + str(cap)\n            + \" calls in the last 24 hours.)\", severity=\"high\",\n            dedupe_key=\"aicap:\" + str(client_id) + \":\" + day)\n    except Exception:\n        pass\n    return GATE_DAILY_CAP\n\n\n# ---------------------------------------------------------------------------\n# prices + cost\n# ---------------------------------------------------------------------------\n\ndef prices() -> Dict[str, Dict[str, float]]:\n    \"\"\"{model: {\"input\": usd_per_1M, \"output\": usd_per_1M}} from the admin\n    panel (llm.prices_json) or OF_AI_PRICES_JSON; {} when not configured.\"\"\"\n    raw = \"\"\n    try:\n        import platform_settings\n\n        raw = str(platform_settings.get_setting(\"llm.prices_json\", \"\") or \"\")\n    except Exception:\n        raw = \"\"\n    if not raw.strip():\n        raw = os.environ.get(\"OF_AI_PRICES_JSON\", \"\")\n    return parse_prices(raw)\n\n\ndef parse_prices(raw: Any) -> Dict[str, Dict[str, float]]:\n    try:\n        data = json.loads(raw) if isinstance(raw, str) else raw\n    except Exception:\n        return {}\n    if not isinstance(data, dict):\n        return {}\n    out: Dict[str, Dict[str, float]] = {}\n    for model, value in data.items():\n        if not isinstance(value, dict):\n            continue\n        try:\n            entry = {\"input\": float(value.get(\"input\") or 0),\n                     \"output\": float(value.get(\"output\") or 0)}\n        except Exception:\n            continue\n        if entry[\"input\"] < 0 or entry[\"output\"] < 0:\n            continue\n        out[str(model).strip().lower()] = entry\n    return out\n\n\ndef estimate_cost(model: str, prompt_tokens: int, completion_tokens: int,\n                  table: Dict[str, Dict[str, float]]) -> Optional[float]:\n    \"\"\"USD for one call, or None when the model is not priced.\"\"\"\n    if not table:\n        return None\n    price = table.get(str(model or \"\").strip().lower()) or table.get(\"default\")\n    if not price:\n        return None\n    return round((max(0, int(prompt_tokens or 0)) * price[\"input\"]\n                  + max(0, int(completion_tokens or 0)) * price[\"output\"])\n                 / 1000000.0, 6)\n\n\n# ---------------------------------------------------------------------------\n# read path\n# ---------------------------------------------------------------------------\n\ndef _days(value: Any) -> int:\n    try:\n        days = int(value or DEFAULT_DAYS)\n    except Exception:\n        days = DEFAULT_DAYS\n    return max(1, min(MAX_DAYS, days))\n\n\ndef usage_report(cur, client_id: int, days: int = DEFAULT_DAYS) -> Dict[str, Any]:\n    \"\"\"Totals + per-feature / per-model / per-day rollups for the window.\"\"\"\n    days = _days(days)\n    cur.execute(\n        \"SELECT feature, model, ok, agent_id, COUNT(*) AS calls,\"\n        \" COALESCE(SUM(prompt_tokens), 0) AS prompt_tokens,\"\n        \" COALESCE(SUM(completion_tokens), 0) AS completion_tokens,\"\n        \" COALESCE(AVG(latency_ms), 0) AS avg_latency_ms\"\n        \" FROM \" + portal_db._q(TABLE) +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY feature, model, ok, agent_id\",\n        (client_id, days),\n    )\n    groups = portal_db.rows(cur)\n    cur.execute(\n        \"SELECT DATE(created_at) AS day, COUNT(*) AS calls,\"\n        \" COALESCE(SUM(prompt_tokens + completion_tokens), 0) AS tokens\"\n        \" FROM \" + portal_db._q(TABLE) +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY DATE(created_at) ORDER BY day\",\n        (client_id, days),\n    )\n    daily = portal_db.rows(cur)\n    table = prices()\n    totals = {\"calls\": 0, \"failed\": 0, \"prompt_tokens\": 0,\n              \"completion_tokens\": 0, \"latency_weighted\": 0.0,\n              \"cost_usd\": 0.0, \"unpriced_calls\": 0}\n    by_feature: Dict[str, Dict[str, Any]] = {}\n    by_model: Dict[str, Dict[str, Any]] = {}\n    by_agent: Dict[int, Dict[str, Any]] = {}\n    for row in groups:\n        calls = int(row.get(\"calls\") or 0)\n        p_tok = int(row.get(\"prompt_tokens\") or 0)\n        c_tok = int(row.get(\"completion_tokens\") or 0)\n        ok = bool(row.get(\"ok\"))\n        model = str(row.get(\"model\") or \"\")\n        feature = str(row.get(\"feature\") or \"other\")\n        try:\n            agent_id = int(row.get(\"agent_id\") or 0)\n        except Exception:\n            agent_id = 0\n        cost = estimate_cost(model, p_tok, c_tok, table)\n        totals[\"calls\"] += calls\n        totals[\"failed\"] += 0 if ok else calls\n        totals[\"prompt_tokens\"] += p_tok\n        totals[\"completion_tokens\"] += c_tok\n        totals[\"latency_weighted\"] += float(row.get(\"avg_latency_ms\") or 0) * calls\n        if cost is None:\n            totals[\"unpriced_calls\"] += calls\n        else:\n            totals[\"cost_usd\"] += cost\n        for bucket, key in ((by_feature, feature), (by_model, model or \"(unknown)\")):\n            entry = bucket.setdefault(key, {\"calls\": 0, \"failed\": 0, \"tokens\": 0,\n                                            \"cost_usd\": 0.0, \"priced\": True})\n            entry[\"calls\"] += calls\n            entry[\"failed\"] += 0 if ok else calls\n            entry[\"tokens\"] += p_tok + c_tok\n            if cost is None:\n                entry[\"priced\"] = False\n            else:\n                entry[\"cost_usd\"] += cost\n        # agent_id 0 / NULL = unattributed (default brain, no persona)\n        akey = agent_id if agent_id > 0 else 0\n        aentry = by_agent.setdefault(akey, {\"calls\": 0, \"failed\": 0, \"tokens\": 0,\n                                            \"cost_usd\": 0.0, \"priced\": True})\n        aentry[\"calls\"] += calls\n        aentry[\"failed\"] += 0 if ok else calls\n        aentry[\"tokens\"] += p_tok + c_tok\n        if cost is None:\n            aentry[\"priced\"] = False\n        else:\n            aentry[\"cost_usd\"] += cost\n    priced = bool(table) and totals[\"unpriced_calls\"] == 0\n    calls = totals[\"calls\"]\n    agent_names: Dict[int, str] = {}\n    try:\n        ids = [aid for aid in by_agent.keys() if aid > 0]\n        if ids:\n            cur.execute(\n                \"SELECT id, name FROM \" + portal_db._q(\"portal_agents\") +\n                \" WHERE client_id = %s AND id = ANY(%s)\",\n                (client_id, ids),\n            )\n            for row in portal_db.rows(cur):\n                agent_names[int(row.get(\"id\") or 0)] = str(row.get(\"name\") or \"\")\n    except Exception as error:\n        logger.warning(\"ai usage agent names failed: %s\", error)\n    by_agent_list = []\n    for aid, v in sorted(by_agent.items(), key=lambda i: -i[1][\"calls\"]):\n        by_agent_list.append({\n            \"agent_id\": aid if aid > 0 else None,\n            \"name\": (agent_names.get(aid) if aid > 0 else None) or (\n                \"Unattributed\" if aid == 0 else (\"Agent #\" + str(aid))),\n            \"calls\": v[\"calls\"],\n            \"failed\": v[\"failed\"],\n            \"tokens\": v[\"tokens\"],\n            \"cost_usd\": round(v[\"cost_usd\"], 4) if v[\"priced\"] and table else None,\n            \"share\": round(v[\"calls\"] / calls, 3) if calls else 0.0,\n        })\n    return {\n        \"days\": days,\n        \"totals\": {\n            \"calls\": calls,\n            \"failed\": totals[\"failed\"],\n            \"prompt_tokens\": totals[\"prompt_tokens\"],\n            \"completion_tokens\": totals[\"completion_tokens\"],\n            \"tokens\": totals[\"prompt_tokens\"] + totals[\"completion_tokens\"],\n            \"avg_latency_ms\": (int(totals[\"latency_weighted\"] / calls)\n                               if calls else 0),\n            \"cost_usd\": round(totals[\"cost_usd\"], 4) if priced else None,\n            \"priced\": priced,\n            \"unpriced_calls\": totals[\"unpriced_calls\"],\n        },\n        \"by_feature\": [\n            {\"feature\": key, \"label\": FEATURE_LABELS.get(key, key),\n             \"calls\": v[\"calls\"], \"failed\": v[\"failed\"], \"tokens\": v[\"tokens\"],\n             \"cost_usd\": round(v[\"cost_usd\"], 4) if v[\"priced\"] and table else None}\n            for key, v in sorted(by_feature.items(), key=lambda i: -i[1][\"calls\"])\n        ],\n        \"by_model\": [\n            {\"model\": key, \"calls\": v[\"calls\"], \"failed\": v[\"failed\"],\n             \"tokens\": v[\"tokens\"],\n             \"cost_usd\": round(v[\"cost_usd\"], 4) if v[\"priced\"] and table else None}\n            for key, v in sorted(by_model.items(), key=lambda i: -i[1][\"calls\"])\n        ],\n        \"by_day\": [\n            {\"day\": (row.get(\"day\").isoformat() if hasattr(row.get(\"day\"), \"isoformat\")\n                     else str(row.get(\"day\"))),\n             \"calls\": int(row.get(\"calls\") or 0),\n             \"tokens\": int(row.get(\"tokens\") or 0)}\n            for row in daily\n        ],\n        \"prices_configured\": bool(table),\n        \"features\": [{\"key\": k, \"label\": l} for k, l in FEATURES],\n        \"by_agent\": by_agent_list,\n    }\n\n\n# ---------------------------------------------------------------------------\n# HTTP\n# ---------------------------------------------------------------------------\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    return principal, None\n\n\n@bp.get(\"/ai/usage\")\ndef get_usage():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    days = _days(request.args.get(\"days\"))\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            report = usage_report(cur, client_id, days)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify(report), 200\n");
writeNewRepair("omniflow-backend-patch/portal_kb.py", "\"\"\"D1: a successful answer create/edit/delete schedules a semantic-index", false,
    "\"\"\"Portal knowledge base (customer Bearer + ingest-time auto-reply).\n\nBusinesses store answers (title, category, keywords, content) as knowledge\nbase entries. When an inbound WhatsApp message classifies as a general\ninformational intent (general, shipping, order_tracking, appointment) and a\nkeyword matches an active entry, the Control Plane queues a regular\nsend_message command; the laptop connector delivers it through the existing\ncommand polling. Complaints, refund requests and human-handoff messages are\nnever auto-answered. Matching is deterministic keyword scoring: zero AI cost.\n\"\"\"\n\nimport json\nimport logging\nimport re\nfrom typing import Any, Dict\n\nfrom flask import Blueprint, jsonify, request\n\nfrom portal_auth import PortalAuthUnavailable, authenticate_portal_request\nimport portal_db\nimport portal_plans\nimport portal_brands\n\n\nlogger = logging.getLogger(\"omniflow.portal-knowledge-base\")\n\nbp = Blueprint(\"portal_kb\", __name__, url_prefix=\"/api/v1\")\n\nKB_SETTINGS_TABLE = \"portal_kb_settings\"\nKB_TABLE = \"portal_kb_entries\"\n\n# Intents eligible for instant knowledge-base answers. Sensitive intents\n# (human_request, complaint, refund_return) and the sales intents owned by\n# the follow-up agent are deliberately excluded.\nKB_AUTO_INTENTS = (\"general\", \"shipping\", \"order_tracking\", \"appointment\")\n\n_INTENT_HINTS = (\n    (\"order_tracking\", (\"track\", \"tracking\", \"kahan\", \"status of my order\",\n                        \"order status\", \"mera order\")),\n    (\"shipping\", (\"delivery\", \"shipping\", \"charge\", \"kitne din\", \"courier\",\n                  \"pahunch\")),\n    (\"appointment\", (\"appointment\", \"booking\", \"book\", \"appointment time\")),\n)\n\n\ndef classify_intent(message_text) -> str:\n    \"\"\"Coarse intent for the KB auto-reply gate (keyword hints first).\n\n    B3: portal_intents.classify wraps this table as its offline fallback \u2014\n    callers get the LLM label when configured, keywords otherwise.\n    \"\"\"\n    text = _normalize_text(message_text)\n    if not text:\n        return \"general\"\n    for intent, hints in _INTENT_HINTS:\n        for hint in hints:\n            if hint in text:\n                return intent\n    return \"general\"\n\nMIN_KEYWORD_SCORE = 3  # one keyword hit = 3 points\nAUTO_REPLY_COOLDOWN_SECONDS = 120\nMAX_LIST_ENTRIES = 200\n\n\n_LANG_DDL_READY = False\n\n\ndef _ensure_lang_column(conn) -> None:\n    \"\"\"portal_kb_entries.lang lands lazily (older installs keep working).\"\"\"\n    global _LANG_DDL_READY\n    if _LANG_DDL_READY:\n        return\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"ALTER TABLE \" + portal_db._q(KB_TABLE) +\n                \" ADD COLUMN IF NOT EXISTS lang TEXT NOT NULL DEFAULT 'auto'\"\n            )\n        conn.commit()\n        _LANG_DDL_READY = True\n    except Exception:\n        try:\n            conn.rollback()\n        except Exception:\n            pass\n\n\ndef _ensure_brand_column(conn) -> None:\n    \"\"\"portal_kb_entries.brand_id lands lazily (multi-brand prep).\"\"\"\n    global _BRAND_DDL_READY\n    if _BRAND_DDL_READY:\n        return\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"ALTER TABLE \" + portal_db._q(KB_TABLE) +\n                \" ADD COLUMN IF NOT EXISTS brand_id BIGINT\"\n            )\n            cur.execute(\n                \"CREATE INDEX IF NOT EXISTS portal_kb_brand_idx ON \"\n                + portal_db._q(KB_TABLE) + \" (client_id, brand_id)\"\n            )\n        conn.commit()\n        _BRAND_DDL_READY = True\n    except Exception:\n        try:\n            conn.rollback()\n        except Exception:\n            pass\n\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}), 401)\n    return principal, None\n\n\ndef _normalize_text(value) -> str:\n    cleaned = re.sub(r\"[^\\w\\s]\", \" \", str(value or \"\").lower())\n    return re.sub(r\"\\s+\", \" \", cleaned).strip()\n\n\ndef _entry_json(row: Dict[str, Any]) -> Dict[str, Any]:\n    return {\n        \"id\": int(row.get(\"id\") or 0),\n        \"title\": str(row.get(\"title\") or \"\"),\n        \"category\": str(row.get(\"category\") or \"general\"),\n        \"keywords\": str(row.get(\"keywords\") or \"\"),\n        \"content\": str(row.get(\"content\") or \"\"),\n        \"is_active\": row.get(\"is_active\") is True,\n        \"usage_count\": int(row.get(\"usage_count\") or 0),\n        \"lang\": str(row.get(\"lang\") or \"auto\"),\n        \"brand_id\": int(row[\"brand_id\"]) if row.get(\"brand_id\") else None,\n    }\n\n\ndef _clean_entry_payload(raw):\n    \"\"\"Validate a knowledge-base entry payload. Returns (fields, error).\"\"\"\n    if not isinstance(raw, dict):\n        return None, (jsonify({\"error\": {\"code\": \"bad_request\",\n                                         \"message\": \"entry object is required.\"}}), 400)\n    title = str(raw.get(\"title\") or \"\").strip()\n    content = str(raw.get(\"content\") or \"\").strip()\n    keywords = str(raw.get(\"keywords\") or \"\").strip()\n    category = str(raw.get(\"category\") or \"\").strip() or \"general\"\n    is_active_raw = raw.get(\"is_active\")\n    if is_active_raw is None:\n        is_active = True\n    else:\n        is_active = is_active_raw is True or str(is_active_raw).lower() == \"true\"\n    if not title or len(title) > 200:\n        return None, (jsonify({\"error\": {\"code\": \"bad_request\",\n                                         \"message\": \"Title is required (max 200 characters).\"}}), 400)\n    if not content or len(content) > 4000:\n        return None, (jsonify({\"error\": {\"code\": \"bad_request\",\n                                         \"message\": \"Answer is required (max 4000 characters).\"}}), 400)\n    if len(keywords) > 600:\n        return None, (jsonify({\"error\": {\"code\": \"bad_request\",\n                                         \"message\": \"Keywords must be 600 characters or fewer.\"}}), 400)\n    if len(category) > 60:\n        return None, (jsonify({\"error\": {\"code\": \"bad_request\",\n                                         \"message\": \"Category must be 60 characters or fewer.\"}}), 400)\n    lang = str(raw.get(\"lang\") or \"auto\").strip().lower() or \"auto\"\n    if lang not in (\"auto\", \"en\", \"ur\", \"roman\"):\n        return None, (jsonify({\"error\": {\"code\": \"bad_request\",\n                                         \"message\": \"lang must be auto, en,\"\n                                                    \" ur, or roman.\"}}), 400)\n    return {\n        \"title\": title,\n        \"content\": content,\n        \"keywords\": keywords,\n        \"category\": category,\n        \"is_active\": is_active,\n        \"lang\": lang,\n        \"brand_id\": raw.get(\"brand_id\"),\n    }, None\n\n\ndef match_knowledge_base_lang(cur, client_id, message_text, lang=None):\n    \"\"\"Language-aware twin of match_knowledge_base.\n\n    Same keyword scoring; when scores tie, an entry written in the\n    customer's stored language wins over 'auto', which wins over any other\n    language. Falls back to the classic SELECT when the lang column is not\n    installed yet, so the ingest hot path can never break.\n    \"\"\"\n    normalized = _normalize_text(message_text)\n    if not normalized:\n        return None\n    tokens = set(normalized.split(\" \"))\n    want = str(lang or \"\").strip().lower()\n    try:\n        cur.execute(\n            \"SELECT id, title, content, keywords, lang FROM \"\n            + portal_db._q(KB_TABLE) +\n            \" WHERE client_id = %s AND is_active IS TRUE LIMIT %s\",\n            (client_id, MAX_LIST_ENTRIES),\n        )\n        rows = portal_db.rows(cur)\n    except Exception:\n        cur.execute(\n            \"SELECT id, title, content, keywords FROM \"\n            + portal_db._q(KB_TABLE) +\n            \" WHERE client_id = %s AND is_active IS TRUE LIMIT %s\",\n            (client_id, MAX_LIST_ENTRIES),\n        )\n        rows = portal_db.rows(cur)\n    best = None\n    best_key = None\n    for row in rows:\n        score = 0\n        for chunk in str(row.get(\"keywords\") or \"\").split(\",\"):\n            keyword = _normalize_text(chunk)\n            if not keyword:\n                continue\n            if \" \" in keyword:\n                if keyword in normalized:\n                    score += 3\n            elif keyword in tokens:\n                score += 3\n        if score <= 0:\n            continue\n        row_lang = str(row.get(\"lang\") or \"auto\").strip().lower() or \"auto\"\n        if want and row_lang == want:\n            tier = 0\n        elif row_lang == \"auto\":\n            tier = 1\n        else:\n            tier = 2\n        key = (score, -tier)\n        if best_key is None or key > best_key:\n            best_key = key\n            best = row\n    if best is None or best_key[0] < MIN_KEYWORD_SCORE:\n        return None\n    return best\n\n\ndef match_knowledge_base(cur, client_id, message_text):\n    \"\"\"Return the best-scoring active entry whose keywords hit the message.\n\n    Single tokens score 3 when the normalized message contains the token;\n    multi-word keywords score 3 when the phrase appears in the normalized\n    text. Requires MIN_KEYWORD_SCORE (at least one keyword hit).\n    \"\"\"\n    normalized = _normalize_text(message_text)\n    if not normalized:\n        return None\n    tokens = set(normalized.split(\" \"))\n    cur.execute(\n        \"SELECT id, title, content, keywords FROM \" + portal_db._q(KB_TABLE) +\n        \" WHERE client_id = %s AND is_active IS TRUE LIMIT %s\",\n        (client_id, MAX_LIST_ENTRIES),\n    )\n    best = None\n    best_score = 0\n    for row in portal_db.rows(cur):\n        score = 0\n        for chunk in str(row.get(\"keywords\") or \"\").split(\",\"):\n            keyword = _normalize_text(chunk)\n            if not keyword:\n                continue\n            if \" \" in keyword:\n                if keyword in normalized:\n                    score += 3\n            elif keyword in tokens:\n                score += 3\n        if score > best_score:\n            best_score = score\n            best = row\n    if best is None or best_score < MIN_KEYWORD_SCORE:\n        return None\n    return best\n\n\ndef maybe_auto_reply(client_id, conversation_id, contact_id, contact_name,\n                     message_text, intent, conn):\n    \"\"\"Queue an instant knowledge-base answer inside the ingest transaction.\n\n    Fires only for KB_AUTO_INTENTS when auto-reply is enabled, no outbound\n    message was sent to this conversation in the last\n    AUTO_REPLY_COOLDOWN_SECONDS, and an active entry keyword-matches the\n    message. Never raises into the caller: wrap in try/except there.\n    \"\"\"\n    if intent not in KB_AUTO_INTENTS:\n        return\n    external_user_id = str(contact_id or \"\").strip()\n    if not external_user_id:\n        return\n    with conn.cursor() as cur:\n        cur.execute(\n            \"SELECT auto_reply FROM \" + portal_db._q(KB_SETTINGS_TABLE) +\n            \" WHERE client_id = %s LIMIT 1\",\n            (client_id,),\n        )\n        settings_rows = portal_db.rows(cur)\n        if not settings_rows or settings_rows[0].get(\"auto_reply\") is not True:\n            return\n        cur.execute(\n            \"SELECT 1 FROM \" + portal_db._q(portal_db.MSGS_TABLE) +\n            \" WHERE conversation_id = %s AND direction = 'out'\"\n            \" AND created_at > NOW() - make_interval(secs => %s)\"\n            \" LIMIT 1\",\n            (conversation_id, AUTO_REPLY_COOLDOWN_SECONDS),\n        )\n        if portal_db.rows(cur):\n            return  # we just answered this conversation \u2014 stay quiet\n        contact_lang = None\n        try:\n            import portal_contacts\n\n            contact_lang = portal_contacts.stored_language(\n                cur, client_id, external_user_id)\n        except Exception:\n            contact_lang = None\n        entry = match_knowledge_base_lang(\n            cur, client_id, message_text, contact_lang)\n        if entry is None:\n            return\n        display_name = str(contact_name or \"\").strip()\n        first_name = display_name.split(\" \")[0] if display_name else \"there\"\n        rendered = str(entry.get(\"content\") or \"\").replace(\n            \"{name}\", first_name\n        ).strip()\n        if not rendered:\n            return\n        payload = {\n            \"external_user_id\": external_user_id,\n            \"body\": rendered[:1000],\n            \"conversation_id\": conversation_id,\n            \"source\": \"knowledge_base\",\n        }\n        if display_name:\n            payload[\"target_display_name\"] = display_name\n        import portal_channels\n\n        channel = portal_channels.channel_for_contact(external_user_id)\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(portal_db.CMD_TABLE) +\n            \" (client_id, channel, action, payload, status, requested_by,\"\n            \" created_at, updated_at) \"\n            \"VALUES (%s, %s, 'send_message', CAST(%s AS JSONB),\"\n            \" 'pending', NULL, NOW(), NOW()) \"\n            \"RETURNING id\",\n            (client_id, channel, json.dumps(payload)),\n        )\n        cur.execute(\n            \"UPDATE \" + portal_db._q(KB_TABLE) +\n            \" SET usage_count = usage_count + 1 WHERE id = %s\",\n            (entry.get(\"id\"),),\n        )\n        return True\n    logger.info(\n        \"knowledge base auto-reply queued entry=%s conversation=%s client=%s\",\n        entry.get(\"id\"),\n        conversation_id,\n        client_id,\n    )\n\n\n@bp.get(\"/portal/kb\")\ndef get_knowledge_base():\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_lang_column(conn)\n            _ensure_brand_column(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(KB_SETTINGS_TABLE) +\n                    \" (client_id) VALUES (%s)\"\n                    \" ON CONFLICT (client_id) DO NOTHING\",\n                    (principal[\"client_id\"],),\n                )\n                cur.execute(\n                    \"SELECT auto_reply FROM \" + portal_db._q(KB_SETTINGS_TABLE) +\n                    \" WHERE client_id = %s LIMIT 1\",\n                    (principal[\"client_id\"],),\n                )\n                settings_rows = portal_db.rows(cur)\n                brand_filter = request.args.get(\"brand_id\")\n                brand_where = \"\"\n                list_args = [principal[\"client_id\"]]\n                if brand_filter not in (None, \"\", \"all\"):\n                    brand_where = \" AND brand_id = %s\"\n                    list_args.append(int(brand_filter))\n                list_args.append(MAX_LIST_ENTRIES)\n                cur.execute(\n                    \"SELECT id, title, category, keywords, content,\"\n                    \" is_active, usage_count, lang, brand_id FROM \"\n                    + portal_db._q(KB_TABLE) +\n                    \" WHERE client_id = %s\" + brand_where +\n                    \" ORDER BY updated_at DESC, id DESC LIMIT %s\",\n                    tuple(list_args),\n                )\n                entry_rows = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"portal knowledge base\")[0]), 503\n    settings_row = settings_rows[0] if settings_rows else {}\n    return jsonify({\n        \"settings\": {\"auto_reply\": settings_row.get(\"auto_reply\") is True},\n        \"entries\": [_entry_json(row) for row in entry_rows],\n    }), 200\n\n\n@bp.post(\"/portal/kb\")\ndef create_kb_entry():\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    payload = request.get_json(silent=True) or {}\n    fields, entry_error = _clean_entry_payload(payload.get(\"entry\"))\n    if entry_error is not None:\n        return entry_error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_brand_column(conn)\n            with conn.cursor() as cur:\n                blocked = portal_plans.enforce(cur, principal[\"client_id\"],\n                                               \"kb_entries\",\n                                               \"Knowledge-base entry\")\n                if blocked is not None:\n                    return blocked\n                brand_id = portal_brands.resolve_brand(\n                    cur, principal[\"client_id\"],\n                    (payload.get(\"entry\") or {}).get(\"brand_id\"))\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(KB_TABLE) +\n                    \" (client_id, title, category, keywords, content,\"\n                    \" is_active, lang, brand_id)\"\n                    \" VALUES (%s, %s, %s, %s, %s, %s, %s, %s)\"\n                    \" RETURNING id, title, category, keywords, content,\"\n                    \" is_active, usage_count, lang, brand_id\",\n                    (principal[\"client_id\"], fields[\"title\"], fields[\"category\"],\n                     fields[\"keywords\"], fields[\"content\"], fields[\"is_active\"],\n                     fields[\"lang\"], brand_id),\n                )\n                created = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"portal knowledge base create\")[0]), 503\n    return jsonify({\n        \"ok\": True,\n        \"entry\": _entry_json(created[0] if created else {}),\n    }), 200\n\n\n@bp.put(\"/portal/kb\")\ndef save_kb_settings():\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    payload = request.get_json(silent=True) or {}\n    raw = payload.get(\"settings\")\n    auto_reply = raw.get(\"auto_reply\") if isinstance(raw, dict) else None\n    if not isinstance(auto_reply, bool):\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"auto_reply must be true or false.\"}}), 400\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(KB_SETTINGS_TABLE) +\n                    \" (client_id, auto_reply, updated_at)\"\n                    \" VALUES (%s, %s, NOW())\"\n                    \" ON CONFLICT (client_id) DO UPDATE SET\"\n                    \" auto_reply = EXCLUDED.auto_reply, updated_at = NOW()\",\n                    (principal[\"client_id\"], auto_reply),\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"portal knowledge base settings\")[0]), 503\n    return jsonify({\"ok\": True, \"settings\": {\"auto_reply\": auto_reply}}), 200\n\n\n@bp.put(\"/portal/kb/<int:entry_id>\")\ndef update_kb_entry(entry_id):\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    payload = request.get_json(silent=True) or {}\n    fields, entry_error = _clean_entry_payload(payload.get(\"entry\"))\n    if entry_error is not None:\n        return entry_error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                brand_id = portal_brands.resolve_brand(\n                    cur, principal[\"client_id\"], fields.get(\"brand_id\"))\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(KB_TABLE) +\n                    \" SET title = %s, category = %s, keywords = %s,\"\n                    \" content = %s, lang = %s, is_active = %s,\"\n                    \" brand_id = %s, updated_at = NOW()\"\n                    \" WHERE id = %s AND client_id = %s\"\n                    \" RETURNING id, title, category, keywords, content,\"\n                    \" is_active, usage_count, lang, brand_id\",\n                    (fields[\"title\"], fields[\"category\"],\n                     fields[\"keywords\"], fields[\"content\"],\n                     fields[\"lang\"], fields[\"is_active\"], brand_id,\n                     entry_id, principal[\"client_id\"]),\n                )\n            updated = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"portal knowledge base update\")[0]), 503\n    if not updated:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Knowledge base entry not found.\"}}), 404\n    return jsonify({\"ok\": True, \"entry\": _entry_json(updated[0])}), 200\n\n\n@bp.delete(\"/portal/kb/<int:entry_id>\")\ndef delete_kb_entry(entry_id):\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"DELETE FROM \" + portal_db._q(KB_TABLE) +\n                    \" WHERE id = %s AND client_id = %s RETURNING id\",\n                    (entry_id, principal[\"client_id\"]),\n                )\n                deleted = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"portal knowledge base delete\")[0]), 503\n    if not deleted:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Knowledge base entry not found.\"}}), 404\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.after_request\ndef _kb_semantic_after(response):\n    \"\"\"D1: a successful answer create/edit/delete schedules a semantic-index\n    sync (portal_kb_semantic); never alters the response.\"\"\"\n    try:\n        import portal_kb_semantic\n\n        return portal_kb_semantic.kick_after_mutation(response)\n    except Exception:\n        return response\n\n");
writeNewRepair("OmniFlow-Control-Plane/portal_kb.py", "\"\"\"D1: a successful answer create/edit/delete schedules a semantic-index", true,
    "\"\"\"Portal knowledge base (customer Bearer + ingest-time auto-reply).\n\nBusinesses store answers (title, category, keywords, content) as knowledge\nbase entries. When an inbound WhatsApp message classifies as a general\ninformational intent (general, shipping, order_tracking, appointment) and a\nkeyword matches an active entry, the Control Plane queues a regular\nsend_message command; the laptop connector delivers it through the existing\ncommand polling. Complaints, refund requests and human-handoff messages are\nnever auto-answered. Matching is deterministic keyword scoring: zero AI cost.\n\"\"\"\n\nimport json\nimport logging\nimport re\nfrom typing import Any, Dict\n\nfrom flask import Blueprint, jsonify, request\n\nfrom portal_auth import PortalAuthUnavailable, authenticate_portal_request\nimport portal_db\nimport portal_plans\nimport portal_brands\n\n\nlogger = logging.getLogger(\"omniflow.portal-knowledge-base\")\n\nbp = Blueprint(\"portal_kb\", __name__, url_prefix=\"/api/v1\")\n\nKB_SETTINGS_TABLE = \"portal_kb_settings\"\nKB_TABLE = \"portal_kb_entries\"\n\n# Intents eligible for instant knowledge-base answers. Sensitive intents\n# (human_request, complaint, refund_return) and the sales intents owned by\n# the follow-up agent are deliberately excluded.\nKB_AUTO_INTENTS = (\"general\", \"shipping\", \"order_tracking\", \"appointment\")\n\n_INTENT_HINTS = (\n    (\"order_tracking\", (\"track\", \"tracking\", \"kahan\", \"status of my order\",\n                        \"order status\", \"mera order\")),\n    (\"shipping\", (\"delivery\", \"shipping\", \"charge\", \"kitne din\", \"courier\",\n                  \"pahunch\")),\n    (\"appointment\", (\"appointment\", \"booking\", \"book\", \"appointment time\")),\n)\n\n\ndef classify_intent(message_text) -> str:\n    \"\"\"Coarse intent for the KB auto-reply gate (keyword hints first).\n\n    B3: portal_intents.classify wraps this table as its offline fallback \u2014\n    callers get the LLM label when configured, keywords otherwise.\n    \"\"\"\n    text = _normalize_text(message_text)\n    if not text:\n        return \"general\"\n    for intent, hints in _INTENT_HINTS:\n        for hint in hints:\n            if hint in text:\n                return intent\n    return \"general\"\n\nMIN_KEYWORD_SCORE = 3  # one keyword hit = 3 points\nAUTO_REPLY_COOLDOWN_SECONDS = 120\nMAX_LIST_ENTRIES = 200\n\n\n_LANG_DDL_READY = False\n\n\ndef _ensure_lang_column(conn) -> None:\n    \"\"\"portal_kb_entries.lang lands lazily (older installs keep working).\"\"\"\n    global _LANG_DDL_READY\n    if _LANG_DDL_READY:\n        return\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"ALTER TABLE \" + portal_db._q(KB_TABLE) +\n                \" ADD COLUMN IF NOT EXISTS lang TEXT NOT NULL DEFAULT 'auto'\"\n            )\n        conn.commit()\n        _LANG_DDL_READY = True\n    except Exception:\n        try:\n            conn.rollback()\n        except Exception:\n            pass\n\n\ndef _ensure_brand_column(conn) -> None:\n    \"\"\"portal_kb_entries.brand_id lands lazily (multi-brand prep).\"\"\"\n    global _BRAND_DDL_READY\n    if _BRAND_DDL_READY:\n        return\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"ALTER TABLE \" + portal_db._q(KB_TABLE) +\n                \" ADD COLUMN IF NOT EXISTS brand_id BIGINT\"\n            )\n            cur.execute(\n                \"CREATE INDEX IF NOT EXISTS portal_kb_brand_idx ON \"\n                + portal_db._q(KB_TABLE) + \" (client_id, brand_id)\"\n            )\n        conn.commit()\n        _BRAND_DDL_READY = True\n    except Exception:\n        try:\n            conn.rollback()\n        except Exception:\n            pass\n\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}), 401)\n    return principal, None\n\n\ndef _normalize_text(value) -> str:\n    cleaned = re.sub(r\"[^\\w\\s]\", \" \", str(value or \"\").lower())\n    return re.sub(r\"\\s+\", \" \", cleaned).strip()\n\n\ndef _entry_json(row: Dict[str, Any]) -> Dict[str, Any]:\n    return {\n        \"id\": int(row.get(\"id\") or 0),\n        \"title\": str(row.get(\"title\") or \"\"),\n        \"category\": str(row.get(\"category\") or \"general\"),\n        \"keywords\": str(row.get(\"keywords\") or \"\"),\n        \"content\": str(row.get(\"content\") or \"\"),\n        \"is_active\": row.get(\"is_active\") is True,\n        \"usage_count\": int(row.get(\"usage_count\") or 0),\n        \"lang\": str(row.get(\"lang\") or \"auto\"),\n        \"brand_id\": int(row[\"brand_id\"]) if row.get(\"brand_id\") else None,\n    }\n\n\ndef _clean_entry_payload(raw):\n    \"\"\"Validate a knowledge-base entry payload. Returns (fields, error).\"\"\"\n    if not isinstance(raw, dict):\n        return None, (jsonify({\"error\": {\"code\": \"bad_request\",\n                                         \"message\": \"entry object is required.\"}}), 400)\n    title = str(raw.get(\"title\") or \"\").strip()\n    content = str(raw.get(\"content\") or \"\").strip()\n    keywords = str(raw.get(\"keywords\") or \"\").strip()\n    category = str(raw.get(\"category\") or \"\").strip() or \"general\"\n    is_active_raw = raw.get(\"is_active\")\n    if is_active_raw is None:\n        is_active = True\n    else:\n        is_active = is_active_raw is True or str(is_active_raw).lower() == \"true\"\n    if not title or len(title) > 200:\n        return None, (jsonify({\"error\": {\"code\": \"bad_request\",\n                                         \"message\": \"Title is required (max 200 characters).\"}}), 400)\n    if not content or len(content) > 4000:\n        return None, (jsonify({\"error\": {\"code\": \"bad_request\",\n                                         \"message\": \"Answer is required (max 4000 characters).\"}}), 400)\n    if len(keywords) > 600:\n        return None, (jsonify({\"error\": {\"code\": \"bad_request\",\n                                         \"message\": \"Keywords must be 600 characters or fewer.\"}}), 400)\n    if len(category) > 60:\n        return None, (jsonify({\"error\": {\"code\": \"bad_request\",\n                                         \"message\": \"Category must be 60 characters or fewer.\"}}), 400)\n    lang = str(raw.get(\"lang\") or \"auto\").strip().lower() or \"auto\"\n    if lang not in (\"auto\", \"en\", \"ur\", \"roman\"):\n        return None, (jsonify({\"error\": {\"code\": \"bad_request\",\n                                         \"message\": \"lang must be auto, en,\"\n                                                    \" ur, or roman.\"}}), 400)\n    return {\n        \"title\": title,\n        \"content\": content,\n        \"keywords\": keywords,\n        \"category\": category,\n        \"is_active\": is_active,\n        \"lang\": lang,\n        \"brand_id\": raw.get(\"brand_id\"),\n    }, None\n\n\ndef match_knowledge_base_lang(cur, client_id, message_text, lang=None):\n    \"\"\"Language-aware twin of match_knowledge_base.\n\n    Same keyword scoring; when scores tie, an entry written in the\n    customer's stored language wins over 'auto', which wins over any other\n    language. Falls back to the classic SELECT when the lang column is not\n    installed yet, so the ingest hot path can never break.\n    \"\"\"\n    normalized = _normalize_text(message_text)\n    if not normalized:\n        return None\n    tokens = set(normalized.split(\" \"))\n    want = str(lang or \"\").strip().lower()\n    try:\n        cur.execute(\n            \"SELECT id, title, content, keywords, lang FROM \"\n            + portal_db._q(KB_TABLE) +\n            \" WHERE client_id = %s AND is_active IS TRUE LIMIT %s\",\n            (client_id, MAX_LIST_ENTRIES),\n        )\n        rows = portal_db.rows(cur)\n    except Exception:\n        cur.execute(\n            \"SELECT id, title, content, keywords FROM \"\n            + portal_db._q(KB_TABLE) +\n            \" WHERE client_id = %s AND is_active IS TRUE LIMIT %s\",\n            (client_id, MAX_LIST_ENTRIES),\n        )\n        rows = portal_db.rows(cur)\n    best = None\n    best_key = None\n    for row in rows:\n        score = 0\n        for chunk in str(row.get(\"keywords\") or \"\").split(\",\"):\n            keyword = _normalize_text(chunk)\n            if not keyword:\n                continue\n            if \" \" in keyword:\n                if keyword in normalized:\n                    score += 3\n            elif keyword in tokens:\n                score += 3\n        if score <= 0:\n            continue\n        row_lang = str(row.get(\"lang\") or \"auto\").strip().lower() or \"auto\"\n        if want and row_lang == want:\n            tier = 0\n        elif row_lang == \"auto\":\n            tier = 1\n        else:\n            tier = 2\n        key = (score, -tier)\n        if best_key is None or key > best_key:\n            best_key = key\n            best = row\n    if best is None or best_key[0] < MIN_KEYWORD_SCORE:\n        return None\n    return best\n\n\ndef match_knowledge_base(cur, client_id, message_text):\n    \"\"\"Return the best-scoring active entry whose keywords hit the message.\n\n    Single tokens score 3 when the normalized message contains the token;\n    multi-word keywords score 3 when the phrase appears in the normalized\n    text. Requires MIN_KEYWORD_SCORE (at least one keyword hit).\n    \"\"\"\n    normalized = _normalize_text(message_text)\n    if not normalized:\n        return None\n    tokens = set(normalized.split(\" \"))\n    cur.execute(\n        \"SELECT id, title, content, keywords FROM \" + portal_db._q(KB_TABLE) +\n        \" WHERE client_id = %s AND is_active IS TRUE LIMIT %s\",\n        (client_id, MAX_LIST_ENTRIES),\n    )\n    best = None\n    best_score = 0\n    for row in portal_db.rows(cur):\n        score = 0\n        for chunk in str(row.get(\"keywords\") or \"\").split(\",\"):\n            keyword = _normalize_text(chunk)\n            if not keyword:\n                continue\n            if \" \" in keyword:\n                if keyword in normalized:\n                    score += 3\n            elif keyword in tokens:\n                score += 3\n        if score > best_score:\n            best_score = score\n            best = row\n    if best is None or best_score < MIN_KEYWORD_SCORE:\n        return None\n    return best\n\n\ndef maybe_auto_reply(client_id, conversation_id, contact_id, contact_name,\n                     message_text, intent, conn):\n    \"\"\"Queue an instant knowledge-base answer inside the ingest transaction.\n\n    Fires only for KB_AUTO_INTENTS when auto-reply is enabled, no outbound\n    message was sent to this conversation in the last\n    AUTO_REPLY_COOLDOWN_SECONDS, and an active entry keyword-matches the\n    message. Never raises into the caller: wrap in try/except there.\n    \"\"\"\n    if intent not in KB_AUTO_INTENTS:\n        return\n    external_user_id = str(contact_id or \"\").strip()\n    if not external_user_id:\n        return\n    with conn.cursor() as cur:\n        cur.execute(\n            \"SELECT auto_reply FROM \" + portal_db._q(KB_SETTINGS_TABLE) +\n            \" WHERE client_id = %s LIMIT 1\",\n            (client_id,),\n        )\n        settings_rows = portal_db.rows(cur)\n        if not settings_rows or settings_rows[0].get(\"auto_reply\") is not True:\n            return\n        cur.execute(\n            \"SELECT 1 FROM \" + portal_db._q(portal_db.MSGS_TABLE) +\n            \" WHERE conversation_id = %s AND direction = 'out'\"\n            \" AND created_at > NOW() - make_interval(secs => %s)\"\n            \" LIMIT 1\",\n            (conversation_id, AUTO_REPLY_COOLDOWN_SECONDS),\n        )\n        if portal_db.rows(cur):\n            return  # we just answered this conversation \u2014 stay quiet\n        contact_lang = None\n        try:\n            import portal_contacts\n\n            contact_lang = portal_contacts.stored_language(\n                cur, client_id, external_user_id)\n        except Exception:\n            contact_lang = None\n        entry = match_knowledge_base_lang(\n            cur, client_id, message_text, contact_lang)\n        if entry is None:\n            return\n        display_name = str(contact_name or \"\").strip()\n        first_name = display_name.split(\" \")[0] if display_name else \"there\"\n        rendered = str(entry.get(\"content\") or \"\").replace(\n            \"{name}\", first_name\n        ).strip()\n        if not rendered:\n            return\n        payload = {\n            \"external_user_id\": external_user_id,\n            \"body\": rendered[:1000],\n            \"conversation_id\": conversation_id,\n            \"source\": \"knowledge_base\",\n        }\n        if display_name:\n            payload[\"target_display_name\"] = display_name\n        import portal_channels\n\n        channel = portal_channels.channel_for_contact(external_user_id)\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(portal_db.CMD_TABLE) +\n            \" (client_id, channel, action, payload, status, requested_by,\"\n            \" created_at, updated_at) \"\n            \"VALUES (%s, %s, 'send_message', CAST(%s AS JSONB),\"\n            \" 'pending', NULL, NOW(), NOW()) \"\n            \"RETURNING id\",\n            (client_id, channel, json.dumps(payload)),\n        )\n        cur.execute(\n            \"UPDATE \" + portal_db._q(KB_TABLE) +\n            \" SET usage_count = usage_count + 1 WHERE id = %s\",\n            (entry.get(\"id\"),),\n        )\n        return True\n    logger.info(\n        \"knowledge base auto-reply queued entry=%s conversation=%s client=%s\",\n        entry.get(\"id\"),\n        conversation_id,\n        client_id,\n    )\n\n\n@bp.get(\"/portal/kb\")\ndef get_knowledge_base():\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_lang_column(conn)\n            _ensure_brand_column(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(KB_SETTINGS_TABLE) +\n                    \" (client_id) VALUES (%s)\"\n                    \" ON CONFLICT (client_id) DO NOTHING\",\n                    (principal[\"client_id\"],),\n                )\n                cur.execute(\n                    \"SELECT auto_reply FROM \" + portal_db._q(KB_SETTINGS_TABLE) +\n                    \" WHERE client_id = %s LIMIT 1\",\n                    (principal[\"client_id\"],),\n                )\n                settings_rows = portal_db.rows(cur)\n                brand_filter = request.args.get(\"brand_id\")\n                brand_where = \"\"\n                list_args = [principal[\"client_id\"]]\n                if brand_filter not in (None, \"\", \"all\"):\n                    brand_where = \" AND brand_id = %s\"\n                    list_args.append(int(brand_filter))\n                list_args.append(MAX_LIST_ENTRIES)\n                cur.execute(\n                    \"SELECT id, title, category, keywords, content,\"\n                    \" is_active, usage_count, lang, brand_id FROM \"\n                    + portal_db._q(KB_TABLE) +\n                    \" WHERE client_id = %s\" + brand_where +\n                    \" ORDER BY updated_at DESC, id DESC LIMIT %s\",\n                    tuple(list_args),\n                )\n                entry_rows = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"portal knowledge base\")[0]), 503\n    settings_row = settings_rows[0] if settings_rows else {}\n    return jsonify({\n        \"settings\": {\"auto_reply\": settings_row.get(\"auto_reply\") is True},\n        \"entries\": [_entry_json(row) for row in entry_rows],\n    }), 200\n\n\n@bp.post(\"/portal/kb\")\ndef create_kb_entry():\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    payload = request.get_json(silent=True) or {}\n    fields, entry_error = _clean_entry_payload(payload.get(\"entry\"))\n    if entry_error is not None:\n        return entry_error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_brand_column(conn)\n            with conn.cursor() as cur:\n                blocked = portal_plans.enforce(cur, principal[\"client_id\"],\n                                               \"kb_entries\",\n                                               \"Knowledge-base entry\")\n                if blocked is not None:\n                    return blocked\n                brand_id = portal_brands.resolve_brand(\n                    cur, principal[\"client_id\"],\n                    (payload.get(\"entry\") or {}).get(\"brand_id\"))\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(KB_TABLE) +\n                    \" (client_id, title, category, keywords, content,\"\n                    \" is_active, lang, brand_id)\"\n                    \" VALUES (%s, %s, %s, %s, %s, %s, %s, %s)\"\n                    \" RETURNING id, title, category, keywords, content,\"\n                    \" is_active, usage_count, lang, brand_id\",\n                    (principal[\"client_id\"], fields[\"title\"], fields[\"category\"],\n                     fields[\"keywords\"], fields[\"content\"], fields[\"is_active\"],\n                     fields[\"lang\"], brand_id),\n                )\n                created = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"portal knowledge base create\")[0]), 503\n    return jsonify({\n        \"ok\": True,\n        \"entry\": _entry_json(created[0] if created else {}),\n    }), 200\n\n\n@bp.put(\"/portal/kb\")\ndef save_kb_settings():\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    payload = request.get_json(silent=True) or {}\n    raw = payload.get(\"settings\")\n    auto_reply = raw.get(\"auto_reply\") if isinstance(raw, dict) else None\n    if not isinstance(auto_reply, bool):\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"auto_reply must be true or false.\"}}), 400\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(KB_SETTINGS_TABLE) +\n                    \" (client_id, auto_reply, updated_at)\"\n                    \" VALUES (%s, %s, NOW())\"\n                    \" ON CONFLICT (client_id) DO UPDATE SET\"\n                    \" auto_reply = EXCLUDED.auto_reply, updated_at = NOW()\",\n                    (principal[\"client_id\"], auto_reply),\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"portal knowledge base settings\")[0]), 503\n    return jsonify({\"ok\": True, \"settings\": {\"auto_reply\": auto_reply}}), 200\n\n\n@bp.put(\"/portal/kb/<int:entry_id>\")\ndef update_kb_entry(entry_id):\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    payload = request.get_json(silent=True) or {}\n    fields, entry_error = _clean_entry_payload(payload.get(\"entry\"))\n    if entry_error is not None:\n        return entry_error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                brand_id = portal_brands.resolve_brand(\n                    cur, principal[\"client_id\"], fields.get(\"brand_id\"))\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(KB_TABLE) +\n                    \" SET title = %s, category = %s, keywords = %s,\"\n                    \" content = %s, lang = %s, is_active = %s,\"\n                    \" brand_id = %s, updated_at = NOW()\"\n                    \" WHERE id = %s AND client_id = %s\"\n                    \" RETURNING id, title, category, keywords, content,\"\n                    \" is_active, usage_count, lang, brand_id\",\n                    (fields[\"title\"], fields[\"category\"],\n                     fields[\"keywords\"], fields[\"content\"],\n                     fields[\"lang\"], fields[\"is_active\"], brand_id,\n                     entry_id, principal[\"client_id\"]),\n                )\n            updated = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"portal knowledge base update\")[0]), 503\n    if not updated:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Knowledge base entry not found.\"}}), 404\n    return jsonify({\"ok\": True, \"entry\": _entry_json(updated[0])}), 200\n\n\n@bp.delete(\"/portal/kb/<int:entry_id>\")\ndef delete_kb_entry(entry_id):\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"DELETE FROM \" + portal_db._q(KB_TABLE) +\n                    \" WHERE id = %s AND client_id = %s RETURNING id\",\n                    (entry_id, principal[\"client_id\"]),\n                )\n                deleted = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"portal knowledge base delete\")[0]), 503\n    if not deleted:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Knowledge base entry not found.\"}}), 404\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.after_request\ndef _kb_semantic_after(response):\n    \"\"\"D1: a successful answer create/edit/delete schedules a semantic-index\n    sync (portal_kb_semantic); never alters the response.\"\"\"\n    try:\n        import portal_kb_semantic\n\n        return portal_kb_semantic.kick_after_mutation(response)\n    except Exception:\n        return response\n\n");
writeNewRepair("omniflow-backend-patch/portal_kb_semantic.py", "def _save_state(cur, client_id: int, error: str, embedded: int, reused: int,", false,
    "\"\"\"Knowledge semantic index (owner decision D1 - delivered in \u00a7211).\n\nAudit-first: this is NOT a second knowledge engine. ``portal_knowledge``\nstays the one ingestion/versioning/retrieval owner and\n``portal_knowledge.retrieve`` stays the one read the brain and the owner's\ntester call. This module only adds meaning-based recall to that read:\n\n* ``portal_kb_embeddings`` - one vector per retrievable item: chunks of\n  PUBLISHED sources and ACTIVE Q&A entries. Vectors are L2-normalised\n  REAL[] columns in the existing Postgres (no pgvector, no new service),\n  keyed by (client_id, kind, ref_id) and a content hash, so re-indexing a\n  source with unchanged text or rolling back a version reuses the stored\n  vector instead of paying for it again.\n* ``sync`` - embeds whatever is missing or changed (budgeted, batched),\n  reuses vectors by content hash and drops vectors whose item was deleted,\n  unpublished or deactivated. Runs on a daemon thread after owner edits,\n  from the connector tick (throttled) and from the \"Build index\" button.\n* ``hybrid`` - called from ``portal_knowledge.retrieve``: embeds the\n  question once (small LRU cache), scores it against the tenant's vectors\n  (in-process cache, TTL) and fuses the result with the existing keyword\n  ranking by reciprocal rank fusion. Hits keep the exact retrieval\n  contract plus ``via`` (keyword|semantic|both) and ``semantic``.\n\nLaws kept:\n* KB auto-publish LOCK - semantic hits are re-read through the same\n  \"published source / active entry\" filters as keyword hits, so a paused\n  or draft source never reaches the AI even if its vector still exists.\n* Fail-soft - any provider/config/DB problem returns ``None`` and the\n  caller falls back to pure keyword retrieval. A failing provider trips a\n  short cooldown so the reply path never waits on a dead endpoint twice.\n* Costs go through ``portal_llm`` (platform AI gate + usage ledger) under\n  the ``kb_embed`` feature, attributed to the persona of the calling scope.\n* Customer text is only embedded (never executed or used as a prompt).\n\"\"\"\n\nimport hashlib\nimport logging\nimport os\nimport threading\nimport time\nfrom collections import OrderedDict\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n    ensure_human_principal,\n)\n\nlogger = logging.getLogger(\"omniflow.portal-kb-semantic\")\n\nbp = Blueprint(\"portal_kb_semantic\", __name__, url_prefix=\"/api/v1/portal\")\n\nEMB_TABLE = \"portal_kb_embeddings\"\nSTATE_TABLE = \"portal_kb_semantic_state\"\nCHUNKS_TABLE = \"portal_kb_chunks\"\nSOURCES_TABLE = \"portal_kb_sources\"\nENTRIES_TABLE = \"portal_kb_entries\"\nFEATURE = \"kb_embed\"\n\n\ndef _env_int(name: str, default: int, lo: int, hi: int) -> int:\n    try:\n        value = int(os.environ.get(name, \"\") or default)\n    except Exception:\n        value = default\n    return max(lo, min(hi, value))\n\n\ndef _env_float(name: str, default: float, lo: float, hi: float) -> float:\n    try:\n        value = float(os.environ.get(name, \"\") or default)\n    except Exception:\n        value = default\n    return max(lo, min(hi, value))\n\n\nSYNC_BUDGET = _env_int(\"OF_KB_EMBED_SYNC_MAX\", 400, 1, 20000)\nSCAN_MAX = _env_int(\"OF_KB_EMBED_SCAN_MAX\", 5000, 50, 50000)\nITEMS_MAX = _env_int(\"OF_KB_EMBED_ITEMS_MAX\", 20000, 50, 200000)\nCACHE_SECONDS = _env_int(\"OF_KB_EMBED_CACHE_SECONDS\", 60, 0, 3600)\nTICK_SECONDS = _env_int(\"OF_KB_EMBED_TICK_SECONDS\", 600, 30, 86400)\nCOOLDOWN_SECONDS = _env_int(\"OF_KB_EMBED_COOLDOWN_SECONDS\", 300, 10, 86400)\nQUERY_TIMEOUT = _env_float(\"OF_KB_EMBED_QUERY_TIMEOUT\", 3.0, 0.5, 30.0)\nQUERY_CACHE_MAX = _env_int(\"OF_KB_EMBED_QUERY_CACHE\", 256, 0, 10000)\nREL_WINDOW = _env_float(\"OF_KB_EMBED_REL_WINDOW\", 0.12, 0.0, 1.0)\nRRF_K = _env_int(\"OF_KB_EMBED_RRF_K\", 60, 1, 1000)\nPOOL = _env_int(\"OF_KB_EMBED_POOL\", 12, 3, 100)\nTEXT_CHARS = _env_int(\"OF_EMBED_TEXT_CHARS\", 2000, 200, 20000)\n\n_DDL_READY = False\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_kb_embeddings (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  kind TEXT NOT NULL,\n  ref_id BIGINT NOT NULL,\n  source_id BIGINT NOT NULL DEFAULT 0,\n  content_hash TEXT NOT NULL DEFAULT '',\n  model TEXT NOT NULL DEFAULT '',\n  dims INT NOT NULL DEFAULT 0,\n  vector REAL[] NOT NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  UNIQUE (client_id, kind, ref_id)\n);\nCREATE INDEX IF NOT EXISTS idx_portal_kb_embeddings_hash\n  ON portal_kb_embeddings (client_id, model, dims, content_hash);\nCREATE TABLE IF NOT EXISTS portal_kb_semantic_state (\n  client_id BIGINT PRIMARY KEY,\n  last_sync_at TIMESTAMPTZ,\n  last_error TEXT NOT NULL DEFAULT '',\n  last_embedded INT NOT NULL DEFAULT 0,\n  last_reused INT NOT NULL DEFAULT 0,\n  model TEXT NOT NULL DEFAULT '',\n  dims INT NOT NULL DEFAULT 0,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\"\"\"\n\n\ndef _ensure_ddl(cur) -> None:\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_DDL)\n    _DDL_READY = True\n\n\n# ---------------------------------------------------------------------------\n# Config, text, hashing (pure)\n# ---------------------------------------------------------------------------\n\ndef config() -> Dict[str, Any]:\n    \"\"\"Effective embedding config; inactive on any error.\"\"\"\n    try:\n        import portal_llm\n        return portal_llm.embed_runtime()\n    except Exception:\n        return {\"active\": False, \"reason\": \"no_key\", \"model\": \"\",\n                \"dimensions\": 0, \"min_similarity\": 0.3, \"mode\": \"on\",\n                \"key_source\": \"none\", \"base_url\": \"\"}\n\n\ndef item_text(row: Dict[str, Any]) -> str:\n    \"\"\"The text a vector represents. Chunks carry their document + section\n    so a bare paragraph still knows what it is about.\"\"\"\n    kind = str(row.get(\"kind\") or \"\")\n    title = str(row.get(\"title\") or \"\").strip()\n    content = str(row.get(\"content\") or \"\").strip()\n    if kind == \"chunk\":\n        source = str(row.get(\"source_title\") or \"\").strip()\n        head = \" > \".join(p for p in (source, title) if p)\n        text = (head + \"\\n\" + content) if head else content\n    else:\n        extra = str(row.get(\"extra\") or \"\").strip()\n        text = \"\\n\".join(p for p in (title, content, extra) if p)\n    return text[:TEXT_CHARS]\n\n\ndef content_hash(text: str) -> str:\n    return hashlib.sha1(str(text or \"\").encode(\"utf-8\")).hexdigest()\n\n\ndef dot(a: List[float], b: List[float]) -> float:\n    if len(a) != len(b):\n        return -1.0\n    return sum(x * y for x, y in zip(a, b))\n\n\n# ---------------------------------------------------------------------------\n# Provider health (cooldown) + caches\n# ---------------------------------------------------------------------------\n\n_LOCK = threading.Lock()\n_DOWN_UNTIL = {\"t\": 0.0, \"error\": \"\"}\n_QUERY_CACHE: \"OrderedDict[Tuple[str, int, str], List[float]]\" = OrderedDict()\n_VEC_CACHE: Dict[int, Dict[str, Any]] = {}\n_RUNNING: set = set()\n_LAST_KICK: Dict[int, float] = {}\n\n\ndef _provider_down() -> bool:\n    return time.monotonic() < _DOWN_UNTIL[\"t\"]\n\n\ndef _trip(error: str) -> None:\n    _DOWN_UNTIL[\"t\"] = time.monotonic() + COOLDOWN_SECONDS\n    _DOWN_UNTIL[\"error\"] = str(error or \"\")[:200]\n\n\ndef _heal() -> None:\n    _DOWN_UNTIL[\"t\"] = 0.0\n    _DOWN_UNTIL[\"error\"] = \"\"\n\n\ndef invalidate(client_id: int) -> None:\n    with _LOCK:\n        _VEC_CACHE.pop(int(client_id), None)\n\n\ndef reset_caches() -> None:\n    \"\"\"Tests / admin: forget every in-process cache and cooldown.\"\"\"\n    with _LOCK:\n        _VEC_CACHE.clear()\n        _QUERY_CACHE.clear()\n        _RUNNING.clear()\n        _LAST_KICK.clear()\n    _heal()\n\n\ndef _embed(texts: List[str], cfg: Dict[str, Any], client_id: int, cur,\n           timeout: Optional[float] = None\n           ) -> Tuple[Optional[List[List[float]]], str]:\n    import portal_llm\n\n    try:\n        _feature, _cid, _cur, agent_id = portal_llm.current_scope()\n    except Exception:\n        agent_id = 0\n    with portal_llm.usage_scope(FEATURE, client_id, cur, agent_id=agent_id):\n        return portal_llm.embed_texts(texts, timeout=timeout, runtime=cfg)\n\n\ndef query_vector(cur, client_id: int, text: str,\n                 cfg: Dict[str, Any]) -> Optional[List[float]]:\n    \"\"\"One question -> one vector (cached per model/dims/text).\"\"\"\n    clean = \" \".join(str(text or \"\").split())[:TEXT_CHARS]\n    if not clean:\n        return None\n    key = (str(cfg.get(\"model\") or \"\"), int(cfg.get(\"dimensions\") or 0),\n           clean.lower())\n    with _LOCK:\n        if key in _QUERY_CACHE:\n            _QUERY_CACHE.move_to_end(key)\n            return _QUERY_CACHE[key]\n    if _provider_down():\n        return None\n    vectors, error = _embed([clean], cfg, client_id, cur, QUERY_TIMEOUT)\n    if not vectors:\n        if error and \"blocked by the platform\" not in error:\n            _trip(error)\n        return None\n    _heal()\n    vector = vectors[0]\n    if QUERY_CACHE_MAX:\n        with _LOCK:\n            _QUERY_CACHE[key] = vector\n            while len(_QUERY_CACHE) > QUERY_CACHE_MAX:\n                _QUERY_CACHE.popitem(last=False)\n    return vector\n\n\ndef load_vectors(cur, client_id: int,\n                 cfg: Dict[str, Any]) -> List[Tuple[str, int, List[float]]]:\n    \"\"\"The tenant's current vectors for the configured model/dims (cached\n    CACHE_SECONDS per process; sync invalidates its own process).\"\"\"\n    model = str(cfg.get(\"model\") or \"\")\n    dims = int(cfg.get(\"dimensions\") or 0)\n    now = time.monotonic()\n    with _LOCK:\n        cached = _VEC_CACHE.get(int(client_id))\n        if (cached and cached[\"model\"] == model and cached[\"dims\"] == dims\n                and now - cached[\"at\"] < CACHE_SECONDS):\n            return cached[\"rows\"]\n    cur.execute(\n        \"SELECT kind, ref_id, vector FROM \" + portal_db._q(EMB_TABLE) +\n        \" WHERE client_id = %s AND model = %s AND dims = %s\"\n        \" ORDER BY id LIMIT %s\",\n        (client_id, model, dims, SCAN_MAX),\n    )\n    rows: List[Tuple[str, int, List[float]]] = []\n    for row in portal_db.rows(cur):\n        vector = row.get(\"vector\")\n        if not vector:\n            continue\n        try:\n            rows.append((str(row.get(\"kind\") or \"\"), int(row.get(\"ref_id\") or 0),\n                         [float(v) for v in vector]))\n        except Exception:\n            continue\n    if CACHE_SECONDS:\n        with _LOCK:\n            _VEC_CACHE[int(client_id)] = {\"at\": now, \"model\": model,\n                                          \"dims\": dims, \"rows\": rows}\n    return rows\n\n\ndef rank_semantic(qvec: List[float],\n                  vectors: List[Tuple[str, int, List[float]]],\n                  min_sim: float, pool: int) -> List[Tuple[float, str, int]]:\n    \"\"\"Cosine (dot of unit vectors) ranking, filtered by an absolute floor\n    and a window below the best match so a weak tail never rides along.\n    Deterministic: ties break on kind then id.\"\"\"\n    scored = []\n    for kind, ref_id, vector in vectors:\n        sim = dot(qvec, vector)\n        if sim >= min_sim:\n            scored.append((round(sim, 4), kind, ref_id))\n    if not scored:\n        return []\n    scored.sort(key=lambda s: (-s[0], s[1], s[2]))\n    floor = max(min_sim, scored[0][0] - REL_WINDOW)\n    return [s for s in scored if s[0] >= floor][:max(1, pool)]\n\n\n# ---------------------------------------------------------------------------\n# Hybrid retrieval (called by portal_knowledge.retrieve)\n# ---------------------------------------------------------------------------\n\ndef _fetch_items(cur, client_id: int, keys: List[Tuple[str, int]],\n                 include_entries: bool) -> Dict[Tuple[str, int], Dict[str, Any]]:\n    \"\"\"Re-read semantic-only hits through the SAME publish/active filters\n    as the keyword path (auto-publish lock).\"\"\"\n    chunk_ids = [ref for kind, ref in keys if kind == \"chunk\"]\n    entry_ids = [ref for kind, ref in keys if kind == \"entry\"]\n    out: Dict[Tuple[str, int], Dict[str, Any]] = {}\n    if chunk_ids:\n        cur.execute(\n            \"SELECT c.id AS id, c.heading AS title, c.content AS content,\"\n            \" c.source_id AS source_id, s.title AS source_title,\"\n            \" c.position AS position FROM \" + portal_db._q(CHUNKS_TABLE) +\n            \" c JOIN \" + portal_db._q(SOURCES_TABLE) +\n            \" s ON s.id = c.source_id AND s.client_id = c.client_id\"\n            \" WHERE c.client_id = %s AND s.status = 'published'\"\n            \" AND c.id = ANY(%s)\",\n            (client_id, chunk_ids),\n        )\n        for row in portal_db.rows(cur):\n            out[(\"chunk\", int(row.get(\"id\") or 0))] = dict(row, kind=\"chunk\")\n    if entry_ids and include_entries:\n        cur.execute(\n            \"SELECT e.id AS id, e.title AS title, e.content AS content FROM \"\n            + portal_db._q(ENTRIES_TABLE) + \" e\"\n            \" WHERE e.client_id = %s AND e.is_active IS TRUE AND e.id = ANY(%s)\",\n            (client_id, entry_ids),\n        )\n        for row in portal_db.rows(cur):\n            out[(\"entry\", int(row.get(\"id\") or 0))] = dict(row, kind=\"entry\")\n    return out\n\n\ndef _hit_from_row(row: Dict[str, Any], snippet_chars: int) -> Dict[str, Any]:\n    return {\n        \"kind\": str(row.get(\"kind\") or \"entry\"),\n        \"id\": int(row.get(\"id\") or 0),\n        \"title\": str(row.get(\"title\") or \"\"),\n        \"content\": str(row.get(\"content\") or \"\")[:snippet_chars],\n        \"source_id\": int(row.get(\"source_id\") or 0),\n        \"source\": str(row.get(\"source_title\") or \"\"),\n        \"position\": int(row.get(\"position\") or 0),\n        \"score\": 0.0,\n        \"matched\": [],\n    }\n\n\ndef fuse(keyword_hits: List[Dict[str, Any]],\n         semantic: List[Tuple[float, str, int]],\n         items: Dict[Tuple[str, int], Dict[str, Any]],\n         n: int, snippet_chars: int = 400) -> List[Dict[str, Any]]:\n    \"\"\"Reciprocal rank fusion of the keyword list and the semantic list.\n\n    An item found by both ranks above an item found by one. Keyword hits\n    keep their BM25 ``score``; semantic-only hits get ``score`` =\n    similarity x 10 (same visual scale in the trace). Ties break on\n    keyword rank, then kind, then id - deterministic.\"\"\"\n    table: Dict[Tuple[str, int], Dict[str, Any]] = {}\n    for rank, hit in enumerate(keyword_hits, start=1):\n        key = (str(hit.get(\"kind\") or \"\"), int(hit.get(\"id\") or 0))\n        entry = dict(hit)\n        entry[\"via\"] = \"keyword\"\n        entry[\"semantic\"] = None\n        table[key] = {\"hit\": entry, \"rrf\": 1.0 / (RRF_K + rank), \"kw\": rank}\n    for rank, (sim, kind, ref_id) in enumerate(semantic, start=1):\n        key = (kind, ref_id)\n        bonus = 1.0 / (RRF_K + rank)\n        if key in table:\n            table[key][\"rrf\"] += bonus\n            table[key][\"hit\"][\"via\"] = \"both\"\n            table[key][\"hit\"][\"semantic\"] = sim\n            continue\n        row = items.get(key)\n        if row is None:  # unpublished / inactive / deleted -> never shown\n            continue\n        hit = _hit_from_row(row, snippet_chars)\n        hit[\"score\"] = round(sim * 10, 4)\n        hit[\"via\"] = \"semantic\"\n        hit[\"semantic\"] = sim\n        table[key] = {\"hit\": hit, \"rrf\": bonus, \"kw\": 10 ** 6}\n    ordered = sorted(table.items(), key=lambda kv: (\n        -round(kv[1][\"rrf\"], 9), kv[1][\"kw\"], kv[0][0], kv[0][1]))\n    return [value[\"hit\"] for _key, value in ordered[:max(1, n)]]\n\n\ndef hybrid(cur, client_id: int, query: str,\n           keyword_hits: List[Dict[str, Any]], n: int,\n           include_entries: bool = True,\n           snippet_chars: int = 400) -> Optional[List[Dict[str, Any]]]:\n    \"\"\"Semantic recall fused into the keyword ranking, or None when the\n    index is off / empty / the provider is unavailable (caller keeps the\n    keyword result).\"\"\"\n    if not str(query or \"\").strip():\n        return None\n    cfg = config()\n    if not cfg.get(\"active\"):\n        return None\n    try:\n        _ensure_ddl(cur)\n        vectors = load_vectors(cur, client_id, cfg)\n    except Exception as error:\n        logger.info(\"semantic vectors unavailable: %s\", error)\n        return None\n    if not include_entries:\n        vectors = [v for v in vectors if v[0] != \"entry\"]\n    if not vectors:\n        return None  # nothing indexed yet: no query spend\n    qvec = query_vector(cur, client_id, query, cfg)\n    if not qvec:\n        return None\n    semantic = rank_semantic(qvec, vectors,\n                             float(cfg.get(\"min_similarity\") or 0.0),\n                             max(POOL, n))\n    known = {(str(h.get(\"kind\") or \"\"), int(h.get(\"id\") or 0))\n             for h in keyword_hits}\n    missing = [(kind, ref) for _sim, kind, ref in semantic\n               if (kind, ref) not in known]\n    items = _fetch_items(cur, client_id, missing, include_entries) \\\n        if missing else {}\n    return fuse(keyword_hits, semantic, items, n, snippet_chars)\n\n\n# ---------------------------------------------------------------------------\n# Index maintenance\n# ---------------------------------------------------------------------------\n\ndef _current_items(cur, client_id: int) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT 'chunk' AS kind, c.id AS id, c.heading AS title,\"\n        \" c.content AS content, '' AS extra, c.source_id AS source_id,\"\n        \" s.title AS source_title FROM \" + portal_db._q(CHUNKS_TABLE) +\n        \" c JOIN \" + portal_db._q(SOURCES_TABLE) +\n        \" s ON s.id = c.source_id AND s.client_id = c.client_id\"\n        \" WHERE c.client_id = %s AND s.status = 'published'\"\n        \" UNION ALL\"\n        \" SELECT 'entry' AS kind, e.id AS id, e.title AS title,\"\n        \" e.content AS content, e.keywords AS extra, 0 AS source_id,\"\n        \" '' AS source_title FROM \" + portal_db._q(ENTRIES_TABLE) + \" e\"\n        \" WHERE e.client_id = %s AND e.is_active IS TRUE\"\n        \" LIMIT %s\",\n        (client_id, client_id, ITEMS_MAX),\n    )\n    return portal_db.rows(cur)\n\n\ndef _existing(cur, client_id: int) -> Dict[Tuple[str, int], Dict[str, Any]]:\n    cur.execute(\n        \"SELECT kind, ref_id, content_hash, model, dims FROM \"\n        + portal_db._q(EMB_TABLE) + \" WHERE client_id = %s\",\n        (client_id,),\n    )\n    return {(str(r.get(\"kind\") or \"\"), int(r.get(\"ref_id\") or 0)): r\n            for r in portal_db.rows(cur)}\n\n\ndef _reusable(cur, client_id: int, model: str, dims: int,\n              hashes: List[str]) -> Dict[str, List[float]]:\n    if not hashes:\n        return {}\n    cur.execute(\n        \"SELECT DISTINCT ON (content_hash) content_hash, vector FROM \"\n        + portal_db._q(EMB_TABLE) +\n        \" WHERE client_id = %s AND model = %s AND dims = %s\"\n        \" AND content_hash = ANY(%s) ORDER BY content_hash, id DESC\",\n        (client_id, model, dims, hashes),\n    )\n    out = {}\n    for row in portal_db.rows(cur):\n        vector = row.get(\"vector\")\n        if vector:\n            out[str(row.get(\"content_hash\") or \"\")] = [float(v) for v in vector]\n    return out\n\n\ndef _upsert(cur, client_id: int, item: Dict[str, Any], digest: str,\n            model: str, dims: int, vector: List[float]) -> None:\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(EMB_TABLE) +\n        \" (client_id, kind, ref_id, source_id, content_hash, model, dims,\"\n        \" vector) VALUES (%s, %s, %s, %s, %s, %s, %s, %s::real[])\"\n        \" ON CONFLICT (client_id, kind, ref_id) DO UPDATE SET\"\n        \" source_id = EXCLUDED.source_id,\"\n        \" content_hash = EXCLUDED.content_hash, model = EXCLUDED.model,\"\n        \" dims = EXCLUDED.dims, vector = EXCLUDED.vector, updated_at = NOW()\",\n        (client_id, str(item.get(\"kind\") or \"\"), int(item.get(\"id\") or 0),\n         int(item.get(\"source_id\") or 0), digest, model, dims,\n         [round(v, 7) for v in vector]),\n    )\n\n\ndef _delete_stale(cur, client_id: int,\n                  keep: List[Tuple[str, int]]) -> int:\n    chunk_ids = [ref for kind, ref in keep if kind == \"chunk\"] or [0]\n    entry_ids = [ref for kind, ref in keep if kind == \"entry\"] or [0]\n    cur.execute(\n        \"DELETE FROM \" + portal_db._q(EMB_TABLE) +\n        \" WHERE client_id = %s AND NOT (\"\n        \" (kind = 'chunk' AND ref_id = ANY(%s))\"\n        \" OR (kind = 'entry' AND ref_id = ANY(%s)))\",\n        (client_id, chunk_ids, entry_ids),\n    )\n    return int(getattr(cur, \"rowcount\", 0) or 0)\n\n\ndef _save_state(cur, client_id: int, error: str, embedded: int, reused: int,\n                model: str, dims: int) -> None:\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(STATE_TABLE) +\n        \" (client_id, last_sync_at, last_error, last_embedded, last_reused,\"\n        \" model, dims, updated_at) VALUES (%s, NOW(), %s, %s, %s, %s, %s, NOW())\"\n        \" ON CONFLICT (client_id) DO UPDATE SET last_sync_at = NOW(),\"\n        \" last_error = EXCLUDED.last_error,\"\n        \" last_embedded = EXCLUDED.last_embedded,\"\n        \" last_reused = EXCLUDED.last_reused, model = EXCLUDED.model,\"\n        \" dims = EXCLUDED.dims, updated_at = NOW()\",\n        (client_id, str(error or \"\")[:300], int(embedded), int(reused),\n         model, int(dims)),\n    )\n\n\ndef sync(cur, client_id: int, budget: Optional[int] = None,\n         cfg: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:\n    \"\"\"Bring the tenant's vectors in line with its published knowledge.\n\n    Reuses vectors by content hash (re-index / rollback cost nothing),\n    embeds up to ``budget`` changed items in provider batches, drops\n    vectors of deleted/unpublished/inactive items, records the outcome.\n    Returns {ok, embedded, reused, removed, pending, error}.\"\"\"\n    cfg = cfg or config()\n    out = {\"ok\": False, \"embedded\": 0, \"reused\": 0, \"removed\": 0,\n           \"pending\": 0, \"error\": \"\"}\n    if not cfg.get(\"active\"):\n        out[\"error\"] = \"not_active:\" + str(cfg.get(\"reason\") or \"\")\n        return out\n    import portal_llm\n\n    _ensure_ddl(cur)\n    model = str(cfg.get(\"model\") or \"\")\n    dims = int(cfg.get(\"dimensions\") or 0)\n    items = _current_items(cur, client_id)\n    existing = _existing(cur, client_id)\n    todo: List[Tuple[Dict[str, Any], str, str]] = []\n    keep: List[Tuple[str, int]] = []\n    for item in items:\n        key = (str(item.get(\"kind\") or \"\"), int(item.get(\"id\") or 0))\n        keep.append(key)\n        text = item_text(item)\n        if not text.strip():\n            continue\n        digest = content_hash(text)\n        have = existing.get(key)\n        if (have and str(have.get(\"content_hash\") or \"\") == digest\n                and str(have.get(\"model\") or \"\") == model\n                and int(have.get(\"dims\") or 0) == dims):\n            continue\n        todo.append((item, text, digest))\n    reuse = _reusable(cur, client_id, model, dims,\n                      sorted({d for _i, _t, d in todo}))\n    fresh: List[Tuple[Dict[str, Any], str, str]] = []\n    for item, text, digest in todo:\n        if digest in reuse:\n            _upsert(cur, client_id, item, digest, model, dims, reuse[digest])\n            out[\"reused\"] += 1\n        else:\n            fresh.append((item, text, digest))\n    limit = SYNC_BUDGET if budget is None else max(0, int(budget))\n    batch_size = portal_llm.EMBED_MAX_INPUTS\n    error = \"\"\n    done = 0\n    for start in range(0, min(len(fresh), limit), batch_size):\n        batch = fresh[start:min(start + batch_size, limit)]\n        vectors, error = _embed([t for _i, t, _d in batch], cfg, client_id,\n                                cur)\n        if not vectors:\n            if error and \"blocked by the platform\" not in error:\n                _trip(error)\n            break\n        _heal()\n        for (item, _text, digest), vector in zip(batch, vectors):\n            _upsert(cur, client_id, item, digest, model, dims, vector)\n        done += len(batch)\n    out[\"embedded\"] = done\n    out[\"pending\"] = max(0, len(fresh) - done)\n    out[\"removed\"] = _delete_stale(cur, client_id, keep)\n    out[\"error\"] = error\n    out[\"ok\"] = not error\n    _save_state(cur, client_id, error, done, out[\"reused\"], model, dims)\n    invalidate(client_id)\n    if done or out[\"reused\"] or out[\"removed\"]:\n        try:\n            portal_db.log_action(\n                cur, client_id, \"kb.semantic_synced\", \"system\", None, None,\n                \"Semantic index: \" + str(done) + \" embedded, \"\n                + str(out[\"reused\"]) + \" reused, \" + str(out[\"removed\"])\n                + \" removed\" + (\", \" + str(out[\"pending\"]) + \" pending\"\n                                if out[\"pending\"] else \"\"))\n        except Exception:\n            pass\n    return out\n\n\ndef status(cur, client_id: int) -> Dict[str, Any]:\n    \"\"\"Owner-facing index health (no secrets).\"\"\"\n    cfg = config()\n    _ensure_ddl(cur)\n    model = str(cfg.get(\"model\") or \"\")\n    dims = int(cfg.get(\"dimensions\") or 0)\n    cur.execute(\n        \"SELECT (SELECT COUNT(*) FROM \" + portal_db._q(CHUNKS_TABLE) +\n        \" c JOIN \" + portal_db._q(SOURCES_TABLE) +\n        \" s ON s.id = c.source_id AND s.client_id = c.client_id\"\n        \" WHERE c.client_id = %s AND s.status = 'published') AS chunks,\"\n        \" (SELECT COUNT(*) FROM \" + portal_db._q(ENTRIES_TABLE) +\n        \" WHERE client_id = %s AND is_active IS TRUE) AS entries,\"\n        \" (SELECT COUNT(*) FROM \" + portal_db._q(EMB_TABLE) +\n        \" WHERE client_id = %s AND model = %s AND dims = %s) AS indexed\",\n        (client_id, client_id, client_id, model, dims),\n    )\n    counts = (portal_db.rows(cur) or [{}])[0]\n    cur.execute(\n        \"SELECT last_sync_at, last_error, last_embedded, last_reused FROM \"\n        + portal_db._q(STATE_TABLE) + \" WHERE client_id = %s\",\n        (client_id,),\n    )\n    state = (portal_db.rows(cur) or [{}])[0]\n    total = int(counts.get(\"chunks\") or 0) + int(counts.get(\"entries\") or 0)\n    indexed = min(int(counts.get(\"indexed\") or 0), total) if total else 0\n    stamp = state.get(\"last_sync_at\")\n    return {\n        \"active\": bool(cfg.get(\"active\")),\n        \"reason\": str(cfg.get(\"reason\") or \"\"),\n        \"mode\": str(cfg.get(\"mode\") or \"on\"),\n        \"model\": model,\n        \"dimensions\": dims,\n        \"min_similarity\": float(cfg.get(\"min_similarity\") or 0.0),\n        \"key_source\": str(cfg.get(\"key_source\") or \"none\"),\n        \"total\": total,\n        \"indexed\": indexed,\n        \"pending\": max(0, total - indexed),\n        \"coverage\": round(indexed / float(total), 4) if total else 0.0,\n        \"running\": int(client_id) in _RUNNING,\n        \"provider_cooldown\": _provider_down(),\n        \"last_sync_at\": stamp.isoformat() if hasattr(stamp, \"isoformat\")\n        else (str(stamp) if stamp else None),\n        \"last_error\": str(state.get(\"last_error\") or \"\"),\n        \"last_embedded\": int(state.get(\"last_embedded\") or 0),\n        \"last_reused\": int(state.get(\"last_reused\") or 0),\n    }\n\n\ndef _sync_job(client_id: int, rounds: int) -> None:\n    try:\n        for _ in range(max(1, rounds)):\n            conn = portal_db._conn()\n            try:\n                with conn.cursor() as cur:\n                    result = sync(cur, client_id)\n                conn.commit()\n            finally:\n                conn.close()\n            if not result.get(\"pending\") or result.get(\"error\"):\n                break\n    except Exception as error:\n        logger.info(\"semantic sync failed client=%s: %s\", client_id, error)\n    finally:\n        with _LOCK:\n            _RUNNING.discard(int(client_id))\n\n\ndef kick(client_id: int, reason: str = \"edit\", rounds: int = 3) -> bool:\n    \"\"\"Run a sync on a daemon thread after the caller's commit. One job per\n    tenant per process; ``tick`` kicks are throttled to TICK_SECONDS.\n    Returns True when a job was started. Never raises.\"\"\"\n    try:\n        client_id = int(client_id or 0)\n        if client_id <= 0 or not config().get(\"active\"):\n            return False\n        now = time.monotonic()\n        with _LOCK:\n            if client_id in _RUNNING:\n                return False\n            if reason == \"tick\" and now - _LAST_KICK.get(client_id, -1e9) \\\n                    < TICK_SECONDS:\n                return False\n            if reason == \"tick\" and _provider_down():\n                return False\n            _RUNNING.add(client_id)\n            _LAST_KICK[client_id] = now\n        threading.Thread(target=_sync_job, args=(client_id, rounds),\n                         daemon=True,\n                         name=\"of-kb-embed-\" + str(client_id)).start()\n        return True\n    except Exception as error:\n        with _LOCK:\n            _RUNNING.discard(int(client_id or 0))\n        logger.info(\"semantic kick skipped: %s\", error)\n        return False\n\n\n# ---------------------------------------------------------------------------\n# HTTP\n# ---------------------------------------------------------------------------\n\ndef _principal():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    return principal, None\n\n\ndef _status_response(client_id: int, started: bool = False):\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            payload = status(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    if started:\n        payload[\"running\"] = True\n    payload[\"started\"] = started\n    return jsonify(payload), 200\n\n\n@bp.get(\"/kb/semantic\")\ndef get_semantic_status():\n    principal, error = _principal()\n    if error:\n        return error\n    try:\n        return _status_response(int(principal.get(\"client_id\") or 0))\n    except Exception as problem:\n        return jsonify(portal_db.portal_unavailable(\n            problem, \"knowledge semantic index\")[0]), 503\n\n\n@bp.post(\"/kb/semantic/sync\")\ndef post_semantic_sync():\n    \"\"\"Owner \"Build index now\": starts a background sync (the website\n    request budget is short) and returns the current status.\"\"\"\n    principal, error = _principal()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    client_id = int(principal.get(\"client_id\") or 0)\n    cfg = config()\n    if not cfg.get(\"active\"):\n        return jsonify({\"error\": {\n            \"code\": \"not_configured\",\n            \"message\": (\"Semantic search is switched off by the platform.\"\n                        if cfg.get(\"reason\") == \"off\" else\n                        \"Semantic search needs an AI key with embeddings.\"\n                        \" Ask the platform admin to configure it.\"),\n        }}), 409\n    rounds = 1 if str(request.args.get(\"once\") or \"\") == \"1\" else 10\n    started = kick(client_id, \"manual\", rounds=rounds)\n    try:\n        return _status_response(client_id, started)\n    except Exception as problem:\n        return jsonify(portal_db.portal_unavailable(\n            problem, \"knowledge semantic index\")[0]), 503\n\n\ndef kick_after_mutation(response):\n    \"\"\"after_request hook for the knowledge blueprints: a successful owner\n    write (source/entry create, edit, publish, pause, delete, re-index,\n    rollback) schedules a background sync. Never alters the response.\"\"\"\n    try:\n        if request.method in (\"GET\", \"HEAD\", \"OPTIONS\"):\n            return response\n        if int(getattr(response, \"status_code\", 500)) >= 400:\n            return response\n        if not config().get(\"active\"):\n            return response\n        principal = authenticate_portal_request()\n        if principal:\n            kick(int(principal.get(\"client_id\") or 0), \"edit\")\n    except Exception:\n        pass\n    return response\n");
writeNewRepair("OmniFlow-Control-Plane/portal_kb_semantic.py", "def _save_state(cur, client_id: int, error: str, embedded: int, reused: int,", true,
    "\"\"\"Knowledge semantic index (owner decision D1 - delivered in \u00a7211).\n\nAudit-first: this is NOT a second knowledge engine. ``portal_knowledge``\nstays the one ingestion/versioning/retrieval owner and\n``portal_knowledge.retrieve`` stays the one read the brain and the owner's\ntester call. This module only adds meaning-based recall to that read:\n\n* ``portal_kb_embeddings`` - one vector per retrievable item: chunks of\n  PUBLISHED sources and ACTIVE Q&A entries. Vectors are L2-normalised\n  REAL[] columns in the existing Postgres (no pgvector, no new service),\n  keyed by (client_id, kind, ref_id) and a content hash, so re-indexing a\n  source with unchanged text or rolling back a version reuses the stored\n  vector instead of paying for it again.\n* ``sync`` - embeds whatever is missing or changed (budgeted, batched),\n  reuses vectors by content hash and drops vectors whose item was deleted,\n  unpublished or deactivated. Runs on a daemon thread after owner edits,\n  from the connector tick (throttled) and from the \"Build index\" button.\n* ``hybrid`` - called from ``portal_knowledge.retrieve``: embeds the\n  question once (small LRU cache), scores it against the tenant's vectors\n  (in-process cache, TTL) and fuses the result with the existing keyword\n  ranking by reciprocal rank fusion. Hits keep the exact retrieval\n  contract plus ``via`` (keyword|semantic|both) and ``semantic``.\n\nLaws kept:\n* KB auto-publish LOCK - semantic hits are re-read through the same\n  \"published source / active entry\" filters as keyword hits, so a paused\n  or draft source never reaches the AI even if its vector still exists.\n* Fail-soft - any provider/config/DB problem returns ``None`` and the\n  caller falls back to pure keyword retrieval. A failing provider trips a\n  short cooldown so the reply path never waits on a dead endpoint twice.\n* Costs go through ``portal_llm`` (platform AI gate + usage ledger) under\n  the ``kb_embed`` feature, attributed to the persona of the calling scope.\n* Customer text is only embedded (never executed or used as a prompt).\n\"\"\"\n\nimport hashlib\nimport logging\nimport os\nimport threading\nimport time\nfrom collections import OrderedDict\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n    ensure_human_principal,\n)\n\nlogger = logging.getLogger(\"omniflow.portal-kb-semantic\")\n\nbp = Blueprint(\"portal_kb_semantic\", __name__, url_prefix=\"/api/v1/portal\")\n\nEMB_TABLE = \"portal_kb_embeddings\"\nSTATE_TABLE = \"portal_kb_semantic_state\"\nCHUNKS_TABLE = \"portal_kb_chunks\"\nSOURCES_TABLE = \"portal_kb_sources\"\nENTRIES_TABLE = \"portal_kb_entries\"\nFEATURE = \"kb_embed\"\n\n\ndef _env_int(name: str, default: int, lo: int, hi: int) -> int:\n    try:\n        value = int(os.environ.get(name, \"\") or default)\n    except Exception:\n        value = default\n    return max(lo, min(hi, value))\n\n\ndef _env_float(name: str, default: float, lo: float, hi: float) -> float:\n    try:\n        value = float(os.environ.get(name, \"\") or default)\n    except Exception:\n        value = default\n    return max(lo, min(hi, value))\n\n\nSYNC_BUDGET = _env_int(\"OF_KB_EMBED_SYNC_MAX\", 400, 1, 20000)\nSCAN_MAX = _env_int(\"OF_KB_EMBED_SCAN_MAX\", 5000, 50, 50000)\nITEMS_MAX = _env_int(\"OF_KB_EMBED_ITEMS_MAX\", 20000, 50, 200000)\nCACHE_SECONDS = _env_int(\"OF_KB_EMBED_CACHE_SECONDS\", 60, 0, 3600)\nTICK_SECONDS = _env_int(\"OF_KB_EMBED_TICK_SECONDS\", 600, 30, 86400)\nCOOLDOWN_SECONDS = _env_int(\"OF_KB_EMBED_COOLDOWN_SECONDS\", 300, 10, 86400)\nQUERY_TIMEOUT = _env_float(\"OF_KB_EMBED_QUERY_TIMEOUT\", 3.0, 0.5, 30.0)\nQUERY_CACHE_MAX = _env_int(\"OF_KB_EMBED_QUERY_CACHE\", 256, 0, 10000)\nREL_WINDOW = _env_float(\"OF_KB_EMBED_REL_WINDOW\", 0.12, 0.0, 1.0)\nRRF_K = _env_int(\"OF_KB_EMBED_RRF_K\", 60, 1, 1000)\nPOOL = _env_int(\"OF_KB_EMBED_POOL\", 12, 3, 100)\nTEXT_CHARS = _env_int(\"OF_EMBED_TEXT_CHARS\", 2000, 200, 20000)\n\n_DDL_READY = False\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_kb_embeddings (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  kind TEXT NOT NULL,\n  ref_id BIGINT NOT NULL,\n  source_id BIGINT NOT NULL DEFAULT 0,\n  content_hash TEXT NOT NULL DEFAULT '',\n  model TEXT NOT NULL DEFAULT '',\n  dims INT NOT NULL DEFAULT 0,\n  vector REAL[] NOT NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  UNIQUE (client_id, kind, ref_id)\n);\nCREATE INDEX IF NOT EXISTS idx_portal_kb_embeddings_hash\n  ON portal_kb_embeddings (client_id, model, dims, content_hash);\nCREATE TABLE IF NOT EXISTS portal_kb_semantic_state (\n  client_id BIGINT PRIMARY KEY,\n  last_sync_at TIMESTAMPTZ,\n  last_error TEXT NOT NULL DEFAULT '',\n  last_embedded INT NOT NULL DEFAULT 0,\n  last_reused INT NOT NULL DEFAULT 0,\n  model TEXT NOT NULL DEFAULT '',\n  dims INT NOT NULL DEFAULT 0,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\"\"\"\n\n\ndef _ensure_ddl(cur) -> None:\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_DDL)\n    _DDL_READY = True\n\n\n# ---------------------------------------------------------------------------\n# Config, text, hashing (pure)\n# ---------------------------------------------------------------------------\n\ndef config() -> Dict[str, Any]:\n    \"\"\"Effective embedding config; inactive on any error.\"\"\"\n    try:\n        import portal_llm\n        return portal_llm.embed_runtime()\n    except Exception:\n        return {\"active\": False, \"reason\": \"no_key\", \"model\": \"\",\n                \"dimensions\": 0, \"min_similarity\": 0.3, \"mode\": \"on\",\n                \"key_source\": \"none\", \"base_url\": \"\"}\n\n\ndef item_text(row: Dict[str, Any]) -> str:\n    \"\"\"The text a vector represents. Chunks carry their document + section\n    so a bare paragraph still knows what it is about.\"\"\"\n    kind = str(row.get(\"kind\") or \"\")\n    title = str(row.get(\"title\") or \"\").strip()\n    content = str(row.get(\"content\") or \"\").strip()\n    if kind == \"chunk\":\n        source = str(row.get(\"source_title\") or \"\").strip()\n        head = \" > \".join(p for p in (source, title) if p)\n        text = (head + \"\\n\" + content) if head else content\n    else:\n        extra = str(row.get(\"extra\") or \"\").strip()\n        text = \"\\n\".join(p for p in (title, content, extra) if p)\n    return text[:TEXT_CHARS]\n\n\ndef content_hash(text: str) -> str:\n    return hashlib.sha1(str(text or \"\").encode(\"utf-8\")).hexdigest()\n\n\ndef dot(a: List[float], b: List[float]) -> float:\n    if len(a) != len(b):\n        return -1.0\n    return sum(x * y for x, y in zip(a, b))\n\n\n# ---------------------------------------------------------------------------\n# Provider health (cooldown) + caches\n# ---------------------------------------------------------------------------\n\n_LOCK = threading.Lock()\n_DOWN_UNTIL = {\"t\": 0.0, \"error\": \"\"}\n_QUERY_CACHE: \"OrderedDict[Tuple[str, int, str], List[float]]\" = OrderedDict()\n_VEC_CACHE: Dict[int, Dict[str, Any]] = {}\n_RUNNING: set = set()\n_LAST_KICK: Dict[int, float] = {}\n\n\ndef _provider_down() -> bool:\n    return time.monotonic() < _DOWN_UNTIL[\"t\"]\n\n\ndef _trip(error: str) -> None:\n    _DOWN_UNTIL[\"t\"] = time.monotonic() + COOLDOWN_SECONDS\n    _DOWN_UNTIL[\"error\"] = str(error or \"\")[:200]\n\n\ndef _heal() -> None:\n    _DOWN_UNTIL[\"t\"] = 0.0\n    _DOWN_UNTIL[\"error\"] = \"\"\n\n\ndef invalidate(client_id: int) -> None:\n    with _LOCK:\n        _VEC_CACHE.pop(int(client_id), None)\n\n\ndef reset_caches() -> None:\n    \"\"\"Tests / admin: forget every in-process cache and cooldown.\"\"\"\n    with _LOCK:\n        _VEC_CACHE.clear()\n        _QUERY_CACHE.clear()\n        _RUNNING.clear()\n        _LAST_KICK.clear()\n    _heal()\n\n\ndef _embed(texts: List[str], cfg: Dict[str, Any], client_id: int, cur,\n           timeout: Optional[float] = None\n           ) -> Tuple[Optional[List[List[float]]], str]:\n    import portal_llm\n\n    try:\n        _feature, _cid, _cur, agent_id = portal_llm.current_scope()\n    except Exception:\n        agent_id = 0\n    with portal_llm.usage_scope(FEATURE, client_id, cur, agent_id=agent_id):\n        return portal_llm.embed_texts(texts, timeout=timeout, runtime=cfg)\n\n\ndef query_vector(cur, client_id: int, text: str,\n                 cfg: Dict[str, Any]) -> Optional[List[float]]:\n    \"\"\"One question -> one vector (cached per model/dims/text).\"\"\"\n    clean = \" \".join(str(text or \"\").split())[:TEXT_CHARS]\n    if not clean:\n        return None\n    key = (str(cfg.get(\"model\") or \"\"), int(cfg.get(\"dimensions\") or 0),\n           clean.lower())\n    with _LOCK:\n        if key in _QUERY_CACHE:\n            _QUERY_CACHE.move_to_end(key)\n            return _QUERY_CACHE[key]\n    if _provider_down():\n        return None\n    vectors, error = _embed([clean], cfg, client_id, cur, QUERY_TIMEOUT)\n    if not vectors:\n        if error and \"blocked by the platform\" not in error:\n            _trip(error)\n        return None\n    _heal()\n    vector = vectors[0]\n    if QUERY_CACHE_MAX:\n        with _LOCK:\n            _QUERY_CACHE[key] = vector\n            while len(_QUERY_CACHE) > QUERY_CACHE_MAX:\n                _QUERY_CACHE.popitem(last=False)\n    return vector\n\n\ndef load_vectors(cur, client_id: int,\n                 cfg: Dict[str, Any]) -> List[Tuple[str, int, List[float]]]:\n    \"\"\"The tenant's current vectors for the configured model/dims (cached\n    CACHE_SECONDS per process; sync invalidates its own process).\"\"\"\n    model = str(cfg.get(\"model\") or \"\")\n    dims = int(cfg.get(\"dimensions\") or 0)\n    now = time.monotonic()\n    with _LOCK:\n        cached = _VEC_CACHE.get(int(client_id))\n        if (cached and cached[\"model\"] == model and cached[\"dims\"] == dims\n                and now - cached[\"at\"] < CACHE_SECONDS):\n            return cached[\"rows\"]\n    cur.execute(\n        \"SELECT kind, ref_id, vector FROM \" + portal_db._q(EMB_TABLE) +\n        \" WHERE client_id = %s AND model = %s AND dims = %s\"\n        \" ORDER BY id LIMIT %s\",\n        (client_id, model, dims, SCAN_MAX),\n    )\n    rows: List[Tuple[str, int, List[float]]] = []\n    for row in portal_db.rows(cur):\n        vector = row.get(\"vector\")\n        if not vector:\n            continue\n        try:\n            rows.append((str(row.get(\"kind\") or \"\"), int(row.get(\"ref_id\") or 0),\n                         [float(v) for v in vector]))\n        except Exception:\n            continue\n    if CACHE_SECONDS:\n        with _LOCK:\n            _VEC_CACHE[int(client_id)] = {\"at\": now, \"model\": model,\n                                          \"dims\": dims, \"rows\": rows}\n    return rows\n\n\ndef rank_semantic(qvec: List[float],\n                  vectors: List[Tuple[str, int, List[float]]],\n                  min_sim: float, pool: int) -> List[Tuple[float, str, int]]:\n    \"\"\"Cosine (dot of unit vectors) ranking, filtered by an absolute floor\n    and a window below the best match so a weak tail never rides along.\n    Deterministic: ties break on kind then id.\"\"\"\n    scored = []\n    for kind, ref_id, vector in vectors:\n        sim = dot(qvec, vector)\n        if sim >= min_sim:\n            scored.append((round(sim, 4), kind, ref_id))\n    if not scored:\n        return []\n    scored.sort(key=lambda s: (-s[0], s[1], s[2]))\n    floor = max(min_sim, scored[0][0] - REL_WINDOW)\n    return [s for s in scored if s[0] >= floor][:max(1, pool)]\n\n\n# ---------------------------------------------------------------------------\n# Hybrid retrieval (called by portal_knowledge.retrieve)\n# ---------------------------------------------------------------------------\n\ndef _fetch_items(cur, client_id: int, keys: List[Tuple[str, int]],\n                 include_entries: bool) -> Dict[Tuple[str, int], Dict[str, Any]]:\n    \"\"\"Re-read semantic-only hits through the SAME publish/active filters\n    as the keyword path (auto-publish lock).\"\"\"\n    chunk_ids = [ref for kind, ref in keys if kind == \"chunk\"]\n    entry_ids = [ref for kind, ref in keys if kind == \"entry\"]\n    out: Dict[Tuple[str, int], Dict[str, Any]] = {}\n    if chunk_ids:\n        cur.execute(\n            \"SELECT c.id AS id, c.heading AS title, c.content AS content,\"\n            \" c.source_id AS source_id, s.title AS source_title,\"\n            \" c.position AS position FROM \" + portal_db._q(CHUNKS_TABLE) +\n            \" c JOIN \" + portal_db._q(SOURCES_TABLE) +\n            \" s ON s.id = c.source_id AND s.client_id = c.client_id\"\n            \" WHERE c.client_id = %s AND s.status = 'published'\"\n            \" AND c.id = ANY(%s)\",\n            (client_id, chunk_ids),\n        )\n        for row in portal_db.rows(cur):\n            out[(\"chunk\", int(row.get(\"id\") or 0))] = dict(row, kind=\"chunk\")\n    if entry_ids and include_entries:\n        cur.execute(\n            \"SELECT e.id AS id, e.title AS title, e.content AS content FROM \"\n            + portal_db._q(ENTRIES_TABLE) + \" e\"\n            \" WHERE e.client_id = %s AND e.is_active IS TRUE AND e.id = ANY(%s)\",\n            (client_id, entry_ids),\n        )\n        for row in portal_db.rows(cur):\n            out[(\"entry\", int(row.get(\"id\") or 0))] = dict(row, kind=\"entry\")\n    return out\n\n\ndef _hit_from_row(row: Dict[str, Any], snippet_chars: int) -> Dict[str, Any]:\n    return {\n        \"kind\": str(row.get(\"kind\") or \"entry\"),\n        \"id\": int(row.get(\"id\") or 0),\n        \"title\": str(row.get(\"title\") or \"\"),\n        \"content\": str(row.get(\"content\") or \"\")[:snippet_chars],\n        \"source_id\": int(row.get(\"source_id\") or 0),\n        \"source\": str(row.get(\"source_title\") or \"\"),\n        \"position\": int(row.get(\"position\") or 0),\n        \"score\": 0.0,\n        \"matched\": [],\n    }\n\n\ndef fuse(keyword_hits: List[Dict[str, Any]],\n         semantic: List[Tuple[float, str, int]],\n         items: Dict[Tuple[str, int], Dict[str, Any]],\n         n: int, snippet_chars: int = 400) -> List[Dict[str, Any]]:\n    \"\"\"Reciprocal rank fusion of the keyword list and the semantic list.\n\n    An item found by both ranks above an item found by one. Keyword hits\n    keep their BM25 ``score``; semantic-only hits get ``score`` =\n    similarity x 10 (same visual scale in the trace). Ties break on\n    keyword rank, then kind, then id - deterministic.\"\"\"\n    table: Dict[Tuple[str, int], Dict[str, Any]] = {}\n    for rank, hit in enumerate(keyword_hits, start=1):\n        key = (str(hit.get(\"kind\") or \"\"), int(hit.get(\"id\") or 0))\n        entry = dict(hit)\n        entry[\"via\"] = \"keyword\"\n        entry[\"semantic\"] = None\n        table[key] = {\"hit\": entry, \"rrf\": 1.0 / (RRF_K + rank), \"kw\": rank}\n    for rank, (sim, kind, ref_id) in enumerate(semantic, start=1):\n        key = (kind, ref_id)\n        bonus = 1.0 / (RRF_K + rank)\n        if key in table:\n            table[key][\"rrf\"] += bonus\n            table[key][\"hit\"][\"via\"] = \"both\"\n            table[key][\"hit\"][\"semantic\"] = sim\n            continue\n        row = items.get(key)\n        if row is None:  # unpublished / inactive / deleted -> never shown\n            continue\n        hit = _hit_from_row(row, snippet_chars)\n        hit[\"score\"] = round(sim * 10, 4)\n        hit[\"via\"] = \"semantic\"\n        hit[\"semantic\"] = sim\n        table[key] = {\"hit\": hit, \"rrf\": bonus, \"kw\": 10 ** 6}\n    ordered = sorted(table.items(), key=lambda kv: (\n        -round(kv[1][\"rrf\"], 9), kv[1][\"kw\"], kv[0][0], kv[0][1]))\n    return [value[\"hit\"] for _key, value in ordered[:max(1, n)]]\n\n\ndef hybrid(cur, client_id: int, query: str,\n           keyword_hits: List[Dict[str, Any]], n: int,\n           include_entries: bool = True,\n           snippet_chars: int = 400) -> Optional[List[Dict[str, Any]]]:\n    \"\"\"Semantic recall fused into the keyword ranking, or None when the\n    index is off / empty / the provider is unavailable (caller keeps the\n    keyword result).\"\"\"\n    if not str(query or \"\").strip():\n        return None\n    cfg = config()\n    if not cfg.get(\"active\"):\n        return None\n    try:\n        _ensure_ddl(cur)\n        vectors = load_vectors(cur, client_id, cfg)\n    except Exception as error:\n        logger.info(\"semantic vectors unavailable: %s\", error)\n        return None\n    if not include_entries:\n        vectors = [v for v in vectors if v[0] != \"entry\"]\n    if not vectors:\n        return None  # nothing indexed yet: no query spend\n    qvec = query_vector(cur, client_id, query, cfg)\n    if not qvec:\n        return None\n    semantic = rank_semantic(qvec, vectors,\n                             float(cfg.get(\"min_similarity\") or 0.0),\n                             max(POOL, n))\n    known = {(str(h.get(\"kind\") or \"\"), int(h.get(\"id\") or 0))\n             for h in keyword_hits}\n    missing = [(kind, ref) for _sim, kind, ref in semantic\n               if (kind, ref) not in known]\n    items = _fetch_items(cur, client_id, missing, include_entries) \\\n        if missing else {}\n    return fuse(keyword_hits, semantic, items, n, snippet_chars)\n\n\n# ---------------------------------------------------------------------------\n# Index maintenance\n# ---------------------------------------------------------------------------\n\ndef _current_items(cur, client_id: int) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT 'chunk' AS kind, c.id AS id, c.heading AS title,\"\n        \" c.content AS content, '' AS extra, c.source_id AS source_id,\"\n        \" s.title AS source_title FROM \" + portal_db._q(CHUNKS_TABLE) +\n        \" c JOIN \" + portal_db._q(SOURCES_TABLE) +\n        \" s ON s.id = c.source_id AND s.client_id = c.client_id\"\n        \" WHERE c.client_id = %s AND s.status = 'published'\"\n        \" UNION ALL\"\n        \" SELECT 'entry' AS kind, e.id AS id, e.title AS title,\"\n        \" e.content AS content, e.keywords AS extra, 0 AS source_id,\"\n        \" '' AS source_title FROM \" + portal_db._q(ENTRIES_TABLE) + \" e\"\n        \" WHERE e.client_id = %s AND e.is_active IS TRUE\"\n        \" LIMIT %s\",\n        (client_id, client_id, ITEMS_MAX),\n    )\n    return portal_db.rows(cur)\n\n\ndef _existing(cur, client_id: int) -> Dict[Tuple[str, int], Dict[str, Any]]:\n    cur.execute(\n        \"SELECT kind, ref_id, content_hash, model, dims FROM \"\n        + portal_db._q(EMB_TABLE) + \" WHERE client_id = %s\",\n        (client_id,),\n    )\n    return {(str(r.get(\"kind\") or \"\"), int(r.get(\"ref_id\") or 0)): r\n            for r in portal_db.rows(cur)}\n\n\ndef _reusable(cur, client_id: int, model: str, dims: int,\n              hashes: List[str]) -> Dict[str, List[float]]:\n    if not hashes:\n        return {}\n    cur.execute(\n        \"SELECT DISTINCT ON (content_hash) content_hash, vector FROM \"\n        + portal_db._q(EMB_TABLE) +\n        \" WHERE client_id = %s AND model = %s AND dims = %s\"\n        \" AND content_hash = ANY(%s) ORDER BY content_hash, id DESC\",\n        (client_id, model, dims, hashes),\n    )\n    out = {}\n    for row in portal_db.rows(cur):\n        vector = row.get(\"vector\")\n        if vector:\n            out[str(row.get(\"content_hash\") or \"\")] = [float(v) for v in vector]\n    return out\n\n\ndef _upsert(cur, client_id: int, item: Dict[str, Any], digest: str,\n            model: str, dims: int, vector: List[float]) -> None:\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(EMB_TABLE) +\n        \" (client_id, kind, ref_id, source_id, content_hash, model, dims,\"\n        \" vector) VALUES (%s, %s, %s, %s, %s, %s, %s, %s::real[])\"\n        \" ON CONFLICT (client_id, kind, ref_id) DO UPDATE SET\"\n        \" source_id = EXCLUDED.source_id,\"\n        \" content_hash = EXCLUDED.content_hash, model = EXCLUDED.model,\"\n        \" dims = EXCLUDED.dims, vector = EXCLUDED.vector, updated_at = NOW()\",\n        (client_id, str(item.get(\"kind\") or \"\"), int(item.get(\"id\") or 0),\n         int(item.get(\"source_id\") or 0), digest, model, dims,\n         [round(v, 7) for v in vector]),\n    )\n\n\ndef _delete_stale(cur, client_id: int,\n                  keep: List[Tuple[str, int]]) -> int:\n    chunk_ids = [ref for kind, ref in keep if kind == \"chunk\"] or [0]\n    entry_ids = [ref for kind, ref in keep if kind == \"entry\"] or [0]\n    cur.execute(\n        \"DELETE FROM \" + portal_db._q(EMB_TABLE) +\n        \" WHERE client_id = %s AND NOT (\"\n        \" (kind = 'chunk' AND ref_id = ANY(%s))\"\n        \" OR (kind = 'entry' AND ref_id = ANY(%s)))\",\n        (client_id, chunk_ids, entry_ids),\n    )\n    return int(getattr(cur, \"rowcount\", 0) or 0)\n\n\ndef _save_state(cur, client_id: int, error: str, embedded: int, reused: int,\n                model: str, dims: int) -> None:\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(STATE_TABLE) +\n        \" (client_id, last_sync_at, last_error, last_embedded, last_reused,\"\n        \" model, dims, updated_at) VALUES (%s, NOW(), %s, %s, %s, %s, %s, NOW())\"\n        \" ON CONFLICT (client_id) DO UPDATE SET last_sync_at = NOW(),\"\n        \" last_error = EXCLUDED.last_error,\"\n        \" last_embedded = EXCLUDED.last_embedded,\"\n        \" last_reused = EXCLUDED.last_reused, model = EXCLUDED.model,\"\n        \" dims = EXCLUDED.dims, updated_at = NOW()\",\n        (client_id, str(error or \"\")[:300], int(embedded), int(reused),\n         model, int(dims)),\n    )\n\n\ndef sync(cur, client_id: int, budget: Optional[int] = None,\n         cfg: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:\n    \"\"\"Bring the tenant's vectors in line with its published knowledge.\n\n    Reuses vectors by content hash (re-index / rollback cost nothing),\n    embeds up to ``budget`` changed items in provider batches, drops\n    vectors of deleted/unpublished/inactive items, records the outcome.\n    Returns {ok, embedded, reused, removed, pending, error}.\"\"\"\n    cfg = cfg or config()\n    out = {\"ok\": False, \"embedded\": 0, \"reused\": 0, \"removed\": 0,\n           \"pending\": 0, \"error\": \"\"}\n    if not cfg.get(\"active\"):\n        out[\"error\"] = \"not_active:\" + str(cfg.get(\"reason\") or \"\")\n        return out\n    import portal_llm\n\n    _ensure_ddl(cur)\n    model = str(cfg.get(\"model\") or \"\")\n    dims = int(cfg.get(\"dimensions\") or 0)\n    items = _current_items(cur, client_id)\n    existing = _existing(cur, client_id)\n    todo: List[Tuple[Dict[str, Any], str, str]] = []\n    keep: List[Tuple[str, int]] = []\n    for item in items:\n        key = (str(item.get(\"kind\") or \"\"), int(item.get(\"id\") or 0))\n        keep.append(key)\n        text = item_text(item)\n        if not text.strip():\n            continue\n        digest = content_hash(text)\n        have = existing.get(key)\n        if (have and str(have.get(\"content_hash\") or \"\") == digest\n                and str(have.get(\"model\") or \"\") == model\n                and int(have.get(\"dims\") or 0) == dims):\n            continue\n        todo.append((item, text, digest))\n    reuse = _reusable(cur, client_id, model, dims,\n                      sorted({d for _i, _t, d in todo}))\n    fresh: List[Tuple[Dict[str, Any], str, str]] = []\n    for item, text, digest in todo:\n        if digest in reuse:\n            _upsert(cur, client_id, item, digest, model, dims, reuse[digest])\n            out[\"reused\"] += 1\n        else:\n            fresh.append((item, text, digest))\n    limit = SYNC_BUDGET if budget is None else max(0, int(budget))\n    batch_size = portal_llm.EMBED_MAX_INPUTS\n    error = \"\"\n    done = 0\n    for start in range(0, min(len(fresh), limit), batch_size):\n        batch = fresh[start:min(start + batch_size, limit)]\n        vectors, error = _embed([t for _i, t, _d in batch], cfg, client_id,\n                                cur)\n        if not vectors:\n            if error and \"blocked by the platform\" not in error:\n                _trip(error)\n            break\n        _heal()\n        for (item, _text, digest), vector in zip(batch, vectors):\n            _upsert(cur, client_id, item, digest, model, dims, vector)\n        done += len(batch)\n    out[\"embedded\"] = done\n    out[\"pending\"] = max(0, len(fresh) - done)\n    out[\"removed\"] = _delete_stale(cur, client_id, keep)\n    out[\"error\"] = error\n    out[\"ok\"] = not error\n    _save_state(cur, client_id, error, done, out[\"reused\"], model, dims)\n    invalidate(client_id)\n    if done or out[\"reused\"] or out[\"removed\"]:\n        try:\n            portal_db.log_action(\n                cur, client_id, \"kb.semantic_synced\", \"system\", None, None,\n                \"Semantic index: \" + str(done) + \" embedded, \"\n                + str(out[\"reused\"]) + \" reused, \" + str(out[\"removed\"])\n                + \" removed\" + (\", \" + str(out[\"pending\"]) + \" pending\"\n                                if out[\"pending\"] else \"\"))\n        except Exception:\n            pass\n    return out\n\n\ndef status(cur, client_id: int) -> Dict[str, Any]:\n    \"\"\"Owner-facing index health (no secrets).\"\"\"\n    cfg = config()\n    _ensure_ddl(cur)\n    model = str(cfg.get(\"model\") or \"\")\n    dims = int(cfg.get(\"dimensions\") or 0)\n    cur.execute(\n        \"SELECT (SELECT COUNT(*) FROM \" + portal_db._q(CHUNKS_TABLE) +\n        \" c JOIN \" + portal_db._q(SOURCES_TABLE) +\n        \" s ON s.id = c.source_id AND s.client_id = c.client_id\"\n        \" WHERE c.client_id = %s AND s.status = 'published') AS chunks,\"\n        \" (SELECT COUNT(*) FROM \" + portal_db._q(ENTRIES_TABLE) +\n        \" WHERE client_id = %s AND is_active IS TRUE) AS entries,\"\n        \" (SELECT COUNT(*) FROM \" + portal_db._q(EMB_TABLE) +\n        \" WHERE client_id = %s AND model = %s AND dims = %s) AS indexed\",\n        (client_id, client_id, client_id, model, dims),\n    )\n    counts = (portal_db.rows(cur) or [{}])[0]\n    cur.execute(\n        \"SELECT last_sync_at, last_error, last_embedded, last_reused FROM \"\n        + portal_db._q(STATE_TABLE) + \" WHERE client_id = %s\",\n        (client_id,),\n    )\n    state = (portal_db.rows(cur) or [{}])[0]\n    total = int(counts.get(\"chunks\") or 0) + int(counts.get(\"entries\") or 0)\n    indexed = min(int(counts.get(\"indexed\") or 0), total) if total else 0\n    stamp = state.get(\"last_sync_at\")\n    return {\n        \"active\": bool(cfg.get(\"active\")),\n        \"reason\": str(cfg.get(\"reason\") or \"\"),\n        \"mode\": str(cfg.get(\"mode\") or \"on\"),\n        \"model\": model,\n        \"dimensions\": dims,\n        \"min_similarity\": float(cfg.get(\"min_similarity\") or 0.0),\n        \"key_source\": str(cfg.get(\"key_source\") or \"none\"),\n        \"total\": total,\n        \"indexed\": indexed,\n        \"pending\": max(0, total - indexed),\n        \"coverage\": round(indexed / float(total), 4) if total else 0.0,\n        \"running\": int(client_id) in _RUNNING,\n        \"provider_cooldown\": _provider_down(),\n        \"last_sync_at\": stamp.isoformat() if hasattr(stamp, \"isoformat\")\n        else (str(stamp) if stamp else None),\n        \"last_error\": str(state.get(\"last_error\") or \"\"),\n        \"last_embedded\": int(state.get(\"last_embedded\") or 0),\n        \"last_reused\": int(state.get(\"last_reused\") or 0),\n    }\n\n\ndef _sync_job(client_id: int, rounds: int) -> None:\n    try:\n        for _ in range(max(1, rounds)):\n            conn = portal_db._conn()\n            try:\n                with conn.cursor() as cur:\n                    result = sync(cur, client_id)\n                conn.commit()\n            finally:\n                conn.close()\n            if not result.get(\"pending\") or result.get(\"error\"):\n                break\n    except Exception as error:\n        logger.info(\"semantic sync failed client=%s: %s\", client_id, error)\n    finally:\n        with _LOCK:\n            _RUNNING.discard(int(client_id))\n\n\ndef kick(client_id: int, reason: str = \"edit\", rounds: int = 3) -> bool:\n    \"\"\"Run a sync on a daemon thread after the caller's commit. One job per\n    tenant per process; ``tick`` kicks are throttled to TICK_SECONDS.\n    Returns True when a job was started. Never raises.\"\"\"\n    try:\n        client_id = int(client_id or 0)\n        if client_id <= 0 or not config().get(\"active\"):\n            return False\n        now = time.monotonic()\n        with _LOCK:\n            if client_id in _RUNNING:\n                return False\n            if reason == \"tick\" and now - _LAST_KICK.get(client_id, -1e9) \\\n                    < TICK_SECONDS:\n                return False\n            if reason == \"tick\" and _provider_down():\n                return False\n            _RUNNING.add(client_id)\n            _LAST_KICK[client_id] = now\n        threading.Thread(target=_sync_job, args=(client_id, rounds),\n                         daemon=True,\n                         name=\"of-kb-embed-\" + str(client_id)).start()\n        return True\n    except Exception as error:\n        with _LOCK:\n            _RUNNING.discard(int(client_id or 0))\n        logger.info(\"semantic kick skipped: %s\", error)\n        return False\n\n\n# ---------------------------------------------------------------------------\n# HTTP\n# ---------------------------------------------------------------------------\n\ndef _principal():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    return principal, None\n\n\ndef _status_response(client_id: int, started: bool = False):\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            payload = status(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    if started:\n        payload[\"running\"] = True\n    payload[\"started\"] = started\n    return jsonify(payload), 200\n\n\n@bp.get(\"/kb/semantic\")\ndef get_semantic_status():\n    principal, error = _principal()\n    if error:\n        return error\n    try:\n        return _status_response(int(principal.get(\"client_id\") or 0))\n    except Exception as problem:\n        return jsonify(portal_db.portal_unavailable(\n            problem, \"knowledge semantic index\")[0]), 503\n\n\n@bp.post(\"/kb/semantic/sync\")\ndef post_semantic_sync():\n    \"\"\"Owner \"Build index now\": starts a background sync (the website\n    request budget is short) and returns the current status.\"\"\"\n    principal, error = _principal()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    client_id = int(principal.get(\"client_id\") or 0)\n    cfg = config()\n    if not cfg.get(\"active\"):\n        return jsonify({\"error\": {\n            \"code\": \"not_configured\",\n            \"message\": (\"Semantic search is switched off by the platform.\"\n                        if cfg.get(\"reason\") == \"off\" else\n                        \"Semantic search needs an AI key with embeddings.\"\n                        \" Ask the platform admin to configure it.\"),\n        }}), 409\n    rounds = 1 if str(request.args.get(\"once\") or \"\") == \"1\" else 10\n    started = kick(client_id, \"manual\", rounds=rounds)\n    try:\n        return _status_response(client_id, started)\n    except Exception as problem:\n        return jsonify(portal_db.portal_unavailable(\n            problem, \"knowledge semantic index\")[0]), 503\n\n\ndef kick_after_mutation(response):\n    \"\"\"after_request hook for the knowledge blueprints: a successful owner\n    write (source/entry create, edit, publish, pause, delete, re-index,\n    rollback) schedules a background sync. Never alters the response.\"\"\"\n    try:\n        if request.method in (\"GET\", \"HEAD\", \"OPTIONS\"):\n            return response\n        if int(getattr(response, \"status_code\", 500)) >= 400:\n            return response\n        if not config().get(\"active\"):\n            return response\n        principal = authenticate_portal_request()\n        if principal:\n            kick(int(principal.get(\"client_id\") or 0), \"edit\")\n    except Exception:\n        pass\n    return response\n");
writeNewRepair("omniflow-backend-patch/portal_knowledge.py", "SEMANTIC_KEYWORD_POOL = _env_int(\"OF_KB_HYBRID_KEYWORD_POOL\", 12, 1, 100)", false,
    "\"\"\"Knowledge engine (MASTER-UPGRADE engine 4): document / page ingestion,\ndeterministic chunking, versioning, health and keyword retrieval for the\nAI. D1 (delivered \u00a7211): ``portal_kb_semantic`` plugs meaning-based\nrecall into ``retrieve`` below (hybrid keyword + embeddings, reciprocal\nrank fusion) without changing the retrieval contract; keyword-only is\nthe automatic fallback.\n\nAudit-first (what already existed and stays):\n\n* ``portal_kb_entries`` (portal_kb) - owner-written Q&A answers with\n  trigger keywords. They still power the instant auto-reply on the\n  ingest path and the assist panel, untouched. Retrieval here searches\n  them TOGETHER with the new document chunks so the brain sees one\n  ranked knowledge list.\n* ``portal_kb_gaps`` (portal_growth) - unanswered questions; unchanged.\n* The KB auto-publish LOCK (owner law): nothing ingested here is ever\n  used by the AI until the owner publishes the source. New sources start\n  as ``draft``; ``published`` sources feed retrieval; ``paused`` sources\n  are kept but silent.\n\nSources (``portal_kb_sources``) are pasted text, uploaded text files\n(the browser reads .txt/.md/.csv/.json/.html and posts the text) or web\npages (fetched server-side with an SSRF guard). Every ingest writes a\nnew version snapshot (``portal_kb_source_versions``, raw text kept so a\nversion can be rolled back or re-chunked) and replaces the source's\nchunks (``portal_kb_chunks``). Retrieval is a single tenant-scoped SQL\ncandidate fetch (ILIKE on the query tokens) plus a deterministic\nBM25-style ranking in Python: term frequency, inverse candidate\nfrequency, heading/title boosts, phrase bonus and query coverage. Every\nhit carries a citation (source title + section) so the brain trace can\nshow where an answer came from. Fail-soft everywhere.\n\"\"\"\n\nimport html as html_lib\nimport ipaddress\nimport logging\nimport math\nimport os\nimport re\nimport socket\nimport urllib.error\nimport urllib.parse\nimport urllib.request\nfrom datetime import datetime, timedelta, timezone\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n    ensure_human_principal,\n)\n\nlogger = logging.getLogger(\"omniflow.portal-knowledge\")\n\nbp = Blueprint(\"portal_knowledge\", __name__, url_prefix=\"/api/v1/portal\")\n\nSOURCES_TABLE = \"portal_kb_sources\"\nVERSIONS_TABLE = \"portal_kb_source_versions\"\nCHUNKS_TABLE = \"portal_kb_chunks\"\nENTRIES_TABLE = \"portal_kb_entries\"\n\nKINDS: Tuple[str, ...] = (\"text\", \"file\", \"url\")\nSTATUSES: Tuple[str, ...] = (\"draft\", \"published\", \"paused\")\n\n\ndef _env_int(name: str, default: int, lo: int, hi: int) -> int:\n    try:\n        value = int(os.environ.get(name, \"\") or default)\n    except Exception:\n        value = default\n    return max(lo, min(hi, value))\n\n\nMAX_SOURCES = _env_int(\"OF_KB_SOURCES_MAX\", 50, 1, 1000)\nMAX_SOURCE_CHARS = _env_int(\"OF_KB_SOURCE_CHARS_MAX\", 200000, 1000, 2000000)\nCHUNK_CHARS = _env_int(\"OF_KB_CHUNK_CHARS\", 700, 200, 4000)\nCHUNK_OVERLAP = _env_int(\"OF_KB_CHUNK_OVERLAP\", 80, 0, 400)\nMAX_VERSIONS = _env_int(\"OF_KB_VERSIONS_MAX\", 10, 1, 100)\nURL_TIMEOUT = _env_int(\"OF_KB_URL_TIMEOUT\", 8, 2, 60)\nURL_BYTES_MAX = _env_int(\"OF_KB_URL_BYTES_MAX\", 1500000, 10000, 20000000)\nURL_STALE_DAYS = _env_int(\"OF_KB_URL_STALE_DAYS\", 30, 1, 365)\nRETRIEVE_CANDIDATES = _env_int(\"OF_KB_RETRIEVE_CANDIDATES\", 200, 10, 2000)\nQUERY_TOKENS_MAX = _env_int(\"OF_KB_QUERY_TOKENS_MAX\", 12, 3, 32)\nMAX_TITLE_CHARS = 120\nMAX_HEADING_CHARS = 160\nSNIPPET_CHARS = 400\nMIN_CHUNK_CHARS = 20\nINSERT_BATCH = 200\n\n_DDL_READY = False\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_kb_sources (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  title TEXT NOT NULL DEFAULT '',\n  kind TEXT NOT NULL DEFAULT 'text',\n  origin TEXT NOT NULL DEFAULT '',\n  status TEXT NOT NULL DEFAULT 'draft',\n  version INT NOT NULL DEFAULT 0,\n  chunk_count INT NOT NULL DEFAULT 0,\n  char_count INT NOT NULL DEFAULT 0,\n  last_error TEXT NOT NULL DEFAULT '',\n  ingested_at TIMESTAMPTZ,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_kb_sources_client\n  ON portal_kb_sources (client_id, status);\nCREATE TABLE IF NOT EXISTS portal_kb_source_versions (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  source_id BIGINT NOT NULL,\n  version INT NOT NULL,\n  content TEXT NOT NULL DEFAULT '',\n  chunk_count INT NOT NULL DEFAULT 0,\n  char_count INT NOT NULL DEFAULT 0,\n  note TEXT NOT NULL DEFAULT '',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_kb_source_versions_source\n  ON portal_kb_source_versions (client_id, source_id, version DESC);\nCREATE TABLE IF NOT EXISTS portal_kb_chunks (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  source_id BIGINT NOT NULL,\n  version INT NOT NULL DEFAULT 1,\n  position INT NOT NULL DEFAULT 0,\n  heading TEXT NOT NULL DEFAULT '',\n  content TEXT NOT NULL DEFAULT '',\n  char_count INT NOT NULL DEFAULT 0,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_kb_chunks_source\n  ON portal_kb_chunks (client_id, source_id, position);\n\"\"\"\n\n\ndef _ensure_ddl(cur) -> None:\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_DDL)\n    _DDL_READY = True\n\n\n# ---------------------------------------------------------------------------\n# Pure text helpers: normalisation, tokens, HTML, chunking, ranking\n# ---------------------------------------------------------------------------\n\n#: Function words that carry no retrieval signal (English + Roman Urdu).\nSTOPWORDS = frozenset(\"\"\"\na an the is are am was were be been being of to in on at for and or but if\nthen than so as by with from into onto about over under up down out off this\nthat these those it its i me my we our you your he she they them their his\nher what which who whom whose when where why how do does did done have has\nhad having can could will would shall should may might must not no yes ok\nokay please plz pls hi hello hey thanks thank\nka ki ke ko ki se me mein main hai hain he hen ho hoon hun hu tha thi the\nthay thi ye yeh wo woh is us un in ab aur or ya bhi to per par pe ap aap tum\nmera meri mere hamara hamari apna apni apne kya kia kyun kyu kaise kaisa\nkaisi kab kahan kon konsa kar karo karen karein kro krna karna kiya raha\nrahi rahe hoga hogi honge chahiye chaiye bhai ji han haan nahi nhi na\n\"\"\".split())\n\n_WORD_RE = re.compile(r\"\\w+\", re.UNICODE)\n_BLANK_RE = re.compile(r\"\\n\\s*\\n\")\n_SENTENCE_RE = re.compile(r\"(?<=[.!?\\u06d4])\\s+\")\n_HEADING_RE = re.compile(r\"^(#{1,6}\\s+|\\d+(\\.\\d+)*[.)]\\s+)\")\n\n\ndef normalize(text: Any) -> str:\n    return re.sub(r\"\\s+\", \" \", str(text or \"\").lower()).strip()\n\n\ndef _collapse(text: Any) -> str:\n    \"\"\"Whitespace-collapsed but case-preserving (titles and headings are\n    shown to the owner; matching lower-cases separately).\"\"\"\n    return re.sub(r\"\\s+\", \" \", str(text or \"\")).strip()\n\n\ndef words(text: Any) -> List[str]:\n    return [w for w in _WORD_RE.findall(str(text or \"\").lower())]\n\n\ndef tokenize(text: Any, limit: int = 0, keep_stopwords: bool = False) -> List[str]:\n    \"\"\"Unique retrieval tokens in order of appearance (stop words and\n    one-character fragments dropped). ``limit`` keeps the longest tokens\n    first so the SQL candidate fetch uses the most selective ones.\"\"\"\n    seen: List[str] = []\n    for word in words(text):\n        if len(word) < 2:\n            continue\n        if not keep_stopwords and word in STOPWORDS:\n            continue\n        if word not in seen:\n            seen.append(word)\n    if limit and len(seen) > limit:\n        seen = sorted(seen, key=lambda w: (-len(w), seen.index(w)))[:limit]\n    return seen\n\n\ndef query_tokens(text: Any) -> List[str]:\n    \"\"\"Tokens for a customer question; falls back to stop words when the\n    question is made of them only (\\\"kya hai\\\") so short questions still\n    get a candidate fetch.\"\"\"\n    tokens = tokenize(text, QUERY_TOKENS_MAX)\n    if not tokens:\n        tokens = tokenize(text, QUERY_TOKENS_MAX, keep_stopwords=True)\n    return tokens\n\n\n_TAG_RE = re.compile(r\"<[^>]+>\")\n_DROP_RE = re.compile(\n    r\"<(script|style|noscript|svg|head|template|iframe)[^>]*>.*?</\\1\\s*>\",\n    re.IGNORECASE | re.DOTALL)\n_COMMENT_RE = re.compile(r\"<!--.*?-->\", re.DOTALL)\n_BLOCK_RE = re.compile(\n    r\"</?(p|div|br|li|ul|ol|tr|td|th|table|section|article|header|footer|\"\n    r\"h[1-6]|blockquote|pre|hr|dd|dt|dl|nav|main|aside|figure|figcaption)\"\n    r\"[^>]*>\", re.IGNORECASE)\n_HEAD_TAG_RE = re.compile(r\"<h([1-6])[^>]*>(.*?)</h\\1\\s*>\",\n                          re.IGNORECASE | re.DOTALL)\n_TITLE_RE = re.compile(r\"<title[^>]*>(.*?)</title>\", re.IGNORECASE | re.DOTALL)\n\n\ndef html_title(markup: str) -> str:\n    match = _TITLE_RE.search(str(markup or \"\"))\n    if not match:\n        return \"\"\n    return _collapse(html_lib.unescape(_TAG_RE.sub(\" \", match.group(1))))[\n        :MAX_TITLE_CHARS]\n\n\ndef html_to_text(markup: str) -> str:\n    \"\"\"Readable text from HTML: scripts/styles/head dropped, headings kept\n    as markdown-style lines (so chunking can carry them), block tags become\n    paragraph breaks, entities unescaped, whitespace collapsed.\"\"\"\n    text = str(markup or \"\")\n    text = _COMMENT_RE.sub(\" \", text)\n    text = _DROP_RE.sub(\" \", text)\n    text = _HEAD_TAG_RE.sub(\n        lambda m: \"\\n\\n\" + \"#\" * int(m.group(1)) + \" \"\n        + _TAG_RE.sub(\" \", m.group(2)).strip() + \"\\n\\n\", text)\n    text = _BLOCK_RE.sub(\"\\n\\n\", text)\n    text = _TAG_RE.sub(\" \", text)\n    text = html_lib.unescape(text)\n    text = text.replace(\"\\xa0\", \" \")\n    lines = [re.sub(r\"[ \\t]+\", \" \", line).strip() for line in text.split(\"\\n\")]\n    out: List[str] = []\n    blank = False\n    for line in lines:\n        if line:\n            out.append(line)\n            blank = False\n        elif not blank and out:\n            out.append(\"\")\n            blank = True\n    return \"\\n\".join(out).strip()\n\n\ndef clean_text(text: Any) -> str:\n    \"\"\"Normalise pasted / uploaded text: CRLF, tabs, trailing spaces, at\n    most one blank line in a row.\"\"\"\n    value = str(text or \"\").replace(\"\\r\\n\", \"\\n\").replace(\"\\r\", \"\\n\")\n    value = value.replace(\"\\t\", \" \").replace(\"\\x00\", \"\")\n    lines = [re.sub(r\"[ ]+\", \" \", line).rstrip() for line in value.split(\"\\n\")]\n    out: List[str] = []\n    blank = False\n    for line in lines:\n        if line.strip():\n            out.append(line)\n            blank = False\n        elif not blank and out:\n            out.append(\"\")\n            blank = True\n    return \"\\n\".join(out).strip()\n\n\ndef _is_heading(block: str) -> bool:\n    if \"\\n\" in block or len(block) > 80:\n        return False\n    if _HEADING_RE.match(block):\n        return True\n    stripped = block.rstrip(\":\").strip()\n    if block.endswith(\":\") and len(stripped.split()) <= 8:\n        return True\n    letters = [c for c in stripped if c.isalpha()]\n    return bool(letters) and len(stripped.split()) <= 6 and all(\n        c.isupper() for c in letters)\n\n\ndef _heading_text(block: str) -> str:\n    return _collapse(_HEADING_RE.sub(\"\", block).rstrip(\":\"))[:MAX_HEADING_CHARS]\n\n\ndef _split_heading(block: str) -> Tuple[str, str]:\n    \"\"\"(heading, body) for a block whose first line is a heading and the\n    rest a paragraph (\"Returns\\nItems can be returned...\"); (\"\", block)\n    otherwise. A first line counts as a heading when it is short, has no\n    sentence punctuation and the line after it is longer.\"\"\"\n    if \"\\n\" not in block:\n        return \"\", block\n    first, rest = block.split(\"\\n\", 1)\n    first, rest = first.strip(), rest.strip()\n    if not first or not rest:\n        return \"\", block\n    if _is_heading(first):\n        return _heading_text(first), rest\n    if (len(first) <= 60 and len(first.split()) <= 8\n            and not first.endswith((\".\", \"!\", \"?\", \",\", \";\"))\n            and len(rest.split(\"\\n\", 1)[0]) > len(first)):\n        return _heading_text(first), rest\n    return \"\", block\n\n\ndef _split_long(block: str, size: int) -> List[str]:\n    \"\"\"A block bigger than one chunk: pack sentences up to ``size``; a\n    single sentence longer than that is cut at its last space.\"\"\"\n    pieces: List[str] = []\n    current = \"\"\n    for sentence in _SENTENCE_RE.split(block):\n        sentence = sentence.strip()\n        if not sentence:\n            continue\n        parts: List[str] = []\n        while len(sentence) > size:\n            cut = sentence.rfind(\" \", 0, size)\n            if cut < size // 2:\n                cut = size\n            parts.append(sentence[:cut].strip())\n            sentence = sentence[cut:].strip()\n        if sentence:\n            parts.append(sentence)\n        for part in parts:\n            if current and len(current) + len(part) + 1 > size:\n                pieces.append(current)\n                current = part\n            else:\n                current = (current + \" \" + part).strip()\n    if current:\n        pieces.append(current)\n    return pieces\n\n\ndef _overlap_tail(text: str, overlap: int) -> str:\n    if overlap <= 0 or len(text) <= overlap:\n        return \"\"\n    tail = text[-overlap:]\n    cut = tail.find(\" \")\n    return tail[cut + 1:].strip() if cut >= 0 else tail.strip()\n\n\ndef chunk_text(text: str, size: int = 0,\n               overlap: Optional[int] = None) -> List[Dict[str, Any]]:\n    \"\"\"Deterministic, heading-aware chunks: paragraphs are packed up to\n    ``size`` characters, headings label the chunks that follow them, over-\n    long paragraphs split at sentence boundaries, and each chunk starts\n    with a short overlap from the previous one so context is not cut.\"\"\"\n    size = size or CHUNK_CHARS\n    overlap = CHUNK_OVERLAP if overlap is None else max(0, overlap)\n    overlap = min(overlap, size // 3)\n    blocks = [b.strip() for b in _BLANK_RE.split(clean_text(text)) if b.strip()]\n    chunks: List[Dict[str, Any]] = []\n    heading = \"\"\n    current = \"\"\n    current_heading = \"\"\n    previous_text = \"\"\n\n    def flush() -> None:\n        nonlocal current, previous_text\n        body = current.strip()\n        if body:\n            chunks.append({\"position\": len(chunks),\n                           \"heading\": current_heading, \"content\": body})\n            previous_text = body\n        current = \"\"\n\n    for block in blocks:\n        if _is_heading(block):\n            flush()\n            previous_text = \"\"  # no overlap across sections\n            heading = _heading_text(block)\n            continue\n        inline_heading, block = _split_heading(block)\n        if inline_heading:\n            flush()\n            previous_text = \"\"\n            heading = inline_heading\n        # long paragraphs are packed a little below ``size`` so the overlap\n        # carried in from the previous chunk still fits\n        pieces = [block] if len(block) <= size else _split_long(\n            block, max(size // 2, size - overlap))\n        for piece in pieces:\n            if current and len(current) + len(piece) + 2 > size:\n                flush()\n            if not current:\n                current_heading = heading\n                tail = _overlap_tail(previous_text, overlap)\n                current = (tail + \" \" + piece).strip() if tail and len(\n                    tail) + len(piece) + 1 <= size else piece\n            else:\n                current = current + \"\\n\\n\" + piece\n    flush()\n    if len(chunks) > 1:\n        chunks = [c for c in chunks if len(c[\"content\"]) >= MIN_CHUNK_CHARS]\n        for index, chunk in enumerate(chunks):\n            chunk[\"position\"] = index\n    return chunks\n\n\ndef _matches(word: str, token: str) -> bool:\n    \"\"\"Exact match, or a prefix match once the token is long enough to be\n    a stem (return -> returned/returns, deliver -> delivery). Short Roman\n    Urdu words (din, kab) stay exact.\"\"\"\n    if word == token:\n        return True\n    if len(token) >= 4 and word.startswith(token):\n        return True\n    return len(word) >= 4 and token.startswith(word) and len(token) - len(word) <= 3\n\n\ndef _count(token: str, word_list: List[str]) -> int:\n    return sum(1 for w in word_list if _matches(w, token))\n\n\ndef score_candidates(tokens: List[str], candidates: List[Dict[str, Any]],\n                     n: int) -> List[Dict[str, Any]]:\n    \"\"\"BM25-style ranking without an index: per-token tf saturation,\n    inverse candidate frequency, title/heading boost, adjacent-token phrase\n    bonus and query coverage. Deterministic; ties break on shorter text\n    then id.\"\"\"\n    if not tokens or not candidates:\n        return []\n    prepared = []\n    for row in candidates:\n        title_words = words(row.get(\"title\"))\n        body_words = words(row.get(\"content\")) + words(row.get(\"extra\"))\n        title_hits = {t: _count(t, title_words) for t in tokens}\n        body_hits = {t: _count(t, body_words) for t in tokens}\n        prepared.append((row, title_words, body_words, title_hits, body_hits))\n    total = len(prepared)\n    df = {t: sum(1 for p in prepared if p[3][t] or p[4][t]) for t in tokens}\n    idf = {t: math.log(1.0 + total / (1.0 + df[t])) + 0.1 for t in tokens}\n    ranked = []\n    for row, title_words, body_words, title_hits, body_hits in prepared:\n        matched: List[str] = []\n        score = 0.0\n        for token in tokens:\n            tf = body_hits[token]\n            in_title = title_hits[token] > 0\n            if not tf and not in_title:\n                continue\n            matched.append(token)\n            weight = (1.0 + math.log(1.0 + tf)) if tf else 0.6\n            if in_title:\n                weight += 1.5\n            score += weight * idf[token]\n        if not matched:\n            continue\n        if len(tokens) > 1:\n            text_words = title_words + body_words\n            for a, b in zip(tokens, tokens[1:]):\n                for i in range(len(text_words) - 1):\n                    if _matches(text_words[i], a) and _matches(text_words[i + 1], b):\n                        score += 1.0\n                        break\n        coverage = len(matched) / float(len(tokens))\n        score *= 0.5 + 0.5 * coverage\n        ranked.append((round(score, 4), matched, row))\n    ranked.sort(key=lambda item: (-item[0], len(str(item[2].get(\"content\") or \"\")),\n                                  int(item[2].get(\"id\") or 0)))\n    hits = []\n    for score, matched, row in ranked[:max(1, n)]:\n        content = str(row.get(\"content\") or \"\")\n        hits.append({\n            \"kind\": str(row.get(\"kind\") or \"entry\"),\n            \"id\": int(row.get(\"id\") or 0),\n            \"title\": str(row.get(\"title\") or \"\"),\n            \"content\": content[:SNIPPET_CHARS],\n            \"source_id\": int(row.get(\"source_id\") or 0),\n            \"source\": str(row.get(\"source_title\") or \"\"),\n            \"position\": int(row.get(\"position\") or 0),\n            \"score\": score,\n            \"matched\": matched,\n        })\n    return hits\n\n\n# ---------------------------------------------------------------------------\n# URL fetch with SSRF guard\n# ---------------------------------------------------------------------------\n\ndef assert_public_url(url: str, resolver=None) -> Tuple[str, str]:\n    \"\"\"Validate an owner-supplied URL: http(s) only, a real host name, no\n    credentials, and every resolved address public (no loopback, private,\n    link-local, multicast or reserved ranges). Returns (scheme, host).\n    Raises ValueError with an owner-readable message.\"\"\"\n    parsed = urllib.parse.urlsplit(str(url or \"\").strip())\n    if parsed.scheme not in (\"http\", \"https\"):\n        raise ValueError(\"Only http and https links are supported.\")\n    host = (parsed.hostname or \"\").strip().lower().rstrip(\".\")\n    if not host or parsed.username or parsed.password:\n        raise ValueError(\"That link is not a valid web address.\")\n    if host == \"localhost\" or host.endswith(\".localhost\") or host.endswith(\n            \".local\") or host.endswith(\".internal\"):\n        raise ValueError(\"Internal addresses cannot be fetched.\")\n    resolve = resolver or socket.getaddrinfo\n    try:\n        infos = resolve(host, parsed.port or (443 if parsed.scheme == \"https\"\n                                                else 80))\n    except Exception:\n        raise ValueError(\"That web address could not be resolved.\")\n    addresses = []\n    for info in infos or []:\n        try:\n            addresses.append(ipaddress.ip_address(info[4][0]))\n        except Exception:\n            continue\n    if not addresses:\n        raise ValueError(\"That web address could not be resolved.\")\n    for address in addresses:\n        if (address.is_private or address.is_loopback or address.is_link_local\n                or address.is_multicast or address.is_reserved\n                or address.is_unspecified):\n            raise ValueError(\"Internal addresses cannot be fetched.\")\n    return parsed.scheme, host\n\n\nclass _SafeRedirectHandler(urllib.request.HTTPRedirectHandler):\n    \"\"\"Re-validates every redirect target (a public page may not bounce\n    the fetch onto an internal address).\"\"\"\n\n    def redirect_request(self, req, fp, code, msg, headers, newurl):\n        assert_public_url(newurl)\n        return super().redirect_request(req, fp, code, msg, headers, newurl)\n\n\ndef fetch_url(url: str) -> Tuple[str, str]:\n    \"\"\"Download a public page and return (text, title). Raises ValueError\n    with an owner-readable message on any problem.\"\"\"\n    assert_public_url(url)\n    req = urllib.request.Request(str(url).strip(), method=\"GET\")\n    req.add_header(\"Accept\", \"text/html, text/plain;q=0.9, */*;q=0.5\")\n    req.add_header(\"User-Agent\", \"OmniFlow-Knowledge/1.0 (+knowledge sources)\")\n    opener = urllib.request.build_opener(_SafeRedirectHandler())\n    try:\n        with opener.open(req, timeout=URL_TIMEOUT) as resp:\n            content_type = str(resp.headers.get(\"Content-Type\") or \"\").lower()\n            raw = resp.read(URL_BYTES_MAX + 1)\n    except urllib.error.HTTPError as error:\n        raise ValueError(\"The page answered with HTTP \" + str(error.code) + \".\")\n    except ValueError:\n        raise\n    except Exception:\n        raise ValueError(\"The page could not be fetched (timeout or \"\n                         \"connection error).\")\n    if len(raw) > URL_BYTES_MAX:\n        raise ValueError(\"The page is too large to import (limit \"\n                         + str(URL_BYTES_MAX // 1000) + \" KB).\")\n    kind = content_type.split(\";\")[0].strip()\n    if kind and not (kind.startswith(\"text/\") or kind in (\n            \"application/json\", \"application/xhtml+xml\", \"application/xml\")):\n        raise ValueError(\"Only web pages and text files can be imported \"\n                         \"from a link (got \" + kind + \").\")\n    charset = \"utf-8\"\n    match = re.search(r\"charset=([\\w-]+)\", content_type)\n    if match:\n        charset = match.group(1)\n    try:\n        body = raw.decode(charset, \"replace\")\n    except Exception:\n        body = raw.decode(\"utf-8\", \"replace\")\n    if kind in (\"text/html\", \"application/xhtml+xml\") or \"<html\" in body[:2000].lower():\n        return html_to_text(body), html_title(body)\n    return clean_text(body), \"\"\n\n\n# ---------------------------------------------------------------------------\n# DB helpers\n# ---------------------------------------------------------------------------\n\nSOURCE_COLS = (\"id, client_id, title, kind, origin, status, version, chunk_count,\"\n               \" char_count, last_error, ingested_at, created_at, updated_at\")\n\n\ndef _iso(value: Any) -> Optional[str]:\n    if value is None or value == \"\":\n        return None\n    if hasattr(value, \"isoformat\"):\n        return value.isoformat()\n    return str(value)\n\n\ndef _is_stale(row: Dict[str, Any]) -> bool:\n    if str(row.get(\"kind\") or \"\") != \"url\":\n        return False\n    stamp = row.get(\"ingested_at\")\n    if not isinstance(stamp, datetime):\n        return False\n    if stamp.tzinfo is None:\n        stamp = stamp.replace(tzinfo=timezone.utc)\n    return stamp < datetime.now(timezone.utc) - timedelta(days=URL_STALE_DAYS)\n\n\ndef source_public(row: Dict[str, Any]) -> Dict[str, Any]:\n    return {\n        \"id\": int(row.get(\"id\") or 0),\n        \"title\": str(row.get(\"title\") or \"\"),\n        \"kind\": str(row.get(\"kind\") or \"text\"),\n        \"origin\": str(row.get(\"origin\") or \"\"),\n        \"status\": str(row.get(\"status\") or \"draft\"),\n        \"version\": int(row.get(\"version\") or 0),\n        \"chunk_count\": int(row.get(\"chunk_count\") or 0),\n        \"char_count\": int(row.get(\"char_count\") or 0),\n        \"last_error\": str(row.get(\"last_error\") or \"\"),\n        \"stale\": _is_stale(row),\n        \"ingested_at\": _iso(row.get(\"ingested_at\")),\n        \"created_at\": _iso(row.get(\"created_at\")),\n        \"updated_at\": _iso(row.get(\"updated_at\")),\n    }\n\n\ndef get_source(cur, client_id: int, source_id: int) -> Optional[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT \" + SOURCE_COLS + \" FROM \" + portal_db._q(SOURCES_TABLE) +\n        \" WHERE id = %s AND client_id = %s\",\n        (int(source_id), client_id),\n    )\n    rows = portal_db.rows(cur)\n    return rows[0] if rows else None\n\n\ndef list_sources(cur, client_id: int) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT \" + SOURCE_COLS + \" FROM \" + portal_db._q(SOURCES_TABLE) +\n        \" WHERE client_id = %s ORDER BY updated_at DESC, id DESC LIMIT %s\",\n        (client_id, MAX_SOURCES + 50),\n    )\n    return portal_db.rows(cur)\n\n\ndef health(sources: List[Dict[str, Any]]) -> Dict[str, Any]:\n    out = {\"sources\": len(sources), \"published\": 0, \"drafts\": 0, \"paused\": 0,\n           \"chunks\": 0, \"errors\": 0, \"stale\": 0}\n    for row in sources:\n        status = str(row.get(\"status\") or \"draft\")\n        if status == \"published\":\n            out[\"published\"] += 1\n            out[\"chunks\"] += int(row.get(\"chunk_count\") or 0)\n        elif status == \"paused\":\n            out[\"paused\"] += 1\n        else:\n            out[\"drafts\"] += 1\n        if str(row.get(\"last_error\") or \"\"):\n            out[\"errors\"] += 1\n        if _is_stale(row):\n            out[\"stale\"] += 1\n    return out\n\n\ndef ingest(cur, client_id: int, source: Dict[str, Any], text: str,\n           note: str = \"\", actor_user_id: Optional[int] = None) -> Dict[str, Any]:\n    \"\"\"Chunk ``text`` for ``source``: replace its chunks, snapshot the raw\n    text as the next version, prune old versions, refresh the counters and\n    audit. Returns the updated source row. Never publishes.\"\"\"\n    source_id = int(source.get(\"id\") or 0)\n    content = clean_text(text)[:MAX_SOURCE_CHARS]\n    chunks = chunk_text(content)\n    version = int(source.get(\"version\") or 0) + 1\n    cur.execute(\n        \"DELETE FROM \" + portal_db._q(CHUNKS_TABLE) +\n        \" WHERE client_id = %s AND source_id = %s\",\n        (client_id, source_id),\n    )\n    for start in range(0, len(chunks), INSERT_BATCH):\n        batch = chunks[start:start + INSERT_BATCH]\n        values = \", \".join([\"(%s, %s, %s, %s, %s, %s, %s)\"] * len(batch))\n        params: List[Any] = []\n        for chunk in batch:\n            params.extend([client_id, source_id, version, chunk[\"position\"],\n                           chunk[\"heading\"], chunk[\"content\"],\n                           len(chunk[\"content\"])])\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(CHUNKS_TABLE) +\n            \" (client_id, source_id, version, position, heading, content,\"\n            \" char_count) VALUES \" + values,\n            tuple(params),\n        )\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(VERSIONS_TABLE) +\n        \" (client_id, source_id, version, content, chunk_count, char_count,\"\n        \" note) VALUES (%s, %s, %s, %s, %s, %s, %s)\",\n        (client_id, source_id, version, content, len(chunks), len(content),\n         str(note or \"\")[:200]),\n    )\n    cur.execute(\n        \"DELETE FROM \" + portal_db._q(VERSIONS_TABLE) +\n        \" WHERE client_id = %s AND source_id = %s AND version <= %s\",\n        (client_id, source_id, version - MAX_VERSIONS),\n    )\n    cur.execute(\n        \"UPDATE \" + portal_db._q(SOURCES_TABLE) +\n        \" SET version = %s, chunk_count = %s, char_count = %s, last_error = '',\"\n        \" ingested_at = NOW(), updated_at = NOW()\"\n        \" WHERE id = %s AND client_id = %s RETURNING \" + SOURCE_COLS,\n        (version, len(chunks), len(content), source_id, client_id),\n    )\n    rows = portal_db.rows(cur)\n    updated = rows[0] if rows else dict(source, version=version,\n                                        chunk_count=len(chunks),\n                                        char_count=len(content), last_error=\"\")\n    portal_db.log_action(\n        cur, client_id, \"kb.source_ingested\", \"customer_user\", actor_user_id,\n        None, \"Indexed '\" + str(updated.get(\"title\") or \"\")[:60] + \"' v\"\n        + str(version) + \" (\" + str(len(chunks)) + \" sections, \"\n        + str(len(content)) + \" chars)\" + (\" - \" + note if note else \"\"),\n    )\n    return updated\n\n\ndef record_error(cur, client_id: int, source_id: int, message: str) -> None:\n    cur.execute(\n        \"UPDATE \" + portal_db._q(SOURCES_TABLE) +\n        \" SET last_error = %s, updated_at = NOW()\"\n        \" WHERE id = %s AND client_id = %s\",\n        (str(message or \"\")[:300], int(source_id), client_id),\n    )\n\n\ndef version_content(cur, client_id: int, source_id: int,\n                    version: Optional[int] = None) -> Optional[Dict[str, Any]]:\n    where = \" AND version = %s\" if version else \"\"\n    params: Tuple[Any, ...] = (client_id, int(source_id)) + (\n        (int(version),) if version else ())\n    cur.execute(\n        \"SELECT version, content, chunk_count, char_count, note, created_at FROM \"\n        + portal_db._q(VERSIONS_TABLE) +\n        \" WHERE client_id = %s AND source_id = %s\" + where +\n        \" ORDER BY version DESC LIMIT 1\",\n        params,\n    )\n    rows = portal_db.rows(cur)\n    return rows[0] if rows else None\n\n\ndef list_versions(cur, client_id: int, source_id: int) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT version, chunk_count, char_count, note, created_at FROM \"\n        + portal_db._q(VERSIONS_TABLE) +\n        \" WHERE client_id = %s AND source_id = %s ORDER BY version DESC LIMIT %s\",\n        (client_id, int(source_id), MAX_VERSIONS),\n    )\n    return [{\"version\": int(r.get(\"version\") or 0),\n             \"chunk_count\": int(r.get(\"chunk_count\") or 0),\n             \"char_count\": int(r.get(\"char_count\") or 0),\n             \"note\": str(r.get(\"note\") or \"\"),\n             \"created_at\": _iso(r.get(\"created_at\"))}\n            for r in portal_db.rows(cur)]\n\n\ndef retrieve(cur, client_id: int, query: str, n: int = 5,\n             include_entries: bool = True) -> List[Dict[str, Any]]:\n    \"\"\"The one knowledge read for the brain and the owner's tester: active\n    Q&A entries + chunks of PUBLISHED sources, ranked deterministically.\n\n    Keyword ranking first (BM25-style over the query tokens); when the\n    semantic index is active and populated, meaning-based hits are fused\n    in (portal_kb_semantic.hybrid). Every hit carries ``via``\n    (keyword|semantic|both) and ``semantic`` (similarity or None).\n    Blank query -> [] without touching the DB.\"\"\"\n    if not str(query or \"\").strip():\n        return []\n    tokens = query_tokens(query)\n    keyword = _keyword_hits(cur, client_id, tokens,\n                            max(n, SEMANTIC_KEYWORD_POOL), include_entries)\n    try:\n        import portal_kb_semantic\n\n        fused = portal_kb_semantic.hybrid(cur, client_id, query, keyword, n,\n                                          include_entries, SNIPPET_CHARS)\n    except Exception as error:  # fail-soft: keyword ranking stands\n        logger.info(\"semantic retrieval skipped: %s\", error)\n        fused = None\n    if fused is not None:\n        return fused\n    out = []\n    for hit in keyword[:max(1, n)]:\n        hit[\"via\"] = \"keyword\"\n        hit[\"semantic\"] = None\n        out.append(hit)\n    return out\n\n\nSEMANTIC_KEYWORD_POOL = _env_int(\"OF_KB_HYBRID_KEYWORD_POOL\", 12, 1, 100)\n\n\ndef _keyword_hits(cur, client_id: int, tokens: List[str], n: int,\n                  include_entries: bool) -> List[Dict[str, Any]]:\n    \"\"\"Keyword candidates (ILIKE on the tokens) ranked by score_candidates.\n    No tokens -> [] without touching the DB.\"\"\"\n    if not tokens:\n        return []\n    patterns = [\"%\" + t + \"%\" for t in tokens]\n    limit = RETRIEVE_CANDIDATES\n    parts: List[str] = []\n    params: List[Any] = []\n    if include_entries:\n        parts.append(\n            \"SELECT 'entry' AS kind, e.id AS id, e.title AS title,\"\n            \" e.content AS content, e.keywords AS extra, 0 AS source_id,\"\n            \" '' AS source_title, 0 AS position FROM \"\n            + portal_db._q(ENTRIES_TABLE) + \" e\"\n            \" WHERE e.client_id = %s AND e.is_active IS TRUE\"\n            \" AND (e.title ILIKE ANY(%s) OR e.keywords ILIKE ANY(%s)\"\n            \" OR e.content ILIKE ANY(%s))\")\n        params.extend([client_id, patterns, patterns, patterns])\n    parts.append(\n        \"SELECT 'chunk' AS kind, c.id AS id, c.heading AS title,\"\n        \" c.content AS content, '' AS extra, c.source_id AS source_id,\"\n        \" s.title AS source_title, c.position AS position FROM \"\n        + portal_db._q(CHUNKS_TABLE) + \" c JOIN \" + portal_db._q(SOURCES_TABLE) +\n        \" s ON s.id = c.source_id AND s.client_id = c.client_id\"\n        \" WHERE c.client_id = %s AND s.status = 'published'\"\n        \" AND (c.heading ILIKE ANY(%s) OR c.content ILIKE ANY(%s))\")\n    params.extend([client_id, patterns, patterns])\n    params.append(limit)\n    cur.execute(\" UNION ALL \".join(parts) + \" LIMIT %s\", tuple(params))\n    return score_candidates(tokens, portal_db.rows(cur), n)\n\n\n# ---------------------------------------------------------------------------\n# HTTP\n# ---------------------------------------------------------------------------\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    return principal, None\n\n\ndef _human_or_error():\n    principal, error = _principal_or_error()\n    if error:\n        return None, error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return None, forbidden\n    return principal, None\n\n\ndef _bad(message: str, code: str = \"bad_request\", status: int = 400):\n    return jsonify({\"error\": {\"code\": code, \"message\": message}}), status\n\n\ndef _limits() -> Dict[str, Any]:\n    return {\"max_sources\": MAX_SOURCES, \"max_chars\": MAX_SOURCE_CHARS,\n            \"chunk_chars\": CHUNK_CHARS, \"max_versions\": MAX_VERSIONS,\n            \"kinds\": list(KINDS)}\n\n\ndef _title_from(text: str, fallback: str) -> str:\n    for line in str(text or \"\").split(\"\\n\"):\n        line = _HEADING_RE.sub(\"\", line).strip().strip(\"#\").strip()\n        if line:\n            return line[:MAX_TITLE_CHARS]\n    return fallback[:MAX_TITLE_CHARS]\n\n\n@bp.get(\"/kb/sources\")\ndef get_sources():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            rows = list_sources(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"sources\": [source_public(r) for r in rows],\n                    \"health\": health(rows), \"limits\": _limits()}), 200\n\n\n@bp.post(\"/kb/sources\")\ndef post_source():\n    \"\"\"Create a source and index it right away. It stays a DRAFT until the\n    owner publishes it (KB auto-publish lock).\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    kind = str(payload.get(\"kind\") or \"text\").strip().lower()\n    if kind not in KINDS:\n        return _bad(\"kind must be one of text, file, url.\")\n    title = str(payload.get(\"title\") or \"\").strip()[:MAX_TITLE_CHARS]\n    origin = \"\"\n    if kind == \"url\":\n        url = str(payload.get(\"url\") or \"\").strip()[:2000]\n        if not url:\n            return _bad(\"A web address is required.\")\n        try:\n            text, page_title = fetch_url(url)\n        except ValueError as problem:\n            return _bad(str(problem), \"fetch_failed\")\n        origin = url\n        title = title or page_title or _title_from(text, url)\n    else:\n        text = clean_text(payload.get(\"text\"))\n        origin = str(payload.get(\"filename\") or \"\").strip()[:200] if kind == \"file\" else \"\"\n        title = title or _title_from(text, origin or \"Pasted text\")\n    if len(text) < MIN_CHUNK_CHARS:\n        return _bad(\"There is not enough text to index (at least \"\n                    + str(MIN_CHUNK_CHARS) + \" characters).\")\n    if len(text) > MAX_SOURCE_CHARS:\n        return _bad(\"That source is too long (limit \"\n                    + str(MAX_SOURCE_CHARS) + \" characters). Split it into\"\n                    \" smaller documents.\", \"too_long\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"SELECT COUNT(*) AS n FROM \" + portal_db._q(SOURCES_TABLE) +\n                \" WHERE client_id = %s\",\n                (client_id,),\n            )\n            rows = portal_db.rows(cur)\n            if int((rows[0] if rows else {}).get(\"n\") or 0) >= MAX_SOURCES:\n                conn.rollback()\n                return _bad(\"This workspace already has the maximum of \"\n                            + str(MAX_SOURCES) + \" sources.\", \"limit\", 409)\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(SOURCES_TABLE) +\n                \" (client_id, title, kind, origin, status)\"\n                \" VALUES (%s, %s, %s, %s, 'draft') RETURNING \" + SOURCE_COLS,\n                (client_id, title, kind, origin),\n            )\n            rows = portal_db.rows(cur)\n            source = rows[0] if rows else {\"id\": 0, \"title\": title,\n                                           \"kind\": kind, \"version\": 0}\n            source = ingest(cur, client_id, source, text, \"created\",\n                            principal.get(\"user_id\"))\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"source\": source_public(source)}), 200\n\n\n@bp.put(\"/kb/sources/<int:source_id>\")\ndef put_source(source_id: int):\n    \"\"\"Owner review: publish / pause / back to draft, rename.\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    status = str(payload.get(\"status\") or \"\").strip().lower()\n    title = str(payload.get(\"title\") or \"\").strip()[:MAX_TITLE_CHARS]\n    if status and status not in STATUSES:\n        return _bad(\"status must be one of draft, published, paused.\")\n    if not status and not title:\n        return _bad(\"Nothing to update.\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            if status == \"published\" and int(source.get(\"chunk_count\") or 0) == 0:\n                conn.rollback()\n                return _bad(\"This source has no indexed text yet. Re-index it\"\n                            \" before publishing.\", \"empty_source\")\n            sets = [\"updated_at = NOW()\"]\n            params: List[Any] = []\n            if status:\n                sets.append(\"status = %s\")\n                params.append(status)\n            if title:\n                sets.append(\"title = %s\")\n                params.append(title)\n            params.extend([int(source_id), client_id])\n            cur.execute(\n                \"UPDATE \" + portal_db._q(SOURCES_TABLE) + \" SET \" +\n                \", \".join(sets) + \" WHERE id = %s AND client_id = %s RETURNING \"\n                + SOURCE_COLS,\n                tuple(params),\n            )\n            rows = portal_db.rows(cur)\n            updated = rows[0] if rows else dict(source)\n            if status and status != str(source.get(\"status\") or \"\"):\n                portal_db.log_action(\n                    cur, client_id, \"kb.source_\" + status, \"customer_user\",\n                    principal.get(\"user_id\"), None,\n                    (\"Published\" if status == \"published\" else\n                     \"Paused\" if status == \"paused\" else \"Unpublished\")\n                    + \" source '\" + str(updated.get(\"title\") or \"\")[:60] + \"'\",\n                )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"source\": source_public(updated)}), 200\n\n\n@bp.delete(\"/kb/sources/<int:source_id>\")\ndef delete_source(source_id: int):\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            cur.execute(\n                \"DELETE FROM \" + portal_db._q(CHUNKS_TABLE) +\n                \" WHERE client_id = %s AND source_id = %s\",\n                (client_id, int(source_id)),\n            )\n            cur.execute(\n                \"DELETE FROM \" + portal_db._q(VERSIONS_TABLE) +\n                \" WHERE client_id = %s AND source_id = %s\",\n                (client_id, int(source_id)),\n            )\n            cur.execute(\n                \"DELETE FROM \" + portal_db._q(SOURCES_TABLE) +\n                \" WHERE id = %s AND client_id = %s\",\n                (int(source_id), client_id),\n            )\n            portal_db.log_action(\n                cur, client_id, \"kb.source_deleted\", \"customer_user\",\n                principal.get(\"user_id\"), None,\n                \"Deleted source '\" + str(source.get(\"title\") or \"\")[:60] + \"'\",\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.post(\"/kb/sources/<int:source_id>/reindex\")\ndef reindex_source(source_id: int):\n    \"\"\"Re-fetch a web page, or re-chunk pasted/uploaded text (new text in\n    the body, else the latest stored version). Publication state is kept.\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    new_text = clean_text(payload.get(\"text\"))\n    if new_text and len(new_text) > MAX_SOURCE_CHARS:\n        return _bad(\"That text is too long (limit \" + str(MAX_SOURCE_CHARS)\n                    + \" characters).\", \"too_long\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            note = \"re-indexed\"\n            if str(source.get(\"kind\") or \"\") == \"url\":\n                try:\n                    text, _title = fetch_url(str(source.get(\"origin\") or \"\"))\n                except ValueError as problem:\n                    record_error(cur, client_id, source_id, str(problem))\n                    conn.commit()\n                    return _bad(str(problem), \"fetch_failed\")\n                note = \"re-fetched\"\n            elif new_text:\n                text = new_text\n                note = \"text replaced\"\n            else:\n                latest = version_content(cur, client_id, source_id)\n                text = str((latest or {}).get(\"content\") or \"\")\n                if len(text) < MIN_CHUNK_CHARS:\n                    conn.rollback()\n                    return _bad(\"No stored text to re-index. Paste the text\"\n                                \" again.\", \"empty_source\")\n            if len(text) < MIN_CHUNK_CHARS:\n                record_error(cur, client_id, source_id,\n                             \"The page returned no readable text.\")\n                conn.commit()\n                return _bad(\"The page returned no readable text.\",\n                            \"fetch_failed\")\n            source = ingest(cur, client_id, source, text, note,\n                            principal.get(\"user_id\"))\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"source\": source_public(source)}), 200\n\n\n@bp.get(\"/kb/sources/<int:source_id>/versions\")\ndef get_versions(source_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            versions = list_versions(cur, client_id, source_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"source\": source_public(source), \"versions\": versions}), 200\n\n\n@bp.post(\"/kb/sources/<int:source_id>/rollback\")\ndef rollback_source(source_id: int):\n    \"\"\"Re-index from an earlier version's stored text (creates a new\n    version, so history is never rewritten).\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    try:\n        version = int(payload.get(\"version\") or 0)\n    except Exception:\n        version = 0\n    if version <= 0:\n        return _bad(\"version is required.\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            snapshot = version_content(cur, client_id, source_id, version)\n            if snapshot is None or len(str(snapshot.get(\"content\") or \"\")) < MIN_CHUNK_CHARS:\n                conn.rollback()\n                return _bad(\"That version is no longer stored.\", \"not_found\", 404)\n            source = ingest(cur, client_id, source, str(snapshot.get(\"content\")),\n                            \"rolled back to v\" + str(version),\n                            principal.get(\"user_id\"))\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"source\": source_public(source)}), 200\n\n\n@bp.get(\"/kb/search\")\ndef search_knowledge():\n    \"\"\"Owner tester: exactly what the AI would retrieve for a question.\"\"\"\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    query = str(request.args.get(\"q\") or \"\").strip()[:300]\n    if not query:\n        return _bad(\"q is required.\")\n    try:\n        n = int(request.args.get(\"n\") or 5)\n    except Exception:\n        n = 5\n    n = max(1, min(10, n))\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            hits = retrieve(cur, client_id, query, n)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"query\": query, \"tokens\": query_tokens(query),\n                    \"hits\": hits}), 200\n\n\n@bp.after_request\ndef _kb_semantic_after(response):\n    \"\"\"D1: a successful owner write schedules a semantic-index sync.\"\"\"\n    try:\n        import portal_kb_semantic\n\n        return portal_kb_semantic.kick_after_mutation(response)\n    except Exception:\n        return response\n\n");
writeNewRepair("OmniFlow-Control-Plane/portal_knowledge.py", "SEMANTIC_KEYWORD_POOL = _env_int(\"OF_KB_HYBRID_KEYWORD_POOL\", 12, 1, 100)", true,
    "\"\"\"Knowledge engine (MASTER-UPGRADE engine 4): document / page ingestion,\ndeterministic chunking, versioning, health and keyword retrieval for the\nAI. D1 (delivered \u00a7211): ``portal_kb_semantic`` plugs meaning-based\nrecall into ``retrieve`` below (hybrid keyword + embeddings, reciprocal\nrank fusion) without changing the retrieval contract; keyword-only is\nthe automatic fallback.\n\nAudit-first (what already existed and stays):\n\n* ``portal_kb_entries`` (portal_kb) - owner-written Q&A answers with\n  trigger keywords. They still power the instant auto-reply on the\n  ingest path and the assist panel, untouched. Retrieval here searches\n  them TOGETHER with the new document chunks so the brain sees one\n  ranked knowledge list.\n* ``portal_kb_gaps`` (portal_growth) - unanswered questions; unchanged.\n* The KB auto-publish LOCK (owner law): nothing ingested here is ever\n  used by the AI until the owner publishes the source. New sources start\n  as ``draft``; ``published`` sources feed retrieval; ``paused`` sources\n  are kept but silent.\n\nSources (``portal_kb_sources``) are pasted text, uploaded text files\n(the browser reads .txt/.md/.csv/.json/.html and posts the text) or web\npages (fetched server-side with an SSRF guard). Every ingest writes a\nnew version snapshot (``portal_kb_source_versions``, raw text kept so a\nversion can be rolled back or re-chunked) and replaces the source's\nchunks (``portal_kb_chunks``). Retrieval is a single tenant-scoped SQL\ncandidate fetch (ILIKE on the query tokens) plus a deterministic\nBM25-style ranking in Python: term frequency, inverse candidate\nfrequency, heading/title boosts, phrase bonus and query coverage. Every\nhit carries a citation (source title + section) so the brain trace can\nshow where an answer came from. Fail-soft everywhere.\n\"\"\"\n\nimport html as html_lib\nimport ipaddress\nimport logging\nimport math\nimport os\nimport re\nimport socket\nimport urllib.error\nimport urllib.parse\nimport urllib.request\nfrom datetime import datetime, timedelta, timezone\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n    ensure_human_principal,\n)\n\nlogger = logging.getLogger(\"omniflow.portal-knowledge\")\n\nbp = Blueprint(\"portal_knowledge\", __name__, url_prefix=\"/api/v1/portal\")\n\nSOURCES_TABLE = \"portal_kb_sources\"\nVERSIONS_TABLE = \"portal_kb_source_versions\"\nCHUNKS_TABLE = \"portal_kb_chunks\"\nENTRIES_TABLE = \"portal_kb_entries\"\n\nKINDS: Tuple[str, ...] = (\"text\", \"file\", \"url\")\nSTATUSES: Tuple[str, ...] = (\"draft\", \"published\", \"paused\")\n\n\ndef _env_int(name: str, default: int, lo: int, hi: int) -> int:\n    try:\n        value = int(os.environ.get(name, \"\") or default)\n    except Exception:\n        value = default\n    return max(lo, min(hi, value))\n\n\nMAX_SOURCES = _env_int(\"OF_KB_SOURCES_MAX\", 50, 1, 1000)\nMAX_SOURCE_CHARS = _env_int(\"OF_KB_SOURCE_CHARS_MAX\", 200000, 1000, 2000000)\nCHUNK_CHARS = _env_int(\"OF_KB_CHUNK_CHARS\", 700, 200, 4000)\nCHUNK_OVERLAP = _env_int(\"OF_KB_CHUNK_OVERLAP\", 80, 0, 400)\nMAX_VERSIONS = _env_int(\"OF_KB_VERSIONS_MAX\", 10, 1, 100)\nURL_TIMEOUT = _env_int(\"OF_KB_URL_TIMEOUT\", 8, 2, 60)\nURL_BYTES_MAX = _env_int(\"OF_KB_URL_BYTES_MAX\", 1500000, 10000, 20000000)\nURL_STALE_DAYS = _env_int(\"OF_KB_URL_STALE_DAYS\", 30, 1, 365)\nRETRIEVE_CANDIDATES = _env_int(\"OF_KB_RETRIEVE_CANDIDATES\", 200, 10, 2000)\nQUERY_TOKENS_MAX = _env_int(\"OF_KB_QUERY_TOKENS_MAX\", 12, 3, 32)\nMAX_TITLE_CHARS = 120\nMAX_HEADING_CHARS = 160\nSNIPPET_CHARS = 400\nMIN_CHUNK_CHARS = 20\nINSERT_BATCH = 200\n\n_DDL_READY = False\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_kb_sources (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  title TEXT NOT NULL DEFAULT '',\n  kind TEXT NOT NULL DEFAULT 'text',\n  origin TEXT NOT NULL DEFAULT '',\n  status TEXT NOT NULL DEFAULT 'draft',\n  version INT NOT NULL DEFAULT 0,\n  chunk_count INT NOT NULL DEFAULT 0,\n  char_count INT NOT NULL DEFAULT 0,\n  last_error TEXT NOT NULL DEFAULT '',\n  ingested_at TIMESTAMPTZ,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_kb_sources_client\n  ON portal_kb_sources (client_id, status);\nCREATE TABLE IF NOT EXISTS portal_kb_source_versions (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  source_id BIGINT NOT NULL,\n  version INT NOT NULL,\n  content TEXT NOT NULL DEFAULT '',\n  chunk_count INT NOT NULL DEFAULT 0,\n  char_count INT NOT NULL DEFAULT 0,\n  note TEXT NOT NULL DEFAULT '',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_kb_source_versions_source\n  ON portal_kb_source_versions (client_id, source_id, version DESC);\nCREATE TABLE IF NOT EXISTS portal_kb_chunks (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  source_id BIGINT NOT NULL,\n  version INT NOT NULL DEFAULT 1,\n  position INT NOT NULL DEFAULT 0,\n  heading TEXT NOT NULL DEFAULT '',\n  content TEXT NOT NULL DEFAULT '',\n  char_count INT NOT NULL DEFAULT 0,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_kb_chunks_source\n  ON portal_kb_chunks (client_id, source_id, position);\n\"\"\"\n\n\ndef _ensure_ddl(cur) -> None:\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_DDL)\n    _DDL_READY = True\n\n\n# ---------------------------------------------------------------------------\n# Pure text helpers: normalisation, tokens, HTML, chunking, ranking\n# ---------------------------------------------------------------------------\n\n#: Function words that carry no retrieval signal (English + Roman Urdu).\nSTOPWORDS = frozenset(\"\"\"\na an the is are am was were be been being of to in on at for and or but if\nthen than so as by with from into onto about over under up down out off this\nthat these those it its i me my we our you your he she they them their his\nher what which who whom whose when where why how do does did done have has\nhad having can could will would shall should may might must not no yes ok\nokay please plz pls hi hello hey thanks thank\nka ki ke ko ki se me mein main hai hain he hen ho hoon hun hu tha thi the\nthay thi ye yeh wo woh is us un in ab aur or ya bhi to per par pe ap aap tum\nmera meri mere hamara hamari apna apni apne kya kia kyun kyu kaise kaisa\nkaisi kab kahan kon konsa kar karo karen karein kro krna karna kiya raha\nrahi rahe hoga hogi honge chahiye chaiye bhai ji han haan nahi nhi na\n\"\"\".split())\n\n_WORD_RE = re.compile(r\"\\w+\", re.UNICODE)\n_BLANK_RE = re.compile(r\"\\n\\s*\\n\")\n_SENTENCE_RE = re.compile(r\"(?<=[.!?\\u06d4])\\s+\")\n_HEADING_RE = re.compile(r\"^(#{1,6}\\s+|\\d+(\\.\\d+)*[.)]\\s+)\")\n\n\ndef normalize(text: Any) -> str:\n    return re.sub(r\"\\s+\", \" \", str(text or \"\").lower()).strip()\n\n\ndef _collapse(text: Any) -> str:\n    \"\"\"Whitespace-collapsed but case-preserving (titles and headings are\n    shown to the owner; matching lower-cases separately).\"\"\"\n    return re.sub(r\"\\s+\", \" \", str(text or \"\")).strip()\n\n\ndef words(text: Any) -> List[str]:\n    return [w for w in _WORD_RE.findall(str(text or \"\").lower())]\n\n\ndef tokenize(text: Any, limit: int = 0, keep_stopwords: bool = False) -> List[str]:\n    \"\"\"Unique retrieval tokens in order of appearance (stop words and\n    one-character fragments dropped). ``limit`` keeps the longest tokens\n    first so the SQL candidate fetch uses the most selective ones.\"\"\"\n    seen: List[str] = []\n    for word in words(text):\n        if len(word) < 2:\n            continue\n        if not keep_stopwords and word in STOPWORDS:\n            continue\n        if word not in seen:\n            seen.append(word)\n    if limit and len(seen) > limit:\n        seen = sorted(seen, key=lambda w: (-len(w), seen.index(w)))[:limit]\n    return seen\n\n\ndef query_tokens(text: Any) -> List[str]:\n    \"\"\"Tokens for a customer question; falls back to stop words when the\n    question is made of them only (\\\"kya hai\\\") so short questions still\n    get a candidate fetch.\"\"\"\n    tokens = tokenize(text, QUERY_TOKENS_MAX)\n    if not tokens:\n        tokens = tokenize(text, QUERY_TOKENS_MAX, keep_stopwords=True)\n    return tokens\n\n\n_TAG_RE = re.compile(r\"<[^>]+>\")\n_DROP_RE = re.compile(\n    r\"<(script|style|noscript|svg|head|template|iframe)[^>]*>.*?</\\1\\s*>\",\n    re.IGNORECASE | re.DOTALL)\n_COMMENT_RE = re.compile(r\"<!--.*?-->\", re.DOTALL)\n_BLOCK_RE = re.compile(\n    r\"</?(p|div|br|li|ul|ol|tr|td|th|table|section|article|header|footer|\"\n    r\"h[1-6]|blockquote|pre|hr|dd|dt|dl|nav|main|aside|figure|figcaption)\"\n    r\"[^>]*>\", re.IGNORECASE)\n_HEAD_TAG_RE = re.compile(r\"<h([1-6])[^>]*>(.*?)</h\\1\\s*>\",\n                          re.IGNORECASE | re.DOTALL)\n_TITLE_RE = re.compile(r\"<title[^>]*>(.*?)</title>\", re.IGNORECASE | re.DOTALL)\n\n\ndef html_title(markup: str) -> str:\n    match = _TITLE_RE.search(str(markup or \"\"))\n    if not match:\n        return \"\"\n    return _collapse(html_lib.unescape(_TAG_RE.sub(\" \", match.group(1))))[\n        :MAX_TITLE_CHARS]\n\n\ndef html_to_text(markup: str) -> str:\n    \"\"\"Readable text from HTML: scripts/styles/head dropped, headings kept\n    as markdown-style lines (so chunking can carry them), block tags become\n    paragraph breaks, entities unescaped, whitespace collapsed.\"\"\"\n    text = str(markup or \"\")\n    text = _COMMENT_RE.sub(\" \", text)\n    text = _DROP_RE.sub(\" \", text)\n    text = _HEAD_TAG_RE.sub(\n        lambda m: \"\\n\\n\" + \"#\" * int(m.group(1)) + \" \"\n        + _TAG_RE.sub(\" \", m.group(2)).strip() + \"\\n\\n\", text)\n    text = _BLOCK_RE.sub(\"\\n\\n\", text)\n    text = _TAG_RE.sub(\" \", text)\n    text = html_lib.unescape(text)\n    text = text.replace(\"\\xa0\", \" \")\n    lines = [re.sub(r\"[ \\t]+\", \" \", line).strip() for line in text.split(\"\\n\")]\n    out: List[str] = []\n    blank = False\n    for line in lines:\n        if line:\n            out.append(line)\n            blank = False\n        elif not blank and out:\n            out.append(\"\")\n            blank = True\n    return \"\\n\".join(out).strip()\n\n\ndef clean_text(text: Any) -> str:\n    \"\"\"Normalise pasted / uploaded text: CRLF, tabs, trailing spaces, at\n    most one blank line in a row.\"\"\"\n    value = str(text or \"\").replace(\"\\r\\n\", \"\\n\").replace(\"\\r\", \"\\n\")\n    value = value.replace(\"\\t\", \" \").replace(\"\\x00\", \"\")\n    lines = [re.sub(r\"[ ]+\", \" \", line).rstrip() for line in value.split(\"\\n\")]\n    out: List[str] = []\n    blank = False\n    for line in lines:\n        if line.strip():\n            out.append(line)\n            blank = False\n        elif not blank and out:\n            out.append(\"\")\n            blank = True\n    return \"\\n\".join(out).strip()\n\n\ndef _is_heading(block: str) -> bool:\n    if \"\\n\" in block or len(block) > 80:\n        return False\n    if _HEADING_RE.match(block):\n        return True\n    stripped = block.rstrip(\":\").strip()\n    if block.endswith(\":\") and len(stripped.split()) <= 8:\n        return True\n    letters = [c for c in stripped if c.isalpha()]\n    return bool(letters) and len(stripped.split()) <= 6 and all(\n        c.isupper() for c in letters)\n\n\ndef _heading_text(block: str) -> str:\n    return _collapse(_HEADING_RE.sub(\"\", block).rstrip(\":\"))[:MAX_HEADING_CHARS]\n\n\ndef _split_heading(block: str) -> Tuple[str, str]:\n    \"\"\"(heading, body) for a block whose first line is a heading and the\n    rest a paragraph (\"Returns\\nItems can be returned...\"); (\"\", block)\n    otherwise. A first line counts as a heading when it is short, has no\n    sentence punctuation and the line after it is longer.\"\"\"\n    if \"\\n\" not in block:\n        return \"\", block\n    first, rest = block.split(\"\\n\", 1)\n    first, rest = first.strip(), rest.strip()\n    if not first or not rest:\n        return \"\", block\n    if _is_heading(first):\n        return _heading_text(first), rest\n    if (len(first) <= 60 and len(first.split()) <= 8\n            and not first.endswith((\".\", \"!\", \"?\", \",\", \";\"))\n            and len(rest.split(\"\\n\", 1)[0]) > len(first)):\n        return _heading_text(first), rest\n    return \"\", block\n\n\ndef _split_long(block: str, size: int) -> List[str]:\n    \"\"\"A block bigger than one chunk: pack sentences up to ``size``; a\n    single sentence longer than that is cut at its last space.\"\"\"\n    pieces: List[str] = []\n    current = \"\"\n    for sentence in _SENTENCE_RE.split(block):\n        sentence = sentence.strip()\n        if not sentence:\n            continue\n        parts: List[str] = []\n        while len(sentence) > size:\n            cut = sentence.rfind(\" \", 0, size)\n            if cut < size // 2:\n                cut = size\n            parts.append(sentence[:cut].strip())\n            sentence = sentence[cut:].strip()\n        if sentence:\n            parts.append(sentence)\n        for part in parts:\n            if current and len(current) + len(part) + 1 > size:\n                pieces.append(current)\n                current = part\n            else:\n                current = (current + \" \" + part).strip()\n    if current:\n        pieces.append(current)\n    return pieces\n\n\ndef _overlap_tail(text: str, overlap: int) -> str:\n    if overlap <= 0 or len(text) <= overlap:\n        return \"\"\n    tail = text[-overlap:]\n    cut = tail.find(\" \")\n    return tail[cut + 1:].strip() if cut >= 0 else tail.strip()\n\n\ndef chunk_text(text: str, size: int = 0,\n               overlap: Optional[int] = None) -> List[Dict[str, Any]]:\n    \"\"\"Deterministic, heading-aware chunks: paragraphs are packed up to\n    ``size`` characters, headings label the chunks that follow them, over-\n    long paragraphs split at sentence boundaries, and each chunk starts\n    with a short overlap from the previous one so context is not cut.\"\"\"\n    size = size or CHUNK_CHARS\n    overlap = CHUNK_OVERLAP if overlap is None else max(0, overlap)\n    overlap = min(overlap, size // 3)\n    blocks = [b.strip() for b in _BLANK_RE.split(clean_text(text)) if b.strip()]\n    chunks: List[Dict[str, Any]] = []\n    heading = \"\"\n    current = \"\"\n    current_heading = \"\"\n    previous_text = \"\"\n\n    def flush() -> None:\n        nonlocal current, previous_text\n        body = current.strip()\n        if body:\n            chunks.append({\"position\": len(chunks),\n                           \"heading\": current_heading, \"content\": body})\n            previous_text = body\n        current = \"\"\n\n    for block in blocks:\n        if _is_heading(block):\n            flush()\n            previous_text = \"\"  # no overlap across sections\n            heading = _heading_text(block)\n            continue\n        inline_heading, block = _split_heading(block)\n        if inline_heading:\n            flush()\n            previous_text = \"\"\n            heading = inline_heading\n        # long paragraphs are packed a little below ``size`` so the overlap\n        # carried in from the previous chunk still fits\n        pieces = [block] if len(block) <= size else _split_long(\n            block, max(size // 2, size - overlap))\n        for piece in pieces:\n            if current and len(current) + len(piece) + 2 > size:\n                flush()\n            if not current:\n                current_heading = heading\n                tail = _overlap_tail(previous_text, overlap)\n                current = (tail + \" \" + piece).strip() if tail and len(\n                    tail) + len(piece) + 1 <= size else piece\n            else:\n                current = current + \"\\n\\n\" + piece\n    flush()\n    if len(chunks) > 1:\n        chunks = [c for c in chunks if len(c[\"content\"]) >= MIN_CHUNK_CHARS]\n        for index, chunk in enumerate(chunks):\n            chunk[\"position\"] = index\n    return chunks\n\n\ndef _matches(word: str, token: str) -> bool:\n    \"\"\"Exact match, or a prefix match once the token is long enough to be\n    a stem (return -> returned/returns, deliver -> delivery). Short Roman\n    Urdu words (din, kab) stay exact.\"\"\"\n    if word == token:\n        return True\n    if len(token) >= 4 and word.startswith(token):\n        return True\n    return len(word) >= 4 and token.startswith(word) and len(token) - len(word) <= 3\n\n\ndef _count(token: str, word_list: List[str]) -> int:\n    return sum(1 for w in word_list if _matches(w, token))\n\n\ndef score_candidates(tokens: List[str], candidates: List[Dict[str, Any]],\n                     n: int) -> List[Dict[str, Any]]:\n    \"\"\"BM25-style ranking without an index: per-token tf saturation,\n    inverse candidate frequency, title/heading boost, adjacent-token phrase\n    bonus and query coverage. Deterministic; ties break on shorter text\n    then id.\"\"\"\n    if not tokens or not candidates:\n        return []\n    prepared = []\n    for row in candidates:\n        title_words = words(row.get(\"title\"))\n        body_words = words(row.get(\"content\")) + words(row.get(\"extra\"))\n        title_hits = {t: _count(t, title_words) for t in tokens}\n        body_hits = {t: _count(t, body_words) for t in tokens}\n        prepared.append((row, title_words, body_words, title_hits, body_hits))\n    total = len(prepared)\n    df = {t: sum(1 for p in prepared if p[3][t] or p[4][t]) for t in tokens}\n    idf = {t: math.log(1.0 + total / (1.0 + df[t])) + 0.1 for t in tokens}\n    ranked = []\n    for row, title_words, body_words, title_hits, body_hits in prepared:\n        matched: List[str] = []\n        score = 0.0\n        for token in tokens:\n            tf = body_hits[token]\n            in_title = title_hits[token] > 0\n            if not tf and not in_title:\n                continue\n            matched.append(token)\n            weight = (1.0 + math.log(1.0 + tf)) if tf else 0.6\n            if in_title:\n                weight += 1.5\n            score += weight * idf[token]\n        if not matched:\n            continue\n        if len(tokens) > 1:\n            text_words = title_words + body_words\n            for a, b in zip(tokens, tokens[1:]):\n                for i in range(len(text_words) - 1):\n                    if _matches(text_words[i], a) and _matches(text_words[i + 1], b):\n                        score += 1.0\n                        break\n        coverage = len(matched) / float(len(tokens))\n        score *= 0.5 + 0.5 * coverage\n        ranked.append((round(score, 4), matched, row))\n    ranked.sort(key=lambda item: (-item[0], len(str(item[2].get(\"content\") or \"\")),\n                                  int(item[2].get(\"id\") or 0)))\n    hits = []\n    for score, matched, row in ranked[:max(1, n)]:\n        content = str(row.get(\"content\") or \"\")\n        hits.append({\n            \"kind\": str(row.get(\"kind\") or \"entry\"),\n            \"id\": int(row.get(\"id\") or 0),\n            \"title\": str(row.get(\"title\") or \"\"),\n            \"content\": content[:SNIPPET_CHARS],\n            \"source_id\": int(row.get(\"source_id\") or 0),\n            \"source\": str(row.get(\"source_title\") or \"\"),\n            \"position\": int(row.get(\"position\") or 0),\n            \"score\": score,\n            \"matched\": matched,\n        })\n    return hits\n\n\n# ---------------------------------------------------------------------------\n# URL fetch with SSRF guard\n# ---------------------------------------------------------------------------\n\ndef assert_public_url(url: str, resolver=None) -> Tuple[str, str]:\n    \"\"\"Validate an owner-supplied URL: http(s) only, a real host name, no\n    credentials, and every resolved address public (no loopback, private,\n    link-local, multicast or reserved ranges). Returns (scheme, host).\n    Raises ValueError with an owner-readable message.\"\"\"\n    parsed = urllib.parse.urlsplit(str(url or \"\").strip())\n    if parsed.scheme not in (\"http\", \"https\"):\n        raise ValueError(\"Only http and https links are supported.\")\n    host = (parsed.hostname or \"\").strip().lower().rstrip(\".\")\n    if not host or parsed.username or parsed.password:\n        raise ValueError(\"That link is not a valid web address.\")\n    if host == \"localhost\" or host.endswith(\".localhost\") or host.endswith(\n            \".local\") or host.endswith(\".internal\"):\n        raise ValueError(\"Internal addresses cannot be fetched.\")\n    resolve = resolver or socket.getaddrinfo\n    try:\n        infos = resolve(host, parsed.port or (443 if parsed.scheme == \"https\"\n                                                else 80))\n    except Exception:\n        raise ValueError(\"That web address could not be resolved.\")\n    addresses = []\n    for info in infos or []:\n        try:\n            addresses.append(ipaddress.ip_address(info[4][0]))\n        except Exception:\n            continue\n    if not addresses:\n        raise ValueError(\"That web address could not be resolved.\")\n    for address in addresses:\n        if (address.is_private or address.is_loopback or address.is_link_local\n                or address.is_multicast or address.is_reserved\n                or address.is_unspecified):\n            raise ValueError(\"Internal addresses cannot be fetched.\")\n    return parsed.scheme, host\n\n\nclass _SafeRedirectHandler(urllib.request.HTTPRedirectHandler):\n    \"\"\"Re-validates every redirect target (a public page may not bounce\n    the fetch onto an internal address).\"\"\"\n\n    def redirect_request(self, req, fp, code, msg, headers, newurl):\n        assert_public_url(newurl)\n        return super().redirect_request(req, fp, code, msg, headers, newurl)\n\n\ndef fetch_url(url: str) -> Tuple[str, str]:\n    \"\"\"Download a public page and return (text, title). Raises ValueError\n    with an owner-readable message on any problem.\"\"\"\n    assert_public_url(url)\n    req = urllib.request.Request(str(url).strip(), method=\"GET\")\n    req.add_header(\"Accept\", \"text/html, text/plain;q=0.9, */*;q=0.5\")\n    req.add_header(\"User-Agent\", \"OmniFlow-Knowledge/1.0 (+knowledge sources)\")\n    opener = urllib.request.build_opener(_SafeRedirectHandler())\n    try:\n        with opener.open(req, timeout=URL_TIMEOUT) as resp:\n            content_type = str(resp.headers.get(\"Content-Type\") or \"\").lower()\n            raw = resp.read(URL_BYTES_MAX + 1)\n    except urllib.error.HTTPError as error:\n        raise ValueError(\"The page answered with HTTP \" + str(error.code) + \".\")\n    except ValueError:\n        raise\n    except Exception:\n        raise ValueError(\"The page could not be fetched (timeout or \"\n                         \"connection error).\")\n    if len(raw) > URL_BYTES_MAX:\n        raise ValueError(\"The page is too large to import (limit \"\n                         + str(URL_BYTES_MAX // 1000) + \" KB).\")\n    kind = content_type.split(\";\")[0].strip()\n    if kind and not (kind.startswith(\"text/\") or kind in (\n            \"application/json\", \"application/xhtml+xml\", \"application/xml\")):\n        raise ValueError(\"Only web pages and text files can be imported \"\n                         \"from a link (got \" + kind + \").\")\n    charset = \"utf-8\"\n    match = re.search(r\"charset=([\\w-]+)\", content_type)\n    if match:\n        charset = match.group(1)\n    try:\n        body = raw.decode(charset, \"replace\")\n    except Exception:\n        body = raw.decode(\"utf-8\", \"replace\")\n    if kind in (\"text/html\", \"application/xhtml+xml\") or \"<html\" in body[:2000].lower():\n        return html_to_text(body), html_title(body)\n    return clean_text(body), \"\"\n\n\n# ---------------------------------------------------------------------------\n# DB helpers\n# ---------------------------------------------------------------------------\n\nSOURCE_COLS = (\"id, client_id, title, kind, origin, status, version, chunk_count,\"\n               \" char_count, last_error, ingested_at, created_at, updated_at\")\n\n\ndef _iso(value: Any) -> Optional[str]:\n    if value is None or value == \"\":\n        return None\n    if hasattr(value, \"isoformat\"):\n        return value.isoformat()\n    return str(value)\n\n\ndef _is_stale(row: Dict[str, Any]) -> bool:\n    if str(row.get(\"kind\") or \"\") != \"url\":\n        return False\n    stamp = row.get(\"ingested_at\")\n    if not isinstance(stamp, datetime):\n        return False\n    if stamp.tzinfo is None:\n        stamp = stamp.replace(tzinfo=timezone.utc)\n    return stamp < datetime.now(timezone.utc) - timedelta(days=URL_STALE_DAYS)\n\n\ndef source_public(row: Dict[str, Any]) -> Dict[str, Any]:\n    return {\n        \"id\": int(row.get(\"id\") or 0),\n        \"title\": str(row.get(\"title\") or \"\"),\n        \"kind\": str(row.get(\"kind\") or \"text\"),\n        \"origin\": str(row.get(\"origin\") or \"\"),\n        \"status\": str(row.get(\"status\") or \"draft\"),\n        \"version\": int(row.get(\"version\") or 0),\n        \"chunk_count\": int(row.get(\"chunk_count\") or 0),\n        \"char_count\": int(row.get(\"char_count\") or 0),\n        \"last_error\": str(row.get(\"last_error\") or \"\"),\n        \"stale\": _is_stale(row),\n        \"ingested_at\": _iso(row.get(\"ingested_at\")),\n        \"created_at\": _iso(row.get(\"created_at\")),\n        \"updated_at\": _iso(row.get(\"updated_at\")),\n    }\n\n\ndef get_source(cur, client_id: int, source_id: int) -> Optional[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT \" + SOURCE_COLS + \" FROM \" + portal_db._q(SOURCES_TABLE) +\n        \" WHERE id = %s AND client_id = %s\",\n        (int(source_id), client_id),\n    )\n    rows = portal_db.rows(cur)\n    return rows[0] if rows else None\n\n\ndef list_sources(cur, client_id: int) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT \" + SOURCE_COLS + \" FROM \" + portal_db._q(SOURCES_TABLE) +\n        \" WHERE client_id = %s ORDER BY updated_at DESC, id DESC LIMIT %s\",\n        (client_id, MAX_SOURCES + 50),\n    )\n    return portal_db.rows(cur)\n\n\ndef health(sources: List[Dict[str, Any]]) -> Dict[str, Any]:\n    out = {\"sources\": len(sources), \"published\": 0, \"drafts\": 0, \"paused\": 0,\n           \"chunks\": 0, \"errors\": 0, \"stale\": 0}\n    for row in sources:\n        status = str(row.get(\"status\") or \"draft\")\n        if status == \"published\":\n            out[\"published\"] += 1\n            out[\"chunks\"] += int(row.get(\"chunk_count\") or 0)\n        elif status == \"paused\":\n            out[\"paused\"] += 1\n        else:\n            out[\"drafts\"] += 1\n        if str(row.get(\"last_error\") or \"\"):\n            out[\"errors\"] += 1\n        if _is_stale(row):\n            out[\"stale\"] += 1\n    return out\n\n\ndef ingest(cur, client_id: int, source: Dict[str, Any], text: str,\n           note: str = \"\", actor_user_id: Optional[int] = None) -> Dict[str, Any]:\n    \"\"\"Chunk ``text`` for ``source``: replace its chunks, snapshot the raw\n    text as the next version, prune old versions, refresh the counters and\n    audit. Returns the updated source row. Never publishes.\"\"\"\n    source_id = int(source.get(\"id\") or 0)\n    content = clean_text(text)[:MAX_SOURCE_CHARS]\n    chunks = chunk_text(content)\n    version = int(source.get(\"version\") or 0) + 1\n    cur.execute(\n        \"DELETE FROM \" + portal_db._q(CHUNKS_TABLE) +\n        \" WHERE client_id = %s AND source_id = %s\",\n        (client_id, source_id),\n    )\n    for start in range(0, len(chunks), INSERT_BATCH):\n        batch = chunks[start:start + INSERT_BATCH]\n        values = \", \".join([\"(%s, %s, %s, %s, %s, %s, %s)\"] * len(batch))\n        params: List[Any] = []\n        for chunk in batch:\n            params.extend([client_id, source_id, version, chunk[\"position\"],\n                           chunk[\"heading\"], chunk[\"content\"],\n                           len(chunk[\"content\"])])\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(CHUNKS_TABLE) +\n            \" (client_id, source_id, version, position, heading, content,\"\n            \" char_count) VALUES \" + values,\n            tuple(params),\n        )\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(VERSIONS_TABLE) +\n        \" (client_id, source_id, version, content, chunk_count, char_count,\"\n        \" note) VALUES (%s, %s, %s, %s, %s, %s, %s)\",\n        (client_id, source_id, version, content, len(chunks), len(content),\n         str(note or \"\")[:200]),\n    )\n    cur.execute(\n        \"DELETE FROM \" + portal_db._q(VERSIONS_TABLE) +\n        \" WHERE client_id = %s AND source_id = %s AND version <= %s\",\n        (client_id, source_id, version - MAX_VERSIONS),\n    )\n    cur.execute(\n        \"UPDATE \" + portal_db._q(SOURCES_TABLE) +\n        \" SET version = %s, chunk_count = %s, char_count = %s, last_error = '',\"\n        \" ingested_at = NOW(), updated_at = NOW()\"\n        \" WHERE id = %s AND client_id = %s RETURNING \" + SOURCE_COLS,\n        (version, len(chunks), len(content), source_id, client_id),\n    )\n    rows = portal_db.rows(cur)\n    updated = rows[0] if rows else dict(source, version=version,\n                                        chunk_count=len(chunks),\n                                        char_count=len(content), last_error=\"\")\n    portal_db.log_action(\n        cur, client_id, \"kb.source_ingested\", \"customer_user\", actor_user_id,\n        None, \"Indexed '\" + str(updated.get(\"title\") or \"\")[:60] + \"' v\"\n        + str(version) + \" (\" + str(len(chunks)) + \" sections, \"\n        + str(len(content)) + \" chars)\" + (\" - \" + note if note else \"\"),\n    )\n    return updated\n\n\ndef record_error(cur, client_id: int, source_id: int, message: str) -> None:\n    cur.execute(\n        \"UPDATE \" + portal_db._q(SOURCES_TABLE) +\n        \" SET last_error = %s, updated_at = NOW()\"\n        \" WHERE id = %s AND client_id = %s\",\n        (str(message or \"\")[:300], int(source_id), client_id),\n    )\n\n\ndef version_content(cur, client_id: int, source_id: int,\n                    version: Optional[int] = None) -> Optional[Dict[str, Any]]:\n    where = \" AND version = %s\" if version else \"\"\n    params: Tuple[Any, ...] = (client_id, int(source_id)) + (\n        (int(version),) if version else ())\n    cur.execute(\n        \"SELECT version, content, chunk_count, char_count, note, created_at FROM \"\n        + portal_db._q(VERSIONS_TABLE) +\n        \" WHERE client_id = %s AND source_id = %s\" + where +\n        \" ORDER BY version DESC LIMIT 1\",\n        params,\n    )\n    rows = portal_db.rows(cur)\n    return rows[0] if rows else None\n\n\ndef list_versions(cur, client_id: int, source_id: int) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT version, chunk_count, char_count, note, created_at FROM \"\n        + portal_db._q(VERSIONS_TABLE) +\n        \" WHERE client_id = %s AND source_id = %s ORDER BY version DESC LIMIT %s\",\n        (client_id, int(source_id), MAX_VERSIONS),\n    )\n    return [{\"version\": int(r.get(\"version\") or 0),\n             \"chunk_count\": int(r.get(\"chunk_count\") or 0),\n             \"char_count\": int(r.get(\"char_count\") or 0),\n             \"note\": str(r.get(\"note\") or \"\"),\n             \"created_at\": _iso(r.get(\"created_at\"))}\n            for r in portal_db.rows(cur)]\n\n\ndef retrieve(cur, client_id: int, query: str, n: int = 5,\n             include_entries: bool = True) -> List[Dict[str, Any]]:\n    \"\"\"The one knowledge read for the brain and the owner's tester: active\n    Q&A entries + chunks of PUBLISHED sources, ranked deterministically.\n\n    Keyword ranking first (BM25-style over the query tokens); when the\n    semantic index is active and populated, meaning-based hits are fused\n    in (portal_kb_semantic.hybrid). Every hit carries ``via``\n    (keyword|semantic|both) and ``semantic`` (similarity or None).\n    Blank query -> [] without touching the DB.\"\"\"\n    if not str(query or \"\").strip():\n        return []\n    tokens = query_tokens(query)\n    keyword = _keyword_hits(cur, client_id, tokens,\n                            max(n, SEMANTIC_KEYWORD_POOL), include_entries)\n    try:\n        import portal_kb_semantic\n\n        fused = portal_kb_semantic.hybrid(cur, client_id, query, keyword, n,\n                                          include_entries, SNIPPET_CHARS)\n    except Exception as error:  # fail-soft: keyword ranking stands\n        logger.info(\"semantic retrieval skipped: %s\", error)\n        fused = None\n    if fused is not None:\n        return fused\n    out = []\n    for hit in keyword[:max(1, n)]:\n        hit[\"via\"] = \"keyword\"\n        hit[\"semantic\"] = None\n        out.append(hit)\n    return out\n\n\nSEMANTIC_KEYWORD_POOL = _env_int(\"OF_KB_HYBRID_KEYWORD_POOL\", 12, 1, 100)\n\n\ndef _keyword_hits(cur, client_id: int, tokens: List[str], n: int,\n                  include_entries: bool) -> List[Dict[str, Any]]:\n    \"\"\"Keyword candidates (ILIKE on the tokens) ranked by score_candidates.\n    No tokens -> [] without touching the DB.\"\"\"\n    if not tokens:\n        return []\n    patterns = [\"%\" + t + \"%\" for t in tokens]\n    limit = RETRIEVE_CANDIDATES\n    parts: List[str] = []\n    params: List[Any] = []\n    if include_entries:\n        parts.append(\n            \"SELECT 'entry' AS kind, e.id AS id, e.title AS title,\"\n            \" e.content AS content, e.keywords AS extra, 0 AS source_id,\"\n            \" '' AS source_title, 0 AS position FROM \"\n            + portal_db._q(ENTRIES_TABLE) + \" e\"\n            \" WHERE e.client_id = %s AND e.is_active IS TRUE\"\n            \" AND (e.title ILIKE ANY(%s) OR e.keywords ILIKE ANY(%s)\"\n            \" OR e.content ILIKE ANY(%s))\")\n        params.extend([client_id, patterns, patterns, patterns])\n    parts.append(\n        \"SELECT 'chunk' AS kind, c.id AS id, c.heading AS title,\"\n        \" c.content AS content, '' AS extra, c.source_id AS source_id,\"\n        \" s.title AS source_title, c.position AS position FROM \"\n        + portal_db._q(CHUNKS_TABLE) + \" c JOIN \" + portal_db._q(SOURCES_TABLE) +\n        \" s ON s.id = c.source_id AND s.client_id = c.client_id\"\n        \" WHERE c.client_id = %s AND s.status = 'published'\"\n        \" AND (c.heading ILIKE ANY(%s) OR c.content ILIKE ANY(%s))\")\n    params.extend([client_id, patterns, patterns])\n    params.append(limit)\n    cur.execute(\" UNION ALL \".join(parts) + \" LIMIT %s\", tuple(params))\n    return score_candidates(tokens, portal_db.rows(cur), n)\n\n\n# ---------------------------------------------------------------------------\n# HTTP\n# ---------------------------------------------------------------------------\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    return principal, None\n\n\ndef _human_or_error():\n    principal, error = _principal_or_error()\n    if error:\n        return None, error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return None, forbidden\n    return principal, None\n\n\ndef _bad(message: str, code: str = \"bad_request\", status: int = 400):\n    return jsonify({\"error\": {\"code\": code, \"message\": message}}), status\n\n\ndef _limits() -> Dict[str, Any]:\n    return {\"max_sources\": MAX_SOURCES, \"max_chars\": MAX_SOURCE_CHARS,\n            \"chunk_chars\": CHUNK_CHARS, \"max_versions\": MAX_VERSIONS,\n            \"kinds\": list(KINDS)}\n\n\ndef _title_from(text: str, fallback: str) -> str:\n    for line in str(text or \"\").split(\"\\n\"):\n        line = _HEADING_RE.sub(\"\", line).strip().strip(\"#\").strip()\n        if line:\n            return line[:MAX_TITLE_CHARS]\n    return fallback[:MAX_TITLE_CHARS]\n\n\n@bp.get(\"/kb/sources\")\ndef get_sources():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            rows = list_sources(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"sources\": [source_public(r) for r in rows],\n                    \"health\": health(rows), \"limits\": _limits()}), 200\n\n\n@bp.post(\"/kb/sources\")\ndef post_source():\n    \"\"\"Create a source and index it right away. It stays a DRAFT until the\n    owner publishes it (KB auto-publish lock).\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    kind = str(payload.get(\"kind\") or \"text\").strip().lower()\n    if kind not in KINDS:\n        return _bad(\"kind must be one of text, file, url.\")\n    title = str(payload.get(\"title\") or \"\").strip()[:MAX_TITLE_CHARS]\n    origin = \"\"\n    if kind == \"url\":\n        url = str(payload.get(\"url\") or \"\").strip()[:2000]\n        if not url:\n            return _bad(\"A web address is required.\")\n        try:\n            text, page_title = fetch_url(url)\n        except ValueError as problem:\n            return _bad(str(problem), \"fetch_failed\")\n        origin = url\n        title = title or page_title or _title_from(text, url)\n    else:\n        text = clean_text(payload.get(\"text\"))\n        origin = str(payload.get(\"filename\") or \"\").strip()[:200] if kind == \"file\" else \"\"\n        title = title or _title_from(text, origin or \"Pasted text\")\n    if len(text) < MIN_CHUNK_CHARS:\n        return _bad(\"There is not enough text to index (at least \"\n                    + str(MIN_CHUNK_CHARS) + \" characters).\")\n    if len(text) > MAX_SOURCE_CHARS:\n        return _bad(\"That source is too long (limit \"\n                    + str(MAX_SOURCE_CHARS) + \" characters). Split it into\"\n                    \" smaller documents.\", \"too_long\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"SELECT COUNT(*) AS n FROM \" + portal_db._q(SOURCES_TABLE) +\n                \" WHERE client_id = %s\",\n                (client_id,),\n            )\n            rows = portal_db.rows(cur)\n            if int((rows[0] if rows else {}).get(\"n\") or 0) >= MAX_SOURCES:\n                conn.rollback()\n                return _bad(\"This workspace already has the maximum of \"\n                            + str(MAX_SOURCES) + \" sources.\", \"limit\", 409)\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(SOURCES_TABLE) +\n                \" (client_id, title, kind, origin, status)\"\n                \" VALUES (%s, %s, %s, %s, 'draft') RETURNING \" + SOURCE_COLS,\n                (client_id, title, kind, origin),\n            )\n            rows = portal_db.rows(cur)\n            source = rows[0] if rows else {\"id\": 0, \"title\": title,\n                                           \"kind\": kind, \"version\": 0}\n            source = ingest(cur, client_id, source, text, \"created\",\n                            principal.get(\"user_id\"))\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"source\": source_public(source)}), 200\n\n\n@bp.put(\"/kb/sources/<int:source_id>\")\ndef put_source(source_id: int):\n    \"\"\"Owner review: publish / pause / back to draft, rename.\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    status = str(payload.get(\"status\") or \"\").strip().lower()\n    title = str(payload.get(\"title\") or \"\").strip()[:MAX_TITLE_CHARS]\n    if status and status not in STATUSES:\n        return _bad(\"status must be one of draft, published, paused.\")\n    if not status and not title:\n        return _bad(\"Nothing to update.\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            if status == \"published\" and int(source.get(\"chunk_count\") or 0) == 0:\n                conn.rollback()\n                return _bad(\"This source has no indexed text yet. Re-index it\"\n                            \" before publishing.\", \"empty_source\")\n            sets = [\"updated_at = NOW()\"]\n            params: List[Any] = []\n            if status:\n                sets.append(\"status = %s\")\n                params.append(status)\n            if title:\n                sets.append(\"title = %s\")\n                params.append(title)\n            params.extend([int(source_id), client_id])\n            cur.execute(\n                \"UPDATE \" + portal_db._q(SOURCES_TABLE) + \" SET \" +\n                \", \".join(sets) + \" WHERE id = %s AND client_id = %s RETURNING \"\n                + SOURCE_COLS,\n                tuple(params),\n            )\n            rows = portal_db.rows(cur)\n            updated = rows[0] if rows else dict(source)\n            if status and status != str(source.get(\"status\") or \"\"):\n                portal_db.log_action(\n                    cur, client_id, \"kb.source_\" + status, \"customer_user\",\n                    principal.get(\"user_id\"), None,\n                    (\"Published\" if status == \"published\" else\n                     \"Paused\" if status == \"paused\" else \"Unpublished\")\n                    + \" source '\" + str(updated.get(\"title\") or \"\")[:60] + \"'\",\n                )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"source\": source_public(updated)}), 200\n\n\n@bp.delete(\"/kb/sources/<int:source_id>\")\ndef delete_source(source_id: int):\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            cur.execute(\n                \"DELETE FROM \" + portal_db._q(CHUNKS_TABLE) +\n                \" WHERE client_id = %s AND source_id = %s\",\n                (client_id, int(source_id)),\n            )\n            cur.execute(\n                \"DELETE FROM \" + portal_db._q(VERSIONS_TABLE) +\n                \" WHERE client_id = %s AND source_id = %s\",\n                (client_id, int(source_id)),\n            )\n            cur.execute(\n                \"DELETE FROM \" + portal_db._q(SOURCES_TABLE) +\n                \" WHERE id = %s AND client_id = %s\",\n                (int(source_id), client_id),\n            )\n            portal_db.log_action(\n                cur, client_id, \"kb.source_deleted\", \"customer_user\",\n                principal.get(\"user_id\"), None,\n                \"Deleted source '\" + str(source.get(\"title\") or \"\")[:60] + \"'\",\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.post(\"/kb/sources/<int:source_id>/reindex\")\ndef reindex_source(source_id: int):\n    \"\"\"Re-fetch a web page, or re-chunk pasted/uploaded text (new text in\n    the body, else the latest stored version). Publication state is kept.\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    new_text = clean_text(payload.get(\"text\"))\n    if new_text and len(new_text) > MAX_SOURCE_CHARS:\n        return _bad(\"That text is too long (limit \" + str(MAX_SOURCE_CHARS)\n                    + \" characters).\", \"too_long\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            note = \"re-indexed\"\n            if str(source.get(\"kind\") or \"\") == \"url\":\n                try:\n                    text, _title = fetch_url(str(source.get(\"origin\") or \"\"))\n                except ValueError as problem:\n                    record_error(cur, client_id, source_id, str(problem))\n                    conn.commit()\n                    return _bad(str(problem), \"fetch_failed\")\n                note = \"re-fetched\"\n            elif new_text:\n                text = new_text\n                note = \"text replaced\"\n            else:\n                latest = version_content(cur, client_id, source_id)\n                text = str((latest or {}).get(\"content\") or \"\")\n                if len(text) < MIN_CHUNK_CHARS:\n                    conn.rollback()\n                    return _bad(\"No stored text to re-index. Paste the text\"\n                                \" again.\", \"empty_source\")\n            if len(text) < MIN_CHUNK_CHARS:\n                record_error(cur, client_id, source_id,\n                             \"The page returned no readable text.\")\n                conn.commit()\n                return _bad(\"The page returned no readable text.\",\n                            \"fetch_failed\")\n            source = ingest(cur, client_id, source, text, note,\n                            principal.get(\"user_id\"))\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"source\": source_public(source)}), 200\n\n\n@bp.get(\"/kb/sources/<int:source_id>/versions\")\ndef get_versions(source_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            versions = list_versions(cur, client_id, source_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"source\": source_public(source), \"versions\": versions}), 200\n\n\n@bp.post(\"/kb/sources/<int:source_id>/rollback\")\ndef rollback_source(source_id: int):\n    \"\"\"Re-index from an earlier version's stored text (creates a new\n    version, so history is never rewritten).\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    try:\n        version = int(payload.get(\"version\") or 0)\n    except Exception:\n        version = 0\n    if version <= 0:\n        return _bad(\"version is required.\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            snapshot = version_content(cur, client_id, source_id, version)\n            if snapshot is None or len(str(snapshot.get(\"content\") or \"\")) < MIN_CHUNK_CHARS:\n                conn.rollback()\n                return _bad(\"That version is no longer stored.\", \"not_found\", 404)\n            source = ingest(cur, client_id, source, str(snapshot.get(\"content\")),\n                            \"rolled back to v\" + str(version),\n                            principal.get(\"user_id\"))\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"source\": source_public(source)}), 200\n\n\n@bp.get(\"/kb/search\")\ndef search_knowledge():\n    \"\"\"Owner tester: exactly what the AI would retrieve for a question.\"\"\"\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    query = str(request.args.get(\"q\") or \"\").strip()[:300]\n    if not query:\n        return _bad(\"q is required.\")\n    try:\n        n = int(request.args.get(\"n\") or 5)\n    except Exception:\n        n = 5\n    n = max(1, min(10, n))\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            hits = retrieve(cur, client_id, query, n)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"query\": query, \"tokens\": query_tokens(query),\n                    \"hits\": hits}), 200\n\n\n@bp.after_request\ndef _kb_semantic_after(response):\n    \"\"\"D1: a successful owner write schedules a semantic-index sync.\"\"\"\n    try:\n        import portal_kb_semantic\n\n        return portal_kb_semantic.kick_after_mutation(response)\n    except Exception:\n        return response\n\n");
writeNewRepair("omniflow-backend-patch/portal_llm.py", "# Embeddings (D1 knowledge semantic index) - same OpenAI-compatible contract", false,
    "\"\"\"Tiny OpenAI-compatible chat client (standard library only).\n\nThe platform stays lightweight: no SDK, no new infrastructure. Point\n``OF_LLM_BASE_URL`` at any OpenAI-compatible endpoint (OpenAI, Groq,\nOpenRouter, a local Ollama) and put the key in ``OF_LLM_API_KEY``.\n\nContract: every helper is FAIL-SOFT. Callers receive ``None`` instead of an\nexception and must fall back to their non-LLM path, so a missing key, an\noutage or a slow provider never blocks a customer message. The default\nbudget is one attempt with a short timeout \u2014 the ingest loop must not stall.\n\"\"\"\n\nimport json\nimport logging\nimport math\nimport os\nimport threading\nimport time\nimport urllib.error\nimport urllib.request\nfrom typing import Any, Dict, List, Optional, Tuple\n\nlogger = logging.getLogger(\"omniflow.llm\")\n\n_SCOPE = threading.local()\n\n\nclass usage_scope:\n    \"\"\"Tag the LLM calls made inside the block for the AI usage ledger:\n\n        with portal_llm.usage_scope(\"brain\", client_id, cur, agent_id=agent_id):\n            payload = portal_llm.chat_json(...)\n\n    ``cur`` (optional) lets the ledger row ride the caller's transaction\n    (savepoint-guarded); without it the ledger opens its own short\n    connection. ``agent_id`` (optional) attributes the call to an AI\n    persona for per-agent cost split. Scopes nest (innermost wins) and\n    never raise.\"\"\"\n\n    def __init__(self, feature: str, client_id: int = 0, cur=None,\n                 agent_id: int = 0):\n        self.entry = (str(feature or \"\")[:40], int(client_id or 0), cur,\n                      int(agent_id or 0))\n\n    def __enter__(self):\n        stack = getattr(_SCOPE, \"stack\", None)\n        if stack is None:\n            stack = _SCOPE.stack = []\n        stack.append(self.entry)\n        return self\n\n    def __exit__(self, *exc):\n        stack = getattr(_SCOPE, \"stack\", None)\n        if stack:\n            stack.pop()\n        return False\n\n\ndef current_scope():\n    \"\"\"(feature, client_id, cur, agent_id) of the innermost usage_scope.\"\"\"\n    stack = getattr(_SCOPE, \"stack\", None)\n    return stack[-1] if stack else (\"\", 0, None, 0)\n\n\ndef _record_usage(model: str, usage: Any, ok: bool, started: float) -> None:\n    \"\"\"Hand the call to the usage ledger (fail-soft, never raises).\"\"\"\n    try:\n        import portal_ai_usage\n\n        feature, client_id, cur, agent_id = current_scope()\n        usage = usage if isinstance(usage, dict) else {}\n        portal_ai_usage.record(\n            client_id, feature or \"other\", model,\n            int(usage.get(\"prompt_tokens\") or 0),\n            int(usage.get(\"completion_tokens\") or 0),\n            int((time.time() - started) * 1000), ok, cur=cur,\n            agent_id=agent_id)\n    except Exception:\n        pass\n\nBASE_URL = os.environ.get(\n    \"OF_LLM_BASE_URL\", \"https://api.openai.com/v1\").rstrip(\"/\")\nAPI_KEY = os.environ.get(\"OF_LLM_API_KEY\", \"\")\nMODEL = os.environ.get(\"OF_LLM_MODEL\", \"gpt-4o-mini\")\nTIMEOUT_SECONDS = float(os.environ.get(\"OF_LLM_TIMEOUT_SECONDS\", \"6\") or 6)\nATTEMPTS = max(1, int(os.environ.get(\"OF_LLM_ATTEMPTS\", \"1\") or 1))\nENABLED = os.environ.get(\n    \"OF_LLM_ENABLED\", \"1\").strip().lower() not in (\"0\", \"false\", \"no\", \"off\")\n\n\ndef _http_post_json(url: str, headers: Dict[str, str],\n                    payload: Dict[str, Any]) -> Optional[Dict[str, Any]]:\n    \"\"\"POST JSON, return the decoded body; None on any transport error.\"\"\"\n    try:\n        request = urllib.request.Request(\n            url,\n            data=json.dumps(payload).encode(\"utf-8\"),\n            headers=headers,\n            method=\"POST\",\n        )\n        with urllib.request.urlopen(request, timeout=TIMEOUT_SECONDS) as resp:\n            return json.loads(resp.read().decode(\"utf-8\"))\n    except Exception:\n        return None\n\n\ndef _gated() -> bool:\n    \"\"\"Platform AI gate (admin kill switch / per-workspace daily call cap)\n    for the call being made in the current usage scope; fail-open.\"\"\"\n    try:\n        import portal_ai_usage\n\n        feature, client_id, cur, _agent_id = current_scope()\n        reason = portal_ai_usage.gate(feature, client_id, cur)\n    except Exception:\n        return False\n    if reason:\n        logger.info(\"llm call blocked (%s) client=%s feature=%s\",\n                    reason, client_id, feature)\n        return True\n    return False\n\n\ndef _runtime() -> Dict[str, Any]:\n    \"\"\"Effective config: admin panel first, env fallback (fail-soft).\"\"\"\n    try:\n        import platform_settings\n        config = platform_settings.llm_config()\n        if config.get(\"enabled\") and config.get(\"api_key\"):\n            return config\n        if not ENABLED:\n            return {\"base_url\": BASE_URL, \"api_key\": \"\", \"model\": MODEL,\n                    \"enabled\": False}\n        if config.get(\"api_key\"):\n            return config\n    except Exception:\n        pass\n    return {\"base_url\": BASE_URL, \"api_key\": API_KEY, \"model\": MODEL,\n            \"enabled\": bool(ENABLED and API_KEY)}\n\n\ndef chat_json(system: str, user: str,\n              max_tokens: int = 120) -> Optional[Dict[str, Any]]:\n    \"\"\"One JSON-mode chat call; parsed object or None (never raises).\"\"\"\n    runtime = _runtime()\n    if not runtime.get(\"enabled\") or not runtime.get(\"api_key\"):\n        return None\n    if _gated():\n        return None\n    payload = {\n        \"model\": runtime.get(\"model\") or MODEL,\n        \"messages\": [\n            {\"role\": \"system\", \"content\": system},\n            {\"role\": \"user\", \"content\": user},\n        ],\n        \"temperature\": 0,\n        \"max_tokens\": max_tokens,\n        \"response_format\": {\"type\": \"json_object\"},\n    }\n    headers = {\n        \"Authorization\": \"Bearer \" + str(runtime[\"api_key\"]),\n        \"Content-Type\": \"application/json\",\n    }\n    base = str(runtime.get(\"base_url\") or BASE_URL).rstrip(\"/\")\n    model = str(payload[\"model\"])\n    started = time.time()\n    last_usage = None\n    for _ in range(ATTEMPTS):\n        data = _http_post_json(base + \"/chat/completions\", headers, payload)\n        if not data:\n            continue\n        last_usage = data.get(\"usage\") if isinstance(data, dict) else None\n        try:\n            content = data[\"choices\"][0][\"message\"][\"content\"]\n            parsed = json.loads(content)\n        except Exception:\n            continue\n        if isinstance(parsed, dict):\n            _record_usage(model, last_usage, True, started)\n            return parsed\n    _record_usage(model, last_usage, False, started)\n    return None\n\n\n# ---------------------------------------------------------------------------\n# Embeddings (D1 knowledge semantic index) - same OpenAI-compatible contract\n# ---------------------------------------------------------------------------\n\nEMBED_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_EMBED_TIMEOUT_SECONDS\", \"20\") or 20)\nEMBED_MAX_INPUTS = max(1, min(256, int(\n    os.environ.get(\"OF_EMBED_BATCH\", \"32\") or 32)))\nEMBED_TEXT_CHARS = max(200, int(\n    os.environ.get(\"OF_EMBED_TEXT_CHARS\", \"2000\") or 2000))\n\n\ndef embed_runtime() -> Dict[str, Any]:\n    \"\"\"Effective embedding config (platform_settings.embed_config);\n    inactive on any error.\"\"\"\n    try:\n        import platform_settings\n        return platform_settings.embed_config()\n    except Exception:\n        return {\"active\": False, \"reason\": \"no_key\", \"api_key\": \"\",\n                \"base_url\": BASE_URL, \"model\": \"\", \"dimensions\": 0,\n                \"min_similarity\": 0.3, \"mode\": \"on\", \"key_source\": \"none\"}\n\n\ndef normalize_vector(values: Any) -> Optional[List[float]]:\n    \"\"\"L2-normalise (needed for Matryoshka-truncated vectors, harmless for\n    the rest) so cosine similarity becomes a plain dot product.\"\"\"\n    try:\n        vector = [float(v) for v in values]\n    except Exception:\n        return None\n    if not vector:\n        return None\n    norm = math.sqrt(sum(v * v for v in vector))\n    if not norm or math.isnan(norm):\n        return None\n    return [v / norm for v in vector]\n\n\ndef _post_detail(url: str, headers: Dict[str, str], payload: Dict[str, Any],\n                 timeout: float) -> Tuple[Optional[Dict[str, Any]], str]:\n    \"\"\"POST JSON -> (body, \"\") or (None, short error) - never raises.\"\"\"\n    try:\n        request = urllib.request.Request(\n            url, data=json.dumps(payload).encode(\"utf-8\"), headers=headers,\n            method=\"POST\")\n        with urllib.request.urlopen(request, timeout=timeout) as resp:\n            return json.loads(resp.read().decode(\"utf-8\")), \"\"\n    except urllib.error.HTTPError as error:\n        detail = \"\"\n        try:\n            body = json.loads(error.read().decode(\"utf-8\") or \"{}\")\n            err = body.get(\"error\") if isinstance(body, dict) else None\n            if isinstance(err, dict):\n                detail = str(err.get(\"message\") or \"\")\n            elif isinstance(body, list) and body and isinstance(body[0], dict):\n                detail = str((body[0].get(\"error\") or {}).get(\"message\") or \"\")\n        except Exception:\n            detail = \"\"\n        return None, (\"HTTP \" + str(error.code)\n                      + (\": \" + detail[:160] if detail else \"\"))\n    except Exception as error:\n        return None, type(error).__name__ + \": \" + str(error)[:120]\n\n\ndef embed_texts(texts: List[str], timeout: Optional[float] = None,\n                runtime: Optional[Dict[str, Any]] = None\n                ) -> Tuple[Optional[List[List[float]]], str]:\n    \"\"\"Embed up to EMBED_MAX_INPUTS texts in one call.\n\n    Returns (normalised vectors in input order, \"\") or (None, reason).\n    Honours the platform AI gate (kill switch / daily cap) and writes one\n    usage-ledger row under the caller's usage_scope. Never raises.\"\"\"\n    items = [str(t or \"\")[:EMBED_TEXT_CHARS] for t in (texts or [])]\n    if not items:\n        return [], \"\"\n    if len(items) > EMBED_MAX_INPUTS:\n        return None, \"too many inputs for one call\"\n    config = runtime or embed_runtime()\n    if not config.get(\"active\") or not config.get(\"api_key\"):\n        return None, \"embeddings not configured (\" + str(\n            config.get(\"reason\") or \"no_key\") + \")\"\n    if _gated():\n        return None, \"blocked by the platform AI controls\"\n    model = str(config.get(\"model\") or \"\")\n    payload: Dict[str, Any] = {\"model\": model, \"input\": items}\n    dims = int(config.get(\"dimensions\") or 0)\n    if dims > 0:\n        payload[\"dimensions\"] = dims\n    headers = {\n        \"Authorization\": \"Bearer \" + str(config[\"api_key\"]),\n        \"Content-Type\": \"application/json\",\n    }\n    base = str(config.get(\"base_url\") or BASE_URL).rstrip(\"/\")\n    started = time.time()\n    data, error = _post_detail(base + \"/embeddings\", headers, payload,\n                               float(timeout or EMBED_TIMEOUT_SECONDS))\n    usage = data.get(\"usage\") if isinstance(data, dict) else None\n    if not isinstance(data, dict):\n        _record_usage(model, usage, False, started)\n        return None, error or \"no response\"\n    rows = data.get(\"data\")\n    if not isinstance(rows, list) or len(rows) != len(items):\n        _record_usage(model, usage, False, started)\n        return None, \"unexpected embeddings response\"\n    try:\n        ordered = sorted(rows, key=lambda r: int(r.get(\"index\", 0)))\n    except Exception:\n        ordered = rows\n    vectors: List[List[float]] = []\n    for row in ordered:\n        vector = normalize_vector((row or {}).get(\"embedding\") or [])\n        if vector is None:\n            _record_usage(model, usage, False, started)\n            return None, \"empty embedding in response\"\n        vectors.append(vector)\n    if len({len(v) for v in vectors}) != 1:\n        _record_usage(model, usage, False, started)\n        return None, \"inconsistent embedding sizes\"\n    _record_usage(model, usage, True, started)\n    return vectors, \"\"\n\n");
writeNewRepair("OmniFlow-Control-Plane/portal_llm.py", "# Embeddings (D1 knowledge semantic index) - same OpenAI-compatible contract", true,
    "\"\"\"Tiny OpenAI-compatible chat client (standard library only).\n\nThe platform stays lightweight: no SDK, no new infrastructure. Point\n``OF_LLM_BASE_URL`` at any OpenAI-compatible endpoint (OpenAI, Groq,\nOpenRouter, a local Ollama) and put the key in ``OF_LLM_API_KEY``.\n\nContract: every helper is FAIL-SOFT. Callers receive ``None`` instead of an\nexception and must fall back to their non-LLM path, so a missing key, an\noutage or a slow provider never blocks a customer message. The default\nbudget is one attempt with a short timeout \u2014 the ingest loop must not stall.\n\"\"\"\n\nimport json\nimport logging\nimport math\nimport os\nimport threading\nimport time\nimport urllib.error\nimport urllib.request\nfrom typing import Any, Dict, List, Optional, Tuple\n\nlogger = logging.getLogger(\"omniflow.llm\")\n\n_SCOPE = threading.local()\n\n\nclass usage_scope:\n    \"\"\"Tag the LLM calls made inside the block for the AI usage ledger:\n\n        with portal_llm.usage_scope(\"brain\", client_id, cur, agent_id=agent_id):\n            payload = portal_llm.chat_json(...)\n\n    ``cur`` (optional) lets the ledger row ride the caller's transaction\n    (savepoint-guarded); without it the ledger opens its own short\n    connection. ``agent_id`` (optional) attributes the call to an AI\n    persona for per-agent cost split. Scopes nest (innermost wins) and\n    never raise.\"\"\"\n\n    def __init__(self, feature: str, client_id: int = 0, cur=None,\n                 agent_id: int = 0):\n        self.entry = (str(feature or \"\")[:40], int(client_id or 0), cur,\n                      int(agent_id or 0))\n\n    def __enter__(self):\n        stack = getattr(_SCOPE, \"stack\", None)\n        if stack is None:\n            stack = _SCOPE.stack = []\n        stack.append(self.entry)\n        return self\n\n    def __exit__(self, *exc):\n        stack = getattr(_SCOPE, \"stack\", None)\n        if stack:\n            stack.pop()\n        return False\n\n\ndef current_scope():\n    \"\"\"(feature, client_id, cur, agent_id) of the innermost usage_scope.\"\"\"\n    stack = getattr(_SCOPE, \"stack\", None)\n    return stack[-1] if stack else (\"\", 0, None, 0)\n\n\ndef _record_usage(model: str, usage: Any, ok: bool, started: float) -> None:\n    \"\"\"Hand the call to the usage ledger (fail-soft, never raises).\"\"\"\n    try:\n        import portal_ai_usage\n\n        feature, client_id, cur, agent_id = current_scope()\n        usage = usage if isinstance(usage, dict) else {}\n        portal_ai_usage.record(\n            client_id, feature or \"other\", model,\n            int(usage.get(\"prompt_tokens\") or 0),\n            int(usage.get(\"completion_tokens\") or 0),\n            int((time.time() - started) * 1000), ok, cur=cur,\n            agent_id=agent_id)\n    except Exception:\n        pass\n\nBASE_URL = os.environ.get(\n    \"OF_LLM_BASE_URL\", \"https://api.openai.com/v1\").rstrip(\"/\")\nAPI_KEY = os.environ.get(\"OF_LLM_API_KEY\", \"\")\nMODEL = os.environ.get(\"OF_LLM_MODEL\", \"gpt-4o-mini\")\nTIMEOUT_SECONDS = float(os.environ.get(\"OF_LLM_TIMEOUT_SECONDS\", \"6\") or 6)\nATTEMPTS = max(1, int(os.environ.get(\"OF_LLM_ATTEMPTS\", \"1\") or 1))\nENABLED = os.environ.get(\n    \"OF_LLM_ENABLED\", \"1\").strip().lower() not in (\"0\", \"false\", \"no\", \"off\")\n\n\ndef _http_post_json(url: str, headers: Dict[str, str],\n                    payload: Dict[str, Any]) -> Optional[Dict[str, Any]]:\n    \"\"\"POST JSON, return the decoded body; None on any transport error.\"\"\"\n    try:\n        request = urllib.request.Request(\n            url,\n            data=json.dumps(payload).encode(\"utf-8\"),\n            headers=headers,\n            method=\"POST\",\n        )\n        with urllib.request.urlopen(request, timeout=TIMEOUT_SECONDS) as resp:\n            return json.loads(resp.read().decode(\"utf-8\"))\n    except Exception:\n        return None\n\n\ndef _gated() -> bool:\n    \"\"\"Platform AI gate (admin kill switch / per-workspace daily call cap)\n    for the call being made in the current usage scope; fail-open.\"\"\"\n    try:\n        import portal_ai_usage\n\n        feature, client_id, cur, _agent_id = current_scope()\n        reason = portal_ai_usage.gate(feature, client_id, cur)\n    except Exception:\n        return False\n    if reason:\n        logger.info(\"llm call blocked (%s) client=%s feature=%s\",\n                    reason, client_id, feature)\n        return True\n    return False\n\n\ndef _runtime() -> Dict[str, Any]:\n    \"\"\"Effective config: admin panel first, env fallback (fail-soft).\"\"\"\n    try:\n        import platform_settings\n        config = platform_settings.llm_config()\n        if config.get(\"enabled\") and config.get(\"api_key\"):\n            return config\n        if not ENABLED:\n            return {\"base_url\": BASE_URL, \"api_key\": \"\", \"model\": MODEL,\n                    \"enabled\": False}\n        if config.get(\"api_key\"):\n            return config\n    except Exception:\n        pass\n    return {\"base_url\": BASE_URL, \"api_key\": API_KEY, \"model\": MODEL,\n            \"enabled\": bool(ENABLED and API_KEY)}\n\n\ndef chat_json(system: str, user: str,\n              max_tokens: int = 120) -> Optional[Dict[str, Any]]:\n    \"\"\"One JSON-mode chat call; parsed object or None (never raises).\"\"\"\n    runtime = _runtime()\n    if not runtime.get(\"enabled\") or not runtime.get(\"api_key\"):\n        return None\n    if _gated():\n        return None\n    payload = {\n        \"model\": runtime.get(\"model\") or MODEL,\n        \"messages\": [\n            {\"role\": \"system\", \"content\": system},\n            {\"role\": \"user\", \"content\": user},\n        ],\n        \"temperature\": 0,\n        \"max_tokens\": max_tokens,\n        \"response_format\": {\"type\": \"json_object\"},\n    }\n    headers = {\n        \"Authorization\": \"Bearer \" + str(runtime[\"api_key\"]),\n        \"Content-Type\": \"application/json\",\n    }\n    base = str(runtime.get(\"base_url\") or BASE_URL).rstrip(\"/\")\n    model = str(payload[\"model\"])\n    started = time.time()\n    last_usage = None\n    for _ in range(ATTEMPTS):\n        data = _http_post_json(base + \"/chat/completions\", headers, payload)\n        if not data:\n            continue\n        last_usage = data.get(\"usage\") if isinstance(data, dict) else None\n        try:\n            content = data[\"choices\"][0][\"message\"][\"content\"]\n            parsed = json.loads(content)\n        except Exception:\n            continue\n        if isinstance(parsed, dict):\n            _record_usage(model, last_usage, True, started)\n            return parsed\n    _record_usage(model, last_usage, False, started)\n    return None\n\n\n# ---------------------------------------------------------------------------\n# Embeddings (D1 knowledge semantic index) - same OpenAI-compatible contract\n# ---------------------------------------------------------------------------\n\nEMBED_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_EMBED_TIMEOUT_SECONDS\", \"20\") or 20)\nEMBED_MAX_INPUTS = max(1, min(256, int(\n    os.environ.get(\"OF_EMBED_BATCH\", \"32\") or 32)))\nEMBED_TEXT_CHARS = max(200, int(\n    os.environ.get(\"OF_EMBED_TEXT_CHARS\", \"2000\") or 2000))\n\n\ndef embed_runtime() -> Dict[str, Any]:\n    \"\"\"Effective embedding config (platform_settings.embed_config);\n    inactive on any error.\"\"\"\n    try:\n        import platform_settings\n        return platform_settings.embed_config()\n    except Exception:\n        return {\"active\": False, \"reason\": \"no_key\", \"api_key\": \"\",\n                \"base_url\": BASE_URL, \"model\": \"\", \"dimensions\": 0,\n                \"min_similarity\": 0.3, \"mode\": \"on\", \"key_source\": \"none\"}\n\n\ndef normalize_vector(values: Any) -> Optional[List[float]]:\n    \"\"\"L2-normalise (needed for Matryoshka-truncated vectors, harmless for\n    the rest) so cosine similarity becomes a plain dot product.\"\"\"\n    try:\n        vector = [float(v) for v in values]\n    except Exception:\n        return None\n    if not vector:\n        return None\n    norm = math.sqrt(sum(v * v for v in vector))\n    if not norm or math.isnan(norm):\n        return None\n    return [v / norm for v in vector]\n\n\ndef _post_detail(url: str, headers: Dict[str, str], payload: Dict[str, Any],\n                 timeout: float) -> Tuple[Optional[Dict[str, Any]], str]:\n    \"\"\"POST JSON -> (body, \"\") or (None, short error) - never raises.\"\"\"\n    try:\n        request = urllib.request.Request(\n            url, data=json.dumps(payload).encode(\"utf-8\"), headers=headers,\n            method=\"POST\")\n        with urllib.request.urlopen(request, timeout=timeout) as resp:\n            return json.loads(resp.read().decode(\"utf-8\")), \"\"\n    except urllib.error.HTTPError as error:\n        detail = \"\"\n        try:\n            body = json.loads(error.read().decode(\"utf-8\") or \"{}\")\n            err = body.get(\"error\") if isinstance(body, dict) else None\n            if isinstance(err, dict):\n                detail = str(err.get(\"message\") or \"\")\n            elif isinstance(body, list) and body and isinstance(body[0], dict):\n                detail = str((body[0].get(\"error\") or {}).get(\"message\") or \"\")\n        except Exception:\n            detail = \"\"\n        return None, (\"HTTP \" + str(error.code)\n                      + (\": \" + detail[:160] if detail else \"\"))\n    except Exception as error:\n        return None, type(error).__name__ + \": \" + str(error)[:120]\n\n\ndef embed_texts(texts: List[str], timeout: Optional[float] = None,\n                runtime: Optional[Dict[str, Any]] = None\n                ) -> Tuple[Optional[List[List[float]]], str]:\n    \"\"\"Embed up to EMBED_MAX_INPUTS texts in one call.\n\n    Returns (normalised vectors in input order, \"\") or (None, reason).\n    Honours the platform AI gate (kill switch / daily cap) and writes one\n    usage-ledger row under the caller's usage_scope. Never raises.\"\"\"\n    items = [str(t or \"\")[:EMBED_TEXT_CHARS] for t in (texts or [])]\n    if not items:\n        return [], \"\"\n    if len(items) > EMBED_MAX_INPUTS:\n        return None, \"too many inputs for one call\"\n    config = runtime or embed_runtime()\n    if not config.get(\"active\") or not config.get(\"api_key\"):\n        return None, \"embeddings not configured (\" + str(\n            config.get(\"reason\") or \"no_key\") + \")\"\n    if _gated():\n        return None, \"blocked by the platform AI controls\"\n    model = str(config.get(\"model\") or \"\")\n    payload: Dict[str, Any] = {\"model\": model, \"input\": items}\n    dims = int(config.get(\"dimensions\") or 0)\n    if dims > 0:\n        payload[\"dimensions\"] = dims\n    headers = {\n        \"Authorization\": \"Bearer \" + str(config[\"api_key\"]),\n        \"Content-Type\": \"application/json\",\n    }\n    base = str(config.get(\"base_url\") or BASE_URL).rstrip(\"/\")\n    started = time.time()\n    data, error = _post_detail(base + \"/embeddings\", headers, payload,\n                               float(timeout or EMBED_TIMEOUT_SECONDS))\n    usage = data.get(\"usage\") if isinstance(data, dict) else None\n    if not isinstance(data, dict):\n        _record_usage(model, usage, False, started)\n        return None, error or \"no response\"\n    rows = data.get(\"data\")\n    if not isinstance(rows, list) or len(rows) != len(items):\n        _record_usage(model, usage, False, started)\n        return None, \"unexpected embeddings response\"\n    try:\n        ordered = sorted(rows, key=lambda r: int(r.get(\"index\", 0)))\n    except Exception:\n        ordered = rows\n    vectors: List[List[float]] = []\n    for row in ordered:\n        vector = normalize_vector((row or {}).get(\"embedding\") or [])\n        if vector is None:\n            _record_usage(model, usage, False, started)\n            return None, \"empty embedding in response\"\n        vectors.append(vector)\n    if len({len(v) for v in vectors}) != 1:\n        _record_usage(model, usage, False, started)\n        return None, \"inconsistent embedding sizes\"\n    _record_usage(model, usage, True, started)\n    return vectors, \"\"\n\n");
writeNewRepair("app/admin/(panel)/integrations/IntegrationsClient.tsx", "hint: \"Blank = gemini-embedding-001 on Gemini, text-embedding-3-small elsewhere.\",", false,
    "\"use client\";\n\nimport { useCallback, useEffect, useState } from \"react\";\n\ntype GroupKey =\n  | \"email\"\n  | \"llm\"\n  | \"flags\"\n  | \"voice\"\n  | \"video\"\n  | \"payments\"\n  | \"whatsapp_e2e\"\n  | \"stt\"\n  | \"embeddings\";\n\ntype Field = {\n  key: string;\n  label: string;\n  secret?: boolean;\n  placeholder?: string;\n  hint?: string;\n};\n\ntype GroupDef = {\n  id: GroupKey;\n  title: string;\n  description: string;\n  fields?: Field[];\n  toggles?: { key: string; label: string; hint: string }[];\n  note?: string;\n  actions?: (\"test\" | \"weekly\")[];\n};\n\nconst GROUPS: GroupDef[] = [\n  {\n    id: \"email\",\n    title: \"Email (SMTP / Brevo)\",\n    description:\n      \"Password-reset codes and the weekly report are parked on these keys.\",\n    fields: [\n      {\n        key: \"provider\",\n        label: \"Provider\",\n        placeholder: \"smtp\",\n        hint: \"smtp or brevo\",\n      },\n      { key: \"smtp_host\", label: \"SMTP host\", placeholder: \"smtp-relay.brevo.com\" },\n      { key: \"smtp_port\", label: \"SMTP port\", placeholder: \"587\" },\n      { key: \"smtp_user\", label: \"SMTP user\" },\n      { key: \"smtp_password\", label: \"SMTP password\", secret: true },\n      {\n        key: \"smtp_from\",\n        label: \"From address\",\n        placeholder: \"OmniFlow <no-reply@yourdomain.com>\",\n      },\n      { key: \"brevo_api_key\", label: \"Brevo API key\", secret: true },\n      {\n        key: \"reports_to\",\n        label: \"Reports to\",\n        placeholder: \"owner@yourdomain.com\",\n        hint: \"Where the weekly report lands\",\n      },\n    ],\n    actions: [\"test\", \"weekly\"],\n  },\n  {\n    id: \"llm\",\n    title: \"AI engine\",\n    description:\n      \"Any OpenAI-compatible endpoint. Powers drafts, intents and the AI switches below.\",\n    fields: [\n      { key: \"base_url\", label: \"Base URL\", placeholder: \"https://api.openai.com/v1\" },\n      { key: \"api_key\", label: \"API key\", secret: true },\n      { key: \"model\", label: \"Model\", placeholder: \"gpt-4o-mini\" },\n      {\n        key: \"prices_json\",\n        label: \"Model prices (JSON, USD per 1M tokens)\",\n        placeholder: '{\"gpt-4o-mini\": {\"input\": 0.15, \"output\": 0.6}, \"default\": {\"input\": 1, \"output\": 2}}',\n        hint: \"Used by the AI operations card to estimate spend. Leave blank to show tokens only.\",\n      },\n    ],\n  },\n  {\n    id: \"stt\",\n    title: \"Speech-to-Text (voice notes)\",\n    description:\n      \"Transcribes WhatsApp voice notes for the media library. Works with any OpenAI-compatible endpoint. Saving takes effect immediately - no redeploy needed.\",\n    fields: [\n      { key: \"api_key\", label: \"API key\", secret: true },\n      { key: \"base_url\", label: \"Base URL\", placeholder: \"https://api.openai.com/v1\" },\n      { key: \"model\", label: \"Model\", placeholder: \"whisper-1\" },\n    ],\n  },\n  {\n    id: \"embeddings\",\n    title: \"Knowledge semantic search (embeddings)\",\n    description:\n      \"Lets the assistant find knowledge by meaning, not only by exact words. Works with any OpenAI-compatible /embeddings endpoint. Leave the key and base URL blank to reuse the AI engine above. Saving takes effect immediately - no redeploy needed.\",\n    fields: [\n      {\n        key: \"mode\",\n        label: \"Mode\",\n        placeholder: \"on\",\n        hint: \"on or off. Off keeps keyword-only retrieval.\",\n      },\n      {\n        key: \"api_key\",\n        label: \"API key\",\n        secret: true,\n        hint: \"Blank = reuse the AI engine key.\",\n      },\n      {\n        key: \"base_url\",\n        label: \"Base URL\",\n        placeholder: \"https://api.openai.com/v1\",\n        hint: \"Blank = reuse the AI engine base URL.\",\n      },\n      {\n        key: \"model\",\n        label: \"Model\",\n        placeholder: \"text-embedding-3-small\",\n        hint: \"Blank = gemini-embedding-001 on Gemini, text-embedding-3-small elsewhere.\",\n      },\n      {\n        key: \"dimensions\",\n        label: \"Dimensions\",\n        placeholder: \"256\",\n        hint: \"0 = provider default. Changing model or dimensions rebuilds the index automatically.\",\n      },\n      {\n        key: \"min_similarity\",\n        label: \"Minimum similarity (%)\",\n        placeholder: \"30\",\n        hint: \"Blank = 60 for Gemini models, 30 for others. Raise it if unrelated sections show up.\",\n      },\n    ],\n    note:\n      \"Workspaces see index progress under Knowledge base. Every embedding call goes through the AI kill switch and daily cap, and is billed to the Knowledge semantic index line in AI usage.\",\n  },\n  {\n    id: \"flags\",\n    title: \"AI switches\",\n    description:\n      \"Flip these once the AI key above is saved \u2014 true sentiment powers the Assist card's sentiment (an 'AI' tag marks LLM results), and KB auto-draft ships a saveable knowledge-base entry with every draft.\",\n    toggles: [\n      {\n        key: \"true_sentiment\",\n        label: \"True sentiment (LLM)\",\n        hint: \"The sentiment endpoint classifies with the AI engine instead of the word list.\",\n      },\n      {\n        key: \"kb_autodraft\",\n        label: \"KB auto-draft\",\n        hint: \"Answer drafts also ship a saveable knowledge-base entry.\",\n      },\n      {\n        key: \"phone_verification\",\n        label: \"Phone verification (Ph9)\",\n        hint: \"The switch the phone-verification feature will read when it ships.\",\n      },\n    ],\n  },\n  {\n    id: \"voice\",\n    title: \"Voice channel\",\n    description: \"Twilio credentials for the voice channel (keys ready before launch).\",\n    fields: [\n      { key: \"provider\", label: \"Provider\", placeholder: \"twilio\" },\n      { key: \"account_sid\", label: \"Account SID\" },\n      { key: \"auth_token\", label: \"Auth token\", secret: true },\n      { key: \"from_number\", label: \"From number\", placeholder: \"+92300...\" },\n    ],\n    note:\n      \"The conversation Call button dials through Twilio with these keys.\",\n  },\n  {\n    id: \"video\",\n    title: \"Video channel\",\n    description: \"Meeting-link provider for the video channel.\",\n    fields: [\n      { key: \"provider\", label: \"Provider\", placeholder: \"whereby / daily / zoom\" },\n      { key: \"api_key\", label: \"Whereby / Daily API key\", secret: true },\n      { key: \"zoom_account_id\", label: \"Zoom account id\" },\n      { key: \"zoom_client_id\", label: \"Zoom client id\" },\n      { key: \"zoom_client_secret\", label: \"Zoom client secret\", secret: true },\n    ],\n    note:\n      \"Whereby/Daily need the API key; Zoom needs the three OAuth fields. The conversation Video invite button uses these.\",\n  },\n  {\n    id: \"payments\",\n    title: \"Payments channel\",\n    description:\n      \"Platform payment-processor keys. (Per-workspace JazzCash/Easypaisa live in the portal settings.)\",\n    fields: [\n      { key: \"provider\", label: \"Provider\", placeholder: \"stripe\" },\n      { key: \"publishable_key\", label: \"Publishable key\" },\n      { key: \"secret_key\", label: \"Secret key\", secret: true },\n      { key: \"webhook_secret\", label: \"Webhook secret\", secret: true },\n    ],\n    note:\n      \"Legacy gateway key \u2014 workspaces pay through Pakistan gateways (JazzCash / Easypaisa) with their own keys in Settings > Payments. This platform key stays unused unless the legacy Stripe path is re-enabled in code.\",\n  },\n  {\n    id: \"whatsapp_e2e\",\n    title: \"WhatsApp E2E test\",\n    description:\n      \"The live number the laptop end-to-end run should message. Save it here so the runbook picks it up.\",\n    fields: [\n      { key: \"live_number\", label: \"Live test number\", placeholder: \"+92300...\" },\n    ],\n  },\n];\n\ntype Values = Record<string, Record<string, string>>;\ntype Configured = Record<string, boolean>;\n\nfunction fieldInputType(field: Field, value: string): string {\n  if (field.secret && !value.startsWith(\"\\u2022\")) return \"password\";\n  return \"text\";\n}\n\nexport default function IntegrationsClient() {\n  const [values, setValues] = useState<Values>({});\n  const [configured, setConfigured] = useState<Configured>({});\n  const [loading, setLoading] = useState(true);\n  const [busyGroup, setBusyGroup] = useState<string>(\"\");\n  const [notice, setNotice] = useState<{ group: string; text: string; ok: boolean } | null>(\n    null\n  );\n\n  const load = useCallback(async () => {\n    setLoading(true);\n    try {\n      const response = await fetch(\"/api/omniflow/admin/providers\", {\n        cache: \"no-store\",\n      });\n      const payload = await response.json().catch(() => null);\n      if (response.ok && payload && payload.groups) {\n        const next: Values = {};\n        const nextConfigured: Configured = {};\n        for (const def of GROUPS) {\n          const group = payload.groups[def.id] || {};\n          const row: Record<string, string> = {};\n          for (const field of def.fields || []) {\n            row[field.key] = String(group[field.key] ?? \"\");\n          }\n          next[def.id] = row;\n          nextConfigured[def.id] = Boolean(group.configured);\n        }\n        setValues(next);\n        setConfigured(nextConfigured);\n      }\n    } catch {\n      // keep whatever is on screen\n    } finally {\n      setLoading(false);\n    }\n  }, []);\n\n  useEffect(() => {\n    void load();\n  }, [load]);\n\n  function update(group: GroupKey, key: string, value: string) {\n    setValues((prev) => ({\n      ...prev,\n      [group]: { ...(prev[group] || {}), [key]: value },\n    }));\n  }\n\n  async function save(def: GroupDef) {\n    setBusyGroup(def.id);\n    setNotice(null);\n    try {\n      const response = await fetch(\"/api/omniflow/admin/providers\", {\n        method: \"PUT\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ group: def.id, values: values[def.id] || {} }),\n      });\n      const payload = await response.json().catch(() => null);\n      if (response.ok && payload && payload.ok) {\n        const kept = Array.isArray(payload.kept_blank) ? payload.kept_blank : [];\n        setNotice({\n          group: def.id,\n          ok: true,\n          text:\n            \"Saved.\" +\n            (kept.length ? \" Left \" + kept.join(\", \") + \" unchanged (blank).\" : \"\"),\n        });\n        await load();\n      } else {\n        setNotice({\n          group: def.id,\n          ok: false,\n          text: payload && payload.error ? payload.error.message : \"Could not save \u2014 try again.\",\n        });\n      }\n    } catch {\n      setNotice({ group: def.id, ok: false, text: \"Could not save \u2014 try again.\" });\n    } finally {\n      setBusyGroup(\"\");\n    }\n  }\n\n  async function action(def: GroupDef, kind: \"test\" | \"weekly\") {\n    setBusyGroup(def.id + \":\" + kind);\n    setNotice(null);\n    try {\n      const to = (values[def.id] || {}).reports_to || \"\";\n      const response = await fetch(\n        kind === \"test\"\n          ? \"/api/omniflow/admin/providers/email-test\"\n          : \"/api/omniflow/admin/providers/weekly-report\",\n        {\n          method: \"POST\",\n          headers: { \"Content-Type\": \"application/json\" },\n          body: JSON.stringify({ to }),\n        }\n      );\n      const payload = await response.json().catch(() => null);\n      if (response.ok && payload && payload.ok) {\n        setNotice({\n          group: def.id,\n          ok: true,\n          text:\n            kind === \"test\"\n              ? \"Test email sent \u2014 check the inbox.\"\n              : \"Weekly report sent\" +\n                (payload.clients ? \" for \" + payload.clients + \" workspace(s).\" : \".\"),\n        });\n      } else {\n        setNotice({\n          group: def.id,\n          ok: false,\n          text: payload && payload.error ? payload.error.message : \"Could not send \u2014 try again.\",\n        });\n      }\n    } catch {\n      setNotice({ group: def.id, ok: false, text: \"Could not send \u2014 try again.\" });\n    } finally {\n      setBusyGroup(\"\");\n    }\n  }\n\n  return (\n    <div className=\"space-y-6\">\n      {loading ? (\n        <div className=\"rounded-2xl border border-line bg-white shadow-card p-6 text-sm text-ink-3\">\n          Loading integration settings\u2026\n        </div>\n      ) : null}\n      {GROUPS.map((def) => {\n        const groupValues = values[def.id] || {};\n        const isOn = configured[def.id];\n        return (\n          <div\n            key={def.id}\n            className=\"rounded-2xl border border-line bg-white shadow-card p-6\"\n          >\n            <div className=\"mb-1 flex items-center justify-between gap-3\">\n              <h2 className=\"text-sm font-semibold text-ink\">{def.title}</h2>\n              <span\n                className={\n                  \"rounded-md border px-2 py-0.5 text-[10px] \" +\n                  (isOn\n                    ? \"border-emerald-400/25 bg-emerald-400/[0.08] text-ok\"\n                    : \"border-line bg-soft text-ink-3\")\n                }\n              >\n                {isOn ? \"Saved\" : \"Not set\"}\n              </span>\n            </div>\n            <p className=\"mb-5 text-xs text-ink-3\">{def.description}</p>\n\n            {(def.fields || []).length > 0 ? (\n              <div className=\"grid gap-4 sm:grid-cols-2\">\n                {(def.fields || []).map((field) => (\n                  <label key={field.key} className=\"block\">\n                    <span className=\"mb-1 block text-[11px] font-medium text-ink-2\">\n                      {field.label}\n                    </span>\n                    <input\n                      type={fieldInputType(field, groupValues[field.key] || \"\")}\n                      value={groupValues[field.key] || \"\"}\n                      onChange={(event) =>\n                        update(def.id, field.key, event.target.value)\n                      }\n                      placeholder={field.placeholder}\n                      autoComplete=\"off\"\n                      className=\"w-full rounded-xl border border-line bg-soft px-3 py-2 text-sm text-ink placeholder:text-ink-3 focus:border-brand/40 focus:outline-none\"\n                    />\n                    {field.hint ? (\n                      <span className=\"mt-1 block text-[10px] text-ink-3\">\n                        {field.hint}\n                      </span>\n                    ) : null}\n                  </label>\n                ))}\n              </div>\n            ) : null}\n\n            {def.toggles ? (\n              <div className=\"space-y-3\">\n                {def.toggles.map((toggle) => (\n                  <label\n                    key={toggle.key}\n                    className=\"flex items-start gap-3 rounded-xl border border-line bg-white shadow-card px-4 py-3\"\n                  >\n                    <input\n                      type=\"checkbox\"\n                      checked={(groupValues[toggle.key] || \"\") === \"on\"}\n                      onChange={(event) =>\n                        update(\n                          def.id,\n                          toggle.key,\n                          event.target.checked ? \"on\" : \"off\"\n                        )\n                      }\n                      className=\"mt-0.5 h-4 w-4 accent-cyan-400\"\n                    />\n                    <span>\n                      <span className=\"block text-sm text-ink\">\n                        {toggle.label}\n                      </span>\n                      <span className=\"block text-[11px] text-ink-3\">\n                        {toggle.hint}\n                      </span>\n                    </span>\n                  </label>\n                ))}\n              </div>\n            ) : null}\n\n            {def.note ? (\n              <p className=\"mt-4 text-[11px] text-ink-3\">{def.note}</p>\n            ) : null}\n\n            <div className=\"mt-5 flex flex-wrap items-center gap-2\">\n              <button\n                onClick={() => void save(def)}\n                disabled={busyGroup === def.id}\n                className=\"rounded-xl border border-brand/30 bg-brand-soft px-4 py-2 text-xs font-medium text-brand transition-colors hover:bg-brand-soft disabled:opacity-50\"\n              >\n                {busyGroup === def.id ? \"Saving\u2026\" : \"Save\"}\n              </button>\n              {def.actions?.includes(\"test\") ? (\n                <button\n                  onClick={() => void action(def, \"test\")}\n                  disabled={busyGroup === def.id + \":test\"}\n                  className=\"rounded-xl border border-line bg-white shadow-card px-4 py-2 text-xs text-ink-2 transition-colors hover:bg-white/[0.06] disabled:opacity-50\"\n                >\n                  {busyGroup === def.id + \":test\" ? \"Sending\u2026\" : \"Send test email\"}\n                </button>\n              ) : null}\n              {def.actions?.includes(\"weekly\") ? (\n                <button\n                  onClick={() => void action(def, \"weekly\")}\n                  disabled={busyGroup === def.id + \":weekly\"}\n                  className=\"rounded-xl border border-line bg-white shadow-card px-4 py-2 text-xs text-ink-2 transition-colors hover:bg-white/[0.06] disabled:opacity-50\"\n                >\n                  {busyGroup === def.id + \":weekly\"\n                    ? \"Sending\u2026\"\n                    : \"Send weekly report now\"}\n                </button>\n              ) : null}\n              {notice && notice.group === def.id ? (\n                <span\n                  className={\n                    \"text-[11px] \" + (notice.ok ? \"text-ok\" : \"text-danger\")\n                  }\n                >\n                  {notice.text}\n                </span>\n              ) : null}\n            </div>\n          </div>\n        );\n      })}\n    </div>\n  );\n}\n");
